TURATH_CHUNK(38,[{"num":7600,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ حَزْمٍ الأنصاري قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ لَمْ يَسْتَرْعِ عَبْدًا رَعِيَّةً إِلَّا وَهُوَ سَائِلُهُ عَنْهَا يَوْمَ الْقِيَامَةِ: كَيْفَ صَنَعَ فِيهَا."],"takhrij":"حسن: رواه أبو يعلى (7174) عن الحسن بن عمر بن شقيق بن أسماء الجرمي، حدثنا جعفر، عن هشام، عن محمد بن سيرين فذكر زيارة عمرو بن حزم الأنصاري لمعاوية بن أبي سفيان عندما استخلف ابنه يزيد بن أبي معاوية في قصة طويلة، وذكر أن عمرو بن حزم حدّث بهذا الحديث عند معاوية.","grade":"حسن","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (7174).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAmr ibn Hazm al-Ansari said: I heard the Messenger of Allah ﷺ say: “Allah does not place a servant in charge of a people except that He will ask him about them on the Day of Resurrection: how did he deal with them?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (7174)."},{"num":7601,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  صِنْفَانِ مِنْ أُمَّتِي لَا تَنَالُهُمَا شَفَاعَتِي ولَنْ تَنَالَهُمَا شَفَاعَتِي، أَوْ لَنْ أَشْفَعَ لَهُمَا: أَمِيرٌ ظَلُومٌ غَشُومٌ عَسُوفٌ، وَكُلُّ غَالٍ مَارِقٍ."],"takhrij":"حسن: رواه مسدد (2157- المطالب) عن جعفر بن سليمان، عن المعلى، عن أبي غالب، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Musaddad (al-Matalib, 2157) and al-Tabarani (8/337).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Umamah said: The Messenger of Allah ﷺ said: “Two types from my nation will not receive my intercession, or I will not intercede for them: an unjust, oppressive, tyrannical ruler, and every extremist who leaves the religion.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مسدد (المطالب 2157)، والطبراني (8/337)."},{"num":7602,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَرْيَمَ الأزدى أَخْبَرَهُ قَالَ: دَخَلْتُ عَلَى مُعَاوِيَةَ، فَقَالَ: مَا أَنْعَمَنَا بِكَ أَبَا فُلاَنٍ. وهى كَلِمَةٌ تَقُولُهَا الْعَرَبُ، فَقُلْتُ: حَدِيثًا سَمِعْتُهُ أُخْبِرُكَ بِهِ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ وَلاَّهُ اللَّهُ عَزَّ وَجَلَّ شَيْئًا مِنْ أَمْرِ الْمُسْلِمِينَ، فَاحْتَجَبَ دُونَ حَاجَتِهِمْ وَخَلَّتِهِمْ وَفَقْرِهِمُ احْتَجَبَ اللَّهُ عَنْهُ دُونَ حَاجَتِهِ وَخَلَّتِهِ وَفَقْرِهِ.","قال: فجعل رجلا على حوائج الناس."],"takhrij":"صحيح: رواه أبو داود ( 2948)، والترمذي (1333)، والحاكم (4/93-94) كلهم من حديث يزيد بن أبي مريم، أن القاسم بن مخيمرة أخبره، أن أبا مريم الأزدي أخبره فذكر الحديث واللفظ لأبي داود. وسكت عليه الترمذي.","grade":"صحيح","chapter_ar":"باب الترغيب في أن يكون الإمام مهتماً بأمور رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2948), al-Tirmidhi (1333), and al-Hakim (4/93–94). The wording is from Abu Dawud.","chapter_en":"Encouragement for the Leader to Be Concerned with the Affairs of His Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Maryam al-Azdi said: I entered upon Muʿawiyah, and he said: “How pleasant your visit is, Abu so-and-so.” This is an expression used by the Arabs. I said: “I will inform you of a hadith I heard. I heard the Messenger of Allah ﷺ say: ‘Whoever Allah, the Mighty and Majestic, appoints over any matter of the Muslims, then he blocks himself from their needs, their poverty, and their hardship, Allah will block Himself from his need, his poverty, and his hardship.’” He said: So Muʿawiyah appointed a man to handle the needs of the people."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2948)، والترمذي (1333)، والحاكم (4/93-94)، واللفظ لأبي داود."},{"num":7603,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أُعْطِيكُمْ وَلاَ أَمْنَعُكُمْ، أَنَا قَاسِمٌ أَضَعُ حَيْثُ أُمِرْتُ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3117) عن محمد بن سنان، حدثنا فُليح، حدثنا هلال، عن عبد الرحمن بن عمرة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ولي الأمر يقدر أرزاق الولاة والعمال","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3117).","chapter_en":"The Ruler Determines the Stipends of Governors and Workers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “I neither give you nor withhold from you by myself. I am only a distributor; I place it where I have been commanded.”"]}},"tuhfa":{},"full":1,"rep":[8026],"tks":"صحيح: رواه البخاري (3117)."},{"num":7604,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الْعَاصِ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنِّي أُرِيدُ أَنْ أَبْعَثَكَ عَلَى جَيْشٍ، فَيُسَلِّمَكَ اللهُ، وَيُغْنِمَكَ، وأرغب لَكَ مِنَ الْمَالِ رَغْبَةً صَالِحَةً، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ مَا أَسْلَمْتُ مِنْ أَجْلِ الْمَالِ، وَلَكِنِّي أَسْلَمْتُ رَغْبَةً فِي الْإِسْلَامِ، وَأَنْ أَكُونَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : نِعْمًا بِالْمَالِ الصَّالِحُ لِلرَّجُلِ الصَّالِحِ."],"takhrij":"صحيح: رواه أحمد (17763)، والطبراني في الأوسط (3213)، والحاكم (2926) كلهم من طريق موسى بن عُلَيّ بن رباح، عن أبيه قال: سمعت عمرو بن العاص فذكره. وإسناده صحيح. قال الحاكم: \"صحيح على شرط مسلم\".","grade":"صحيح","chapter_ar":"باب ولي الأمر يقدر أرزاق الولاة والعمال","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (17763), al-Tabarani in al-Awsat (3213), and al-Hakim (2926).","chapter_en":"The Ruler Determines the Stipends of Governors and Workers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said to me: “I want to send you over an army, so Allah will keep you safe and grant you spoils, and I desire for you a good share of wealth.” He said: I said: “O Messenger of Allah, I did not embrace Islam for wealth. Rather, I embraced Islam out of desire for Islam and to be with the Messenger of Allah ﷺ.” The Messenger of Allah ﷺ said: “How excellent is righteous wealth for a righteous man.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (17763)، والطبراني في الأوسط (3213)، والحاكم (2926)."},{"num":7605,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عَبْدَ الرَّحْمَنِ لاَ تَسْأَلِ الإِمَارَةَ، فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا، وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا، وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَكَفِّرْ يَمِينَكَ، وَأْتِ الَّذِي هُوَ خَيْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7146)، ومسلم في الإمارة (1652: 13) كلاهما من طريق جرير بن حازم، حدثنا الحسن، حدثنا عبد الرحمن بن سمرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7146) and Muslim (1652:13).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Samurah said: The Prophet ﷺ said to me: “O ʿAbd al-Rahman ibn Samurah, do not ask for leadership. If you are given it because of asking, you will be left to it; but if you are given it without asking, you will be helped in it. And if you swear an oath, then see something else better than it, expiate your oath and do what is better.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7146)، ومسلم (1652:13)."},{"num":7606,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: أَقْبَلْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعِي رَجُلاَنِ مِنَ الأَشْعَرِيِّينَ، أَحَدُهُمَا عَنْ يَمِينِي، وَالآخَرُ عَنْ يَسَارِي، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَاكُ فَكِلاَهُمَا سَأَلَ الْعَمَلَ والنبي صَلَّى اللَّهِ عَلَيْهِ وَسَلَّمَ يَسْتَاكُ، فَقَالَ:  مَا تَقُولُ: يَا أَبَا مُوسَى أَوْ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ؟ فَقُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا، وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ. وكأني أَنْظُرُ إِلَى سِوَاكِهِ تَحْتِ شَفَتِهِ وَقَدْ قَلَصَتْ، فَقَالَ: لَنْ -أَوْ- لاَ نَسْتَعْمِلُ عَلَى عَمَلِنَا مَنْ أَرَادَهُ، وَلَكِنِ اذْهَبْ أَنْتَ يَا أَبَا مُوسَى أَوْ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ فبعثه عَلَى الْيَمَنِ، ثُمَّ أَتْبَعَهُ مُعَاذُ بْنُ جَبَلٍ، فَلَمَّا قَدِمَ عَلَيْهِ قَالَ: انْزِلْ، وألقى لَهُ وِسَادَةً، وَإِذَا رَجُلٌ عِنْدَهُ مُوثَقٌ قَالَ: مَا هَذَا؟ قَالَ: هذاكان يَهُودِيًّا فَأَسْلَمَ ثُمَّ راجع دينه دين السوء فتهود، قَالَ: لاَ أجلس حَتَّى يُقْتَلَ، قَضَاءُ اللَّهِ وَرَسُولِهِ، فَقَالَ: اجْلِسْ، نَعَمْ، قَالَ: لاَ أَجْلِسُ حَتَّى يُقْتَلَ، قَضَاءُ اللَّهِ وَرَسُولِهِ -ثَلاَثَ مَرَّاتٍ- فَأَمَرَ بِهِ، فقُتلَ. ثُمَّ تذاكرا القيام من اللَّيْلِ فَقَالَ: أَحَدُهُمَا -مُعَاذُ- أَمَّا أَنَا فأنام وأقوم، وَأَرْجُو فِي نَوْمَتِي مَا أَرْجُو فِي قَوْمَتِي."],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدين (6923)، ومسلم في الإمارة (1733: 15) كلاهما من طريق يحيى القطان، حدثنا قرة بن خالد، حدثنا حميد بن هلال، حدثني أبو بردة قال: قال أبو موسى فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6923) and Muslim (1733:15). The wording is from Muslim.","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Musa said: I came to the Prophet ﷺ with two men from the Ashʿaris, one on my right and the other on my left, while the Messenger of Allah ﷺ was brushing his teeth. Both of them asked for an official position while the Prophet ﷺ was brushing his teeth. He said: “What do you say, Abu Musa, or ʿAbdullah ibn Qays?” I said: “By the One who sent you with the truth, they did not inform me of what was in their hearts, and I did not know that they were seeking office.” It is as if I can still see his tooth-stick beneath his lip, which had drawn back. He said: “We will never — or we do not — appoint to our work one who desires it. But you, Abu Musa, or ʿAbdullah ibn Qays, go to Yemen.” Then he sent Muʿadh ibn Jabal after him. When Muʿadh came to him, he said: “Dismount,” and he placed a cushion for him. There was a man bound with him. Muʿadh said: “What is this?” He said: “This man was a Jew, then he embraced Islam, then he returned to his evil religion and became a Jew again.” Muʿadh said: “I will not sit until he is killed, as the judgment of Allah and His Messenger.” He said: “Sit.” He said: “Yes, but I will not sit until he is killed, as the judgment of Allah and His Messenger.” He said this three times. So he ordered that he be killed. Then they discussed standing in prayer at night. One of them, Muʿadh, said: “As for me, I sleep and I stand, and I hope for reward in my sleep as I hope for reward in my standing.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6923)، ومسلم (1733:15). والسياق لمسلم."},{"num":7607,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَرَجُلاَنِ مِنْ قَوْمِي فَقَالَ أَحَدُ الرَّجُلَيْنِ: أَمِّرْنَا يَا رَسُولَ اللَّهِ. وَقَالَ الآخَرُ: مِثْلَهُ. فَقَالَ: إِنَّا لاَ نُوَلِّي هَذَا مَنْ سَأَلَهُ، وَلاَ مَنْ حَرَصَ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7149)، ومسلم في الإمارة (1733: 14) كلاهما عن محمد بن العلاء، حدثنا أبو أسامة، عن بريد، عن أبي بردة، عن أبي موسى قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7149) and Muslim (1733:14).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Musa said: I entered upon the Prophet ﷺ with two men from my people. One of the two men said: “Appoint us, O Messenger of Allah.” The other said the same. He said: “We do not appoint to this matter one who asks for it, nor one who is eager for it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7149)، ومسلم (1733:14)."},{"num":7608,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّكُمْ سَتَحْرِصُونَ عَلَى الإِمَارَةِ، وَسَتَكُونُ نَدَامَةً يَوْمَ الْقِيَامَةِ، فَنِعْمَ الْمُرْضِعَةُ، وَبِئْسَتِ الْفَاطِمَةُ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7148) عن أحمد بن يونس حدثنا ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7148).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “You will be eager for leadership, but it will be regret on the Day of Resurrection. How excellent is the nursing mother, and how terrible is the weaning mother.”"]},"buhuth":{"en":["His phrase “How excellent is the nursing mother, and how terrible is the weaning mother” means: it is excellent while it provides status, wealth, authority, and sensory and imagined pleasures during its possession; but it is terrible when one is separated from it through death or otherwise, because of the consequences that follow it in the Hereafter. Fath al-Bari (13/126)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7148)."},{"num":7609,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ:  قُلْتُ: يَا رَسُولَ اللَّهِ، أَلَا تَسْتَعْمِلُنِي؟ قَالَ: فَضَرَبَ بِيَدِهِ عَلَى مَنْكِبِي، ثُمَّ قَالَ: يَا أَبَا ذَرٍّ، إِنَّكَ ضَعِيفٌ، وَإِنَّهَا أَمَانَةٌ، وَإِنَّهَا يَوْمَ الْقِيَامَةِ خِزْيٌ وَنَدَامَةٌ، إِلَّا مَنْ أَخَذَهَا بِحَقِّهَا، وَأَدَّى الَّذِي عَلَيْهِ فِيهَا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1825) عن عبد الملك بن شعيب بن الليث، حدثني أبي شعيب بن الليث، حدثني الليث بن سعد، حدثني يزيد بن أبي حبيب، عن بكر بن عمرو، عن الحارث بن يزيد الحضرمي، عن ابن حجيرة الأكبر، عن أبي ذر قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1825).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Dharr said: I said: “O Messenger of Allah, will you not appoint me?” He struck my shoulder with his hand and said: “O Abu Dharr, you are weak, and it is a trust. On the Day of Resurrection it will be disgrace and regret, except for one who takes it with its right and fulfills what is due regarding it.”"]}},"tuhfa":{},"full":1,"rep":[6725],"tks":"صحيح: رواه مسلم (1825)."},{"num":7610,"demo":false,"sanad":"","matn":["عَنْ عَوْفُ بْنُ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنْ شِئْتُمْ أَنْبَأْتُكُمْ عَنِ الإِمَارَةِ، وَمَا هِيَ؟ فَنَادَيْتُ بِأَعْلَى صَوْتِي ثَلاثَ مَرَّاتٍ: مَا هِيَ يَا رَسُولَ اللَّهِ؟ قَالَ: أَوَّلُهَا مَلامَةٌ، وَثَانِيهَا نَدَامَةٌ، وَثَالِثُهَا عَذَابٌ يَوْمَ الْقِيَامَةِ، إِلَّا مَنْ عَدَلَ، وَكَيْفَ يَعْدِلُ مَعَ أَقْرَبِيهِ."],"takhrij":"صحيح: رواه البزار (2756)، والطبراني في الكبير (18/ 132)، والأوسط (2533- مجمع البحرين) كلاهما من طرق عن صدقة بن خالد، عن زيد بن واقد، عن بُسر بن عبيدالله، عن يزيد الأصم، عن عوف بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar (2756), al-Tabarani in al-Kabir (18/132), and al-Awsat (Majmaʿ al-Bahrayn 2533).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿAwf ibn Malik narrated from the Prophet ﷺ that he said: “Shall I inform you about leadership and what it is?” I stood and called out at the top of my voice three times: “What is it, O Messenger of Allah?” He said: “Its beginning is blame, its second stage is regret, and its third stage is punishment on the Day of Resurrection, except for one who is just. But how can he be just with his relatives?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار (2756)، والطبراني في الكبير (18/132)، والأوسط (مجمع البحرين 2533)."},{"num":7611,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَا أَبَا ذَرٍّ، إِنِّي أَرَاكَ ضَعِيفًا، وَإِنِّي أُحِبُّ لَكَ مَا أُحِبُّ لِنَفْسِي، لَا تَأَمَّرَنَّ عَلَى اثْنَيْنِ، وَلَا تَوَلَّيَنَّ مَالَ يَتِيمٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1826) من طريق عبد الله بن يزيد المقرئ، حدثنا سعيد بن أبي أيوب، عن عبيد الله بن أبي جعفر القرشي، عن سالم بن أبي سالم الجيشاني، عن أبيه، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1826).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Dharr narrated that the Messenger of Allah ﷺ said: “O Abu Dharr, I see that you are weak, and I love for you what I love for myself. Do not be placed in authority over even two people, and do not take charge of an orphan’s wealth.”"]}},"tuhfa":{},"full":1,"rep":[6726,12653],"tks":"صحيح: رواه مسلم (1826)."},{"num":7612,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَادِ بْنِ الْأَسْوَدِ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَبْعَثًا، فَلَمَّا رَجَعْتُ قَالَ لِي: كَيْفَ تَجِدُ نَفْسَكَ؟ قُلْتُ: مَا زِلْتُ حَتَّى ظَنَنْتُ أَنَّ مَنْ مَعِي خَوَلًا لِي، وَايْمُ اللَّهِ لَا أَعْمَلُ عَلَى رَجُلَيْنِ بَعْدَهُمَا هَذَا."],"takhrij":"حسن: رواه النسائي في الكبرى (8695)، والطبراني في الكبير (20/ح 609)، والحاكم (5488) كلهم من طرق عن بشر بن المفضل، حدثنا عبد الله بن عون، عن عمير بن إسحاق، عن المقداد بن الأسود فذكره.","grade":"حسن","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (8695), al-Tabarani in al-Kabir (20/258–259), and al-Hakim (5488).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Miqdad ibn al-Aswad said: The Prophet ﷺ sent me on a mission. When I returned, he said to me: “How do you find yourself?” I said: “I remained in such a state that I thought I had servants belonging to me. By Allah, I will never again take charge over two men after this.”"]},"buhuth":{"en":["His phrase “servants belonging to me” means what Allah has granted a person of blessings, male servants, female servants, and the like."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في الكبرى (8695)، والطبراني في الكبير (20/ح 609)، والحاكم (5488)."},{"num":7613,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّمَا الْإِمَامُ جُنَّةٌ، يُقَاتَلُ مِنْ وَرَائِهِ وَيُتَّقَى بِهِ، فَإِنْ أَمَرَ بِتَقْوَى اللَّهِ عَزَّ وَجَلَّ وَعَدَلَ، كَانَ لَهُ بِذَلِكَ أَجْرٌ، وَإِنْ يَأْمُرْ بِغَيْرِهِ، كَانَ عَلَيْهِ مِنْهُ."],"takhrij":"متفق عليه:  رواه البخاري في الجهاد والسير (2957)، ومسلم في الإمارة (1841) كلاهما من حديث أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الإمام جُنّة يقاتل من ورائه ويتقى به","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2957) and Muslim (1841).","chapter_en":"The Leader Is a Shield Behind Whom Fighting Is Done and Through Whom Protection Is Sought","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “The leader is only a shield behind whom fighting is done and through whom protection is sought. If he commands mindfulness of Allah, the Mighty and Majestic, and acts justly, he will have reward for that. But if he commands something other than that, then it will be against him.”"]}},"tuhfa":{},"full":1,"rep":[7589],"tks":"متفق عليه: رواه البخاري (2957)، ومسلم (1841)."},{"num":7614,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  خِيَارُ أَئِمَّتِكُمُ الَّذِينَ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ، وَيُصَلُّونَ عَلَيْكُمْ وَتُصَلُّونَ عَلَيْهِمْ، وَشِرَارُ أَئِمَّتِكُمُ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ، وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ. قِيلَ: يَا رَسُولَ اللَّهِ، أَفَلَا نُنَابِذُهُمْ بِالسَّيْفِ؟ فَقَالَ: لَا، مَا أَقَامُوا فِيكُمُ الصَّلَاةَ، وَإِذَا رَأَيْتُمْ مِنْ وُلَاتِكُمْ شَيْئًا تَكْرَهُونَهُ فَاكْرَهُوا عَمَلَهُ، وَلَا تَنْزِعُوا يَدًا مِنْ طَاعَةٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1855: 65) عن إسحاق بن إبراهيم الحنظلي أخبرنا عيسى بن يونس، حدثنا الأوزاعي، عن يزيد بن يزيد بن جابر، عن رزيق بن حيان، عن مسلم بن قرظة، عن عوف بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة خيار الأئمة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1855:65).","chapter_en":"What Has Come Concerning the Description of the Best Leaders","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAwf ibn Malik narrated from the Messenger of Allah ﷺ that he said: “The best of your leaders are those whom you love and who love you, and who pray for you and for whom you pray. The worst of your leaders are those whom you hate and who hate you, and whom you curse and who curse you.” It was said: “O Messenger of Allah, should we not oppose them with the sword?” He said: “No, as long as they establish prayer among you. If you see something from your rulers that you dislike, then hate his action, but do not withdraw your hand from obedience.”"]},"intro":{"ar":["قال الله تعالى: (الَّذِينَ إِن مَّكَّنَّاهُمْ فِي الْأَرْضِ أَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنكَرِ وَلِلَّهِ عَاقِبَةُ الْأُمُورِ) [سورة الحج: ٤١]"],"en":["Allah the Exalted says: “Those who, if We establish them in the land, establish prayer, give charity, command what is right, and forbid what is wrong. And to Allah belongs the outcome of all matters.” [Surah al-Hajj: 41]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1855:65)."},{"num":7615,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكَرَةَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَكْرَمَ سُلْطَانَ اللهِ فِي الدُّنْيَا، أَكْرَمَهُ اللهُ يَوْمَ الْقِيَامَةِ، وَمَنْ أَهَانَ سُلْطَانَ اللهِ فِي الدُّنْيَا، أَهَانَهُ اللهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد ( 20433)، والترمذي (2224) كلاهما من طريق حميد بن مهران، عن سعيد بن أوس، عن زياد بن كسيب العدوي، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب إكرام السلطان","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20433) and al-Tirmidhi (2224), who graded it hasan. The wording is from Ahmad. In al-Tirmidhi, the beginning includes a story: Ziyad ibn Kusayb al-ʿAdawi said: I was with Abu Bakrah beneath the pulpit of Ibn ʿAmir while he was delivering a sermon, wearing thin garments. Abu Bilal said: “Look at our commander wearing the clothing of the wicked.” Abu Bakrah said: “Be quiet. I heard the Messenger of Allah ﷺ say: ‘Whoever humiliates Allah’s authority on earth, Allah will humiliate him.’”","chapter_en":"Honoring the Authority","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Abu Bakrah said: I heard the Messenger of Allah ﷺ say: “Whoever honors Allah’s authority in this world, Allah will honor him on the Day of Resurrection; and whoever humiliates Allah’s authority in this world, Allah will humiliate him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20433)، والترمذي (2224) وحسنه. واللفظ لأحمد. وعند الترمذي في أوله قصة: قال زياد بن كسيب العدوي: كنت مع أبي بكرة تحت منبر ابن عامر، وهو يخطب، وعليه ثياب رقاق، فقال أبو بلال: انظروا إلى أميرنا يلبس ثياب الفساق، فقال أبو بكرة: اسكت، سمعت رسول الله ﷺ يقول: (( من أهان سلطان الله في الأرض أهانه الله ))."},{"num":7616,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ قَالَ: نَزَلَتْ فِي عَبْدِ اللَّهِ بْنِ حُذَافَةَ بْنِ قَيْسِ بْنِ عَدِيٍّ إِذْ بَعَثَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4584)، ومسلم في الإمارة (1834) كلاهما من طريق حجاج بن محمد، عن ابن جريج، عن يعلى بن مسلم، عن سعيد بن جبير، عن ابن عباس قال: فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4584) and Muslim (1834). The wording is from al-Bukhari.","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said concerning the verse, “Obey Allah, obey the Messenger, and those in authority among you.” He said: It was revealed concerning ʿAbdullah ibn Hudhafah ibn Qays ibn ʿAdi when the Prophet ﷺ sent him in command of a military detachment."]},"intro":{"ar":["قال تعالى: (يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنكُمْ) [النساء: ٥٩]"],"en":["Allah the Exalted says: “O you who believe, obey Allah, obey the Messenger, and those in authority among you.” [Surah an-Nisa’: 59]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4584)، ومسلم (1834). والسياق للبخاري."},{"num":7617,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ فِي الْمَنْشَطِ وَالْمَكْرَهِ. وَأَنْ لاَ نُنَازِعَ الأَمْرَ أَهْلَهُ، وَأَنْ نَقُومَ ـ أَوْ نَقُولَ ـ بِالْحَقِّ حَيْثُمَا كُنَّا، لاَ نَخَافُ فِي اللَّهِ لَوْمَةَ لاَئِمٍ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (5) عن يحيى بن سعيد قال: أخبرني عبادة بن الوليد بن عبادة بن الصامت، عن أبيه، عن جده فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (5), al-Bukhari (7199–7200), and Muslim (1709:41).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿUbadah ibn as-Samit said: We pledged allegiance to the Messenger of Allah ﷺ to hear and obey in ease and hardship, in what we liked and disliked, and not to dispute authority with its rightful holders, and to speak — or stand for — the truth wherever we were, not fearing the blame of any blamer for the sake of Allah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (5)، والبخاري (7199-7200)، ومسلم (1709:41)."},{"num":7618,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا إِذَا بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ يَقُولُ لَنَا: فِيمَا اسْتَطَعْتَ."],"takhrij":"متفق عليه: رواه مالك في البيعة (1) عن عبد الله بن دينار أن عبد الله بن عمر فذكره. ورواه البخاري في الأحكام (7202) من طريق مالك به مثله. ورواه مسلم في الإمارة (1867) من طريق إسماعيل بن جعفر، أخبرني عبد الله بن دينار به.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (7202), and Muslim (1867).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: When we pledged allegiance to the Messenger of Allah ﷺ to hear and obey, he would say to us: “As much as you are able.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (7202)، ومسلم (1867)."},{"num":7619,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: السَّمْعُ وَالطَّاعَةُ عَلَى الْمَرْءِ الْمُسْلِمِ فِيمَا أَحَبَّ وَكَرِهَ مَا لَمْ يُؤْمَرْ بِمَعْصِيَةٍ، فَإِذَا أُمِرَ بِمَعْصِيَةٍ فَلاَ سَمْعَ وَلاَ طَاعَةَ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7144)، ومسلم في الإمارة (1839: 38) كلاهما من طريق عبيد الله، حدثني نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7144) and Muslim (1839:38).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar narrated from the Prophet ﷺ that he said: “Hearing and obeying are binding upon a Muslim in what he likes and dislikes, so long as he is not commanded to commit disobedience. If he is commanded to commit disobedience, then there is no hearing and no obedience.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7144)، ومسلم (1839:38)."},{"num":7620,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللهَ، وَمَنْ يَعْصِنِي فَقَدْ عَصَى اللَّهَ، وَمَنْ يُطِعِ الْأَمِيرَ فَقَدْ أَطَاعَنِي، وَمَنْ يَعْصِ الْأَمِيرَ فَقَدْ عَصَانِي."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2957)، ومسلم في الإمارة (1835: 32) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2957) and Muslim (1835:32). The wording is from Muslim.","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Whoever obeys me has obeyed Allah, and whoever disobeys me has disobeyed Allah. Whoever obeys the commander has obeyed me, and whoever disobeys the commander has disobeyed me.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2957)، ومسلم (1835:32). والسياق لمسلم."},{"num":7621,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْمَعُوا وَأَطِيعُوا، وَإِنِ اسْتُعْمِلَ عَلَيْكُمْ عَبْدٌ حَبَشِيٌّ كَأَنَّ رَأْسَهُ زَبِيبَةٌ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7142) عن مسدد، حدثنا يحيى بن سعيد، عن شعبة، عن أبي التيّاح، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7142).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Hear and obey, even if an Abyssinian slave whose head is like a raisin is appointed over you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7142)."},{"num":7622,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ، وَالطَّاعَةِ، فَقَالَ: فِيمَا اسْتَطَعْتُمْ."],"takhrij":"حسن: رواه ابن ماجه (2868)، وأحمد (12203) من طريق وكيع قال: حدثنا شعبة، عن عتّاب مولى ابن هرمز قال: سمعت أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2868) and Ahmad (12203).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik said: We pledged allegiance to the Messenger of Allah ﷺ to hear and obey, and he said: “As much as you are able.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2868)، وأحمد (12203)."},{"num":7623,"demo":false,"sanad":"","matn":["عن أُمِّ الْحُصَيْنِ قَالَ: سَمِعْتُهَا تَقُولُ:  حَجَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةَ الْوَدَاعِ قَالَتْ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْلًا كَثِيرًا، ثُمَّ سَمِعْتُهُ يَقُولُ: إِنْ أُمِّرَ عَلَيْكُمْ عَبْدٌ مُجَدَّعٌ حَسِبْتُهَا قَالَتْ: أَسْوَدُ يَقُودُكُمْ بِكِتَابِ اللَّهِ، فَاسْمَعُوا لَهُ وَأَطِيعُوا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1838) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل عن زيد بن أبي أنيسة، عن يحيى بن حصين، عن جدته أم الحصين فذكرته.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1838).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Umm al-Husayn said: I performed the Farewell Pilgrimage with the Messenger of Allah ﷺ. She said: The Messenger of Allah ﷺ said many things, then I heard him say: “If a mutilated slave is appointed over you — I think she said: a black slave — and he leads you by the Book of Allah, then listen to him and obey.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1838)."},{"num":7624,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ:  إِنَّ خَلِيلِي أَوْصَانِي: أَنْ أَسْمَعَ وَأُطِيعَ، وَإِنْ كَانَ عَبْدًا مُجَدَّعَ الْأَطْرَافِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1837) من طريق ابن إدريس، عن شعبة، عن أبي عمران، عن عبد الله بن الصامت، عن أبي ذر قال: فذكره.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1837).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Dharr said: My close friend advised me to listen and obey, even if he is a slave with mutilated limbs."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1837)."},{"num":7625,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن سلام، أَنَّ أَبَا سَلاَّمٍ حَدَّثَهُ أَنَّ الْحَارِثَ الأشعري حَدَّثَهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَأَنَا آمُرُكُمْ بِخَمْسٍ اللَّهُ أَمَرَنِي بِهِنَّ: السَّمْعُ، وَالطَّاعَةُ، وَالْجِهَادُ، وَالْهِجْرَةُ، وَالْجَمَاعَةُ، فَإِنَّ مَنْ فَارَقَ الْجَمَاعَةَ قِيدَ شِبْرٍ فَقَدْ خَلَعَ رِبْقَةَ الإِسْلاَمِ مِنْ عُنُقِهِ إِلاَّ أَنْ يَرْجِعَ وَمَنِ ادَّعَى دَعْوَى الْجَاهِلِيَّةِ فَإِنَّهُ مِنْ جُثَا جَهَنَّمَ فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، وَإِنْ صَلَّى وَصَامَ؟ قَالَ: وَإِنْ صَلَّى وَصَامَ فَادْعُوا بِدَعْوَى اللَّهِ الَّذِي سَمَّاكُمُ الْمُسْلِمِينَ الْمُؤْمِنِينَ عِبَادَ اللَّهِ."],"takhrij":"صحيح: رواه الترمذي (2863) عن محمد بن إسماعيل (البخاري)، حدثنا موسى بن إسماعيل، حدثنا أبان بن يزيد، حدثنا يحيى بن أبي كثير، عن زيد بن سلام أن أبا سلام حدثه فذكره بطوله. وهو مذكور في أخبار يحيى بن زكريا.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (2863), who said: “A hasan, sahih, strange hadith.”","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Zayd ibn Salam narrated that Abu Salam told him, that al-Harith al-Ashʿari told him, that the Prophet ﷺ said: “I command you with five things which Allah commanded me with: hearing, obedience, striving, migration, and the community. Whoever separates from the community by a handspan has removed the bond of Islam from his neck unless he returns. Whoever calls with the call of the pre-Islamic period is among the heaps of Hell.” A man said: “O Messenger of Allah, even if he prays and fasts?” He said: “Even if he prays and fasts. So call with the call of Allah, who named you Muslims, believers, servants of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2863)، قال الترمذي: “حديث حسن صحيح غريب”."},{"num":7626,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً، وَأَمَّرَ عَلَيْهِمْ رَجُلاً مِنَ الأَنْصَارِ، وَأَمَرَهُمْ أَنْ يُطِيعُوهُ، فَغَضِبَ عَلَيْهِمْ، وَقَالَ: أَلَيْسَ قَدْ أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ تُطِيعُونِي؟ قَالُوا: بَلَى قَالَ: قَدْ عَزَمْتُ عَلَيْكُمْ لَمَا جَمَعْتُمْ حَطَبًا، وَأَوْقَدْتُمْ نَارًا، ثُمَّ دَخَلْتُمْ فِيهَا فَجَمَعُوا حَطَبًا، فَأَوْقَدُوا نَارًا، فَلَمَّا هَمُّوا بِالدُّخُولِ، فَقَامَ يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ، قَالَ بَعْضُهُمْ: إِنَّمَا تَبِعْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِرَارًا مِنَ النَّارِ أَفَنَدْخُلُهَا؟ فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ خَمَدَتِ النَّارُ وَسَكَنَ غَضَبُهُ فَذُكِرَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَوْ دَخَلُوهَا مَا خَرَجُوا مِنْهَا أَبَدًا، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ. وَفِي رِوَايَةِ: لَا طاعة فِي معصية الله، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7145)، ومسلم في الإمارة (1840: 40) من طريق الأعمش، حدثنا سعد بن عبيدة عن أبي عبدالرحمن عن علي فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7145) and Muslim (1840:40). The other wording is from Muslim.","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAli said: The Prophet ﷺ sent a military detachment and appointed a man from the Ansar over them, and he commanded them to obey him. The commander became angry with them and said: “Did the Prophet ﷺ not command you to obey me?” They said: “Yes.” He said: “I firmly command you to gather firewood, light a fire, and then enter it.” So they gathered firewood and lit a fire. When they were about to enter it, they began looking at one another. Some of them said: “We only followed the Prophet ﷺ to flee from the Fire; shall we enter it?” While they were in that state, the fire died down and his anger subsided. This was mentioned to the Prophet ﷺ, and he said: “If they had entered it, they would never have come out of it. Obedience is only in what is right.” In another narration: “There is no obedience in disobedience to Allah; obedience is only in what is right.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7145)، ومسلم (1840:40)، والرواية الأخرى لمسلم."},{"num":7627,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ أنه قَالَ لِلْحَكَمِ بن عَمْرٍو الْغِفَارِيَّ: أَسَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا طَاعَةَ لِأَحَدٍ فِي مَعْصِيَةِ اللهِ تَبَارَكَ وَتَعَالَى قَالَ: نَعَمْ فَقَالَ عِمْرَانُ: لِلَّهِ الْحَمْدُ أَوِ اللهُ أَكْبَرُ."],"takhrij":"صحيح: رواه أحمد (20654) عن بهز، حدثنا سليمان بن المغيرة، حدثنا حميد -يعني ابن هلال- عن عبد الله بن الصامت قال: أراد زياد أن يبعث عمران بن حصين على خراسان فأبى عليهم فقال له أصحابه: أتركت خراسان أن تكون عليها قال: فقال: إني والله ما يسرني أن أُصلى بحرِّها وتصلون ببردها، إني أخاف إذا كنت في نحور العدو أن يأتيني كتاب من زياد، فإن أنا مضيتُ هلكتُ، وإن رجعت ضربت عنقي. قال: فأراد الحكم بن عمرو الغفاري عليها، قال: فانقاد لأمره قال: فقال عمران: ألا أحد يدعو لي الحكم؟ قال فانطلق الرسول، قال: فأقبل الحكم إليه، قال: فدخل عليه قال: فقال عمران للحكم: فذكره.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20654) and al-Harith ibn Abi Usamah, as in al-Bughyah (603).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿImran ibn Husayn said to al-Hakam ibn ʿAmr al-Ghifari: “Did you hear the Messenger of Allah ﷺ say: ‘There is no obedience to anyone in disobedience to Allah, Blessed and Exalted’?” He said: “Yes.” So ʿImran said: “Praise belongs to Allah,” or “Allah is the Greatest.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20654)، والحارث بن أبي أسامة كما في البغية (603)."},{"num":7628,"demo":false,"sanad":"","matn":["عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ، قَالَ: بَايَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، فَلَقَّنَنِي، فِيمَا اسْتَطَعْتُ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ.","وفي لفظ: بَايَعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى إِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ، وَعَلَى فِرَاقِ الْمُشْرِكِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7204)، ومسلم في الإيمان (56: 99) عن يعقوب بن إبراهيم الدورقي –وزاد مسلم غيره- عن هشيم، أخبرنا سيّار، عن الشعبي، عن جرير بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7204) and Muslim (56:99). The second wording was narrated by al-Nasa’i (4175) and Ahmad (19162).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jarir said: I pledged allegiance to the Prophet ﷺ to hear and obey, and he prompted me to say: “As much as I am able, and sincere counsel for every Muslim.” In another wording: I pledged allegiance to the Messenger of Allah ﷺ to establish prayer, give charity, offer sincere counsel to every Muslim, and separate from the polytheist."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7204)، ومسلم (56:99). واللفظ الثاني رواه النسائي (4175)، وأحمد (19162)."},{"num":7629,"demo":false,"sanad":"","matn":["عن أَبِي أُمَامَةَ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي حَجَّةِ الْوَدَاعِ فَقَالَ: اتَّقُوا اللَّهَ رَبَّكُمْ، وَصَلُّوا خَمْسَكُمْ، وَصُومُوا شَهْرَكُمْ، وَأَدُّوا زَكَاةَ أَمْوَالِكُمْ، وَأَطِيعُوا ذَا أَمْرِكُمْ، تَدْخُلُوا جَنَّةَ رَبِّكُمْ."],"takhrij":"صحيح: رواه الترمذي ( 616) عن موسى بن عبد الرحمن الكندي الكوفي، حدثنا زيد بن الحباب، أخبرنا معاوية بن صالح، حدثني سليم بن عامر، قال: سمعت أبا أمامة يقول: فذكره. قال: فقلت لأبي أمامة: منذ كم سمعت من رسول الله صلى الله عليه وسلم هذا الحديث؟ قال: سمعته وأنا ابن ثلاثين سنة.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (616), who said: “This is a hasan, sahih hadith.” It was also narrated by Imam Ahmad (22161).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Umamah said: I heard the Messenger of Allah ﷺ delivering a sermon during the Farewell Pilgrimage, and he said: “Be mindful of Allah, your Lord; pray your five prayers, fast your month, give the charity due on your wealth, and obey the one in authority over you; you will enter the Paradise of your Lord.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (616)، قال الترمذي: هذا حديث حسن صحيح، ورواه أيضا الإمام أحمد (22161)."},{"num":7630,"demo":false,"sanad":"","matn":["عن مُعَاوِيَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ السَّامِعَ الْمُطِيعَ لَا حُجَّةَ عَلَيْهِ، وَإِنَّ السَّامِعَ الْعَاصِي لَا حُجَّةَ لَهُ."],"takhrij":"صحيح: رواه ابن أبي عاصم في السنة (1090)، والطبراني في الكبير (19/ح 861) كلاهما من حديث محمد بن عبد الرحيم صاعقة، حدثنا روح بن عبادة، حدثنا حماد بن سلمة، عن جبلة بن عطية، عن ابن محيريز، عن معاوية فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abi ʿAsim in as-Sunnah (1090) and al-Tabarani in al-Kabir (19/366).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Muʿawiyah narrated from the Prophet ﷺ that he said: “The one who hears and obeys has no case against him, and the one who hears and disobeys has no case in his favor.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه ابن أبي عاصم في السنة (1090)، والطبراني في الكبير (19/ح 861)."},{"num":7631,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ عَلْقَمَةَ بْنَ مُجَزِّزٍ عَلَى بَعْثٍ وَأَنَا فِيهِمْ. فَلَمَّا انْتَهَى إِلَى رَأْسِ غَزَاتِهِ أَوْ كَانَ بِبَعْضِ الطَّرِيقِ اسْتَأْذَنَتْهُ طَائِفَةٌ مِنَ الْجَيْشِ فَأَذِنَ لَهُمْ وَأَمَّرَ عَلَيْهِمْ عَبْدَ اللَّهِ بْنَ حُذَافَةَ بْنِ قَيْسٍ السَّهْمِيَّ. فَكُنْتُ فِيمَنْ غَزَا مَعَهُ فَلَمَّا كَانَ بِبَعْضِ الطَّرِيقِ أَوْقَدَ الْقَوْمُ نَارًا لِيَصْطَلُوا أَوْ لِيَصْنَعُوا عَلَيْهَا صَنِيعًا. فَقَالَ عَبْدُ اللَّهِ: - وَكَانَتْ فِيهِ دُعَابَةٌ - أَلَيْسَ لِي عَلَيْكُمُ السَّمْعُ وَالطَّاعَةُ؟ قَالُوا: بَلَى. قَالَ: فَمَا أَنَا بِآمِرِكُمْ بِشَىْءٍ إِلاَّ صَنَعْتُمُوهُ؟ قَالُوا: نَعَمْ. قَالَ: فَإِنِّي أَعْزِمُ عَلَيْكُمْ إِلاَّ تَوَاثَبْتُمْ فِي هَذِهِ النَّارِ. فَقَامَ نَاسٌ فَتَحَجَّزُوا. فَلَمَّا ظَنَّ أَنَّهُمْ وَاثِبُونَ قَالَ: أَمْسِكُوا عَلَى أَنْفُسِكُمْ. فَإِنَّمَا كُنْتُ أَمْزَحُ مَعَكُمْ. فَلَمَّا قَدِمْنَا ذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَمَرَكُمْ مِنْهُمْ بِمَعْصِيَةِ اللَّهِ فَلاَ تُطِيعُوهُ."],"takhrij":"حسن: رواه ابن ماجه (2863)، وأحمد (11639)، وابن حبان (4558) كلهم من طريق محمد بن عمرو، عن عمر بن الحكم بن ثوبان، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2863), Ahmad (11639), and authenticated by Ibn Hibban (4558).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ sent ʿAlqamah ibn Mujazziz in command of a detachment, and I was among them. When he reached the area of his campaign, or while he was on part of the road, a group from the army sought his permission, and he granted them permission and appointed ʿAbdullah ibn Hudhafah ibn Qays as-Sahmi over them. I was among those who went with him. While they were on part of the road, the people lit a fire to warm themselves or to cook something over it. ʿAbdullah — who had some humor in him — said: “Do I not have the right of hearing and obedience over you?” They said: “Yes.” He said: “Whatever I command you to do, will you do it?” They said: “Yes.” He said: “I firmly command you to jump into this fire.” Some people stood and prepared themselves. When he thought they were about to jump, he said: “Hold back from yourselves; I was only joking with you.” When we returned, they mentioned that to the Prophet ﷺ, and the Messenger of Allah ﷺ said: “If one of them commands you to disobey Allah, then do not obey him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2863)، وأحمد (11639)، وصححه ابن حبان (4558)."},{"num":7632,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: طَاعَةُ الْإِمَامِ حَقٌّ عَلَى الْمَرْءِ الْمُسْلِمِ مَا لَمْ يَأْمُرْ بِمَعْصِيَةٍ اللَّهِ، فَإِذَا أَمَرَ بِمَعْصِيَةِ اللَّهِ فَلَا طَاعَةَ لَهُ."],"takhrij":"حسن: رواه تمام في فوائده (914- الروض) عن الحسن بن حبيب، حدثنا بدر بن الهيثم، حدثنا سليمان بن عبد الرحمن، حدثنا عبد الرحمن بن المغراء، عن عبيد الله بن عمر، عن سعيد بن أبي سعيد المقبري، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Tammam in his Fawa’id (ar-Rawd, 914).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Obedience to the leader is a duty upon the Muslim so long as he does not command disobedience to Allah. If he commands disobedience to Allah, then there is no obedience to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه تمام في فوائده (الروض 914)."},{"num":7633,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَيَلِي أُمُورَكُمْ بَعْدِي رِجَالٌ يُطْفِئُونَ السُّنَّةَ، وَيَعْمَلُونَ بِالْبِدْعَةِ، وَيُؤَخِّرُونَ الصَّلاَةَ عَنْ مَوَاقِيتِهَا فَقُلْتُ: يَا رَسُولَ اللَّهِ إِنْ أَدْرَكْتُهُمْ كَيْفَ أَفْعَلُ؟ قَالَ: تَسْأَلُنِي يَا ابْنَ أُمِّ عَبْدٍ كَيْفَ تَفْعَلُ لاَ طَاعَةَ لِمَنْ عَصَى اللَّهَ."],"takhrij":"حسن: رواه ابن ماجه (2865)، وأحمد (3790)، والبيهقي (3/124) من طرق عن عبد الله بن عثمان بن خثيم، عن القاسم بن عبد الرحمن بن عبد الله بن مسعود، عن أبيه، عن جده عبد الله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2865), Ahmad (3790), and al-Bayhaqi (3/124).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud narrated that the Prophet ﷺ said: “After me, men will take charge of your affairs who extinguish the practice, act according to innovation, and delay the prayer beyond its proper times.” I said: “O Messenger of Allah, if I reach them, what should I do?” He said: “You ask me, son of Umm ʿAbd, what you should do? There is no obedience to one who disobeys Allah.”"]},"buhuth":{"en":["His statement “There is no obedience to one who disobeys Allah” means in whatever contradicts the command of Allah. That is, he should perform the prayer in its time at home, then pray with them so that he is not disobedient to them either, because the time of prayer is broad.","Among the beliefs of the people of the Prophetic way is that if the people gather upon the one who has gained authority by dominance, obedience to him becomes obligatory, as Ibn ʿUmar did. He refused to pledge allegiance either to Ibn az-Zubayr or to ʿAbd al-Malik, but when ʿAbd al-Malik prevailed and authority became established for him, he pledged allegiance to him.","Harmalah said: I heard ash-Shafiʿi say: Everyone who gains the caliphate by the sword until he is called caliph and the people gather upon him, then he is a caliph. Narrated by al-Bayhaqi in Manaqib ash-Shafiʿi (1/448).","Imam Ahmad said: “The foundations of the Prophetic way according to us…” then he mentioned matters and said: “Hearing and obedience to the leaders and the commander of the believers, whether righteous or sinful, and to whoever takes charge of the caliphate and the people gather upon him and accept him, and to whoever overcomes them by the sword until he becomes caliph and is called the commander of the believers.”","He also said: “Whoever rebels against the leader of the Muslims after the people have gathered upon him and affirmed the caliphate for him by any means, whether through acceptance or dominance, then this rebel has split the unity of the Muslims and opposed the transmitted reports from the Messenger of Allah ﷺ. If the rebel dies upon that, he dies a death of the pre-Islamic period. It is not lawful for anyone among the people to fight the ruler or rebel against him. Whoever does that is an innovator, not upon the Prophetic way or the path.” See Sharh al-Iʿtiqad by al-Lalaka’i (1/160–161).","Al-Hafiz Ibn Hajar said: The jurists have unanimously agreed on the obligation of obeying the ruler who gained authority by dominance, and of striving alongside him, and that obedience to him is better than rebelling against him because that preserves blood and calms the masses. Fath al-Bari (13/7).","Shaykh al-Islam Muhammad ibn ʿAbd al-Wahhab, may Allah have mercy on him, said: The imams of every school are agreed that whoever gains dominance over a land or lands has the ruling of the leader in all matters. Ad-Durar as-Saniyyah fi al-Ajwibah an-Najdiyyah (7/239).","Imam al-Barbahari, who died in 328 after the Hijrah, said: “If you see a man supplicating against the ruler, know that he is a person of desires. If you hear a man supplicating for the ruler’s righteousness, know that he is a person of the Prophetic way, if Allah wills. Fudayl ibn ʿIyad said: If I had one supplication, I would only make it for the ruler. We were commanded to supplicate for their righteousness, and we were not commanded to supplicate against them, even if they are unjust and oppressive; for their injustice and oppression harm themselves and the Muslims, while their righteousness benefits themselves and the Muslims.” See Tabaqat al-Hanabilah by Ibn Abi Yaʿla (2/36).","In these reports — and they are very many — is the point that among the beliefs of the people of the Prophetic way and the community is that rebelling against the leaders, even if they are unjust, is forbidden, unless clear disbelief is seen from them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2865)، وأحمد (3790)، والبيهقي (3/124)."},{"num":7634,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّكُمْ سَتَرَوْنَ بَعْدِي أَثَرَةً وَأُمُورًا تُنْكِرُونَهَا. قَالُوا: فَمَا تَأْمُرُنَا يَا رَسُولَ اللَّهِ؟ قَالَ: أَدُّوا إِلَيْهِمْ حَقَّهُمْ، وَسَلُوا اللَّهَ حَقَّكُمْ."],"takhrij":"متفق عليه: رواه البخاري في القتن (7052)، ومسلم في الإمارة (1843: 45) كلاهما من طريق الأعمش، حدثنا زيد بن وهب سمعت عبد الله قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7052) and Muslim (1843:45).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The Messenger of Allah ﷺ said to us: “After me, you will see favoritism and matters that you disapprove of.” They said: “What do you command us, O Messenger of Allah?” He said: “Give them their right, and ask Allah for your right.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7052)، ومسلم (1843:45)."},{"num":7635,"demo":false,"sanad":"","matn":["عَنْ جُنَادَةَ بْنِ أَبِي أُمَيَّةَ، قَالَ: دَخَلْنَا عَلَى عُبَادَةَ بْنِ الصَّامِتِ، وَهْوَ مَرِيضٌ قُلْنَا: أَصْلَحَكَ اللَّهُ حَدِّثْ بِحَدِيثٍ، يَنْفَعُكَ اللَّهُ بِهِ سَمِعْتَهُ مِنَ النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: دَعَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْنَاهُ فَقَالَ: فِيمَا أَخَذَ عَلَيْنَا أَنْ بَايَعَنَا عَلَى السَّمْعِ وَالطَّاعَةِ، فِي مَنْشَطِنَا وَمَكْرَهِنَا، وَعُسْرِنَا، وَيُسْرِنَا، وَأَثَرَةٍ عَلَيْنَا، وَأَنْ لاَ نُنَازِعَ الأَمْرَ أَهْلَهُ، إِلاَّ أَنْ تَرَوْا كُفْرًا بَوَاحًا، عِنْدَكُمْ مِنَ اللَّهِ فِيهِ بُرْهَانٌ."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7055)، ومسلم في الإمارة (1709: 42) كلاهما من طريق عبد الله بن وهب، حدثنا عمرو بن الحارث، حدثني بكير، عن بسر بن سعيد، عن جنادة بن أبي أمية قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7055) and Muslim (1709:42).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Junadah ibn Abi Umayyah said: We entered upon ʿUbadah ibn as-Samit while he was ill, and we said: “May Allah set your affair right. Narrate to us a hadith you heard from the Prophet ﷺ, by which Allah may benefit you.” He said: The Prophet ﷺ called us and we pledged allegiance to him. Among what he took from us was that we pledged allegiance to hear and obey in what we liked and disliked, in hardship and ease, and even when others were favored over us, and that we would not dispute authority with its rightful holders, “unless you see clear disbelief for which you have proof from Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7055)، ومسلم (1709:42)."},{"num":7636,"demo":false,"sanad":"","matn":["رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ رَأَى مِنْ أَمِيرِهِ شَيْئًا يَكْرَهُهُ فَلْيَصْبِرْ عَلَيْهِ، فَإِنَّهُ مَنْ فَارَقَ الْجَمَاعَةَ شِبْرًا فَمَاتَ، إِلاَّ مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7054)، ومسلم في الإمارة (1849: 55) كلاهما من طريق حماد بن زيد، عن الجعد أبي عثمان، حدثني أبو رجاء العطاردي قال: سمعت ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7054) and Muslim (1849:55).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas narrated from the Prophet ﷺ that he said: “Whoever sees something from his commander that he dislikes, let him be patient with it; for whoever separates from the community by a handspan and then dies, he only dies a death of the pre-Islamic period.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7054)، ومسلم (1849:55)."},{"num":7637,"demo":false,"sanad":"","matn":["عَنْ أُسَيْدِ بْنِ حُضَيْرٍ، أَنَّ رَجُلاً، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ اسْتَعْمَلْتَ فُلاَنًا وَلَمْ تَسْتَعْمِلْنِي. قَالَ: إِنَّكُمْ سَتَرَوْنَ بَعْدِي أَثَرَةً، فَاصْبِرُوا حَتَّى تَلْقَوْنِي."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7057)، ومسلم في الإمارة (1845: 48) كلاهما من طريق شعبة، عن قتادة، عن أنس بن مالك، عن أسيد بن حضير فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7057) and Muslim (1845:48).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Usayd ibn Hudayr narrated that a man came to the Prophet ﷺ and said: “O Messenger of Allah, you appointed so-and-so but did not appoint me.” He said: “After me, you will see favoritism, so be patient until you meet me.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7057)، ومسلم (1845:48)."},{"num":7638,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  عَلَيْكَ السَّمْعَ وَالطَّاعَةَ فِي عُسْرِكَ وَيُسْرِكَ، وَمَنْشَطِكَ وَمَكْرَهِكَ، وَأَثَرَةٍ عَلَيْكَ."],"takhrij":"صحيح: رواه مسلم في الإمارة 1836) من طريق يعقوب بن عبد الرحمن، عن أبي حازم، عن أبي صالح السمان، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1836).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “You must hear and obey in hardship and ease, in what you like and dislike, and even when others are favored over you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1836)."},{"num":7639,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: سَأَلَ سَلَمَةُ بْنُ يَزِيدَ الْجُعْفِيُّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللَّهِ، أَرَأَيْتَ إِنْ قَامَتْ عَلَيْنَا أُمَرَاءُ يَسْأَلُونَا حَقَّهُمْ وَيَمْنَعُونَا حَقَّنَا فَمَا تَأْمُرُنَا؟ فَأَعْرَضَ عَنْهُ، ثُمَّ سَأَلَهُ، فَأَعْرَضَ عَنْهُ، ثُمَّ سَأَلَهُ فِي الثَّانِيَةِ أَوْ فِي الثَّالِثَةِ فَجَذَبَهُ الْأَشْعَثُ بْنُ قَيْسٍ وَقَالَ: اسْمَعُوا وَأَطِيعُوا فَإِنَّمَا عَلَيْهِمْ مَا حُمِّلُوا وَعَلَيْكُمْ مَا حُمِّلْتُمْ. وَفِي روية: فَجَذَبَهُ الْأَشْعَثُ بن قَيْسٍ فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : اسْمَعُوا وَأَطِيعُوا الحديث."],"takhrij":"صحيح: رواه مسلم في الإمارة (1846: 49) من طريق محمد بن جعفر، حدثنا شعبة، عن سماك بن حرب، عن علقمة بن وائل الحضرمي، عن أبيه قال: فذكره. والرواية الأخرى من طريق شبابة، حدثنا شعبة به.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1846:49).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Wa’il ibn Hujr said: Salamah ibn Yazid al-Juʿfi asked the Messenger of Allah ﷺ: “O Prophet of Allah, what do you think if rulers stand over us, demanding their rights from us while withholding our rights from us? What do you command us?” He turned away from him. Then he asked again, and he turned away from him. Then he asked him the second or third time, so al-Ashʿath ibn Qays pulled him. He said: “Hear and obey, for upon them is what they are burdened with, and upon you is what you are burdened with.” In another narration: Al-Ashʿath ibn Qays pulled him, and the Messenger of Allah ﷺ said: “Hear and obey…”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1846:49)."},{"num":7640,"demo":false,"sanad":"","matn":["عن عَوْفِ بْنِ مَالِكٍ الأشجعي يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  خِيَارُ أَئِمَّتِكُمُ الَّذِينَ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ، وَتُصَلُّونَ عَلَيْهِمْ وَيُصَلُّونَ عَلَيْكُمْ، وَشِرَارُ أَئِمَّتِكُمُ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ، وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ. قَالُوا: قُلْنَا: يَا رَسُولَ اللَّهِ، أَفَلَا نُنَابِذُهُمْ عِنْدَ ذَلِكَ؟ قَالَ: لَا، مَا أَقَامُوا فِيكُمُ الصَّلَاةَ، لَا، مَا أَقَامُوا فِيكُمُ الصَّلَاةَ، أَلَا مَنْ وَلِيَ عَلَيْهِ وَالٍ، فَرَآهُ يَأْتِي شَيْئًا مِنْ مَعْصِيَةِ اللهِ، فَلْيَكْرَهْ مَا يَأْتِي مِنْ مَعْصِيَةِ اللهِ، وَلَا يَنْزِعَنَّ يَدًا مِنْ طَاعَةٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1855: 66) عن داود بن رشيد حدثنا الوليد يعني بن مسلم، حدثنا عبد الرحمن بن يزيد بن جابر، أخبرني مولى بني فزارة وهو رزيق بن حيان أنه سمع مسلم بن قرظة ابن عم عوف بن مالك الأشجعي يقول سمعت عوف بن مالك الأشجعي يقول: فذكره.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1855:66).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAwf ibn Malik al-Ashjaʿi said: I heard the Messenger of Allah ﷺ say: “The best of your leaders are those whom you love and who love you, and for whom you pray and who pray for you. The worst of your leaders are those whom you hate and who hate you, and whom you curse and who curse you.” They said: We said: “O Messenger of Allah, should we not oppose them then?” He said: “No, as long as they establish prayer among you. No, as long as they establish prayer among you. Indeed, whoever has a ruler appointed over him and sees him doing something of disobedience to Allah, let him hate the disobedience to Allah that he does, but let him not withdraw his hand from obedience.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1855:66)."},{"num":7641,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  سَتَكُونُ أُمَرَاءُ، فَتَعْرِفُونَ وَتُنْكِرُونَ، فَمَنْ عَرَفَ بَرِئَ، وَمَنْ أَنْكَرَ سَلِمَ، وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ. قَالُوا: أَفَلَا نُقَاتِلُهُمْ؟ قَالَ: لَا، مَا صَلَّوْا.","وفي رواية: فمن كره فقد برئ، ومن أنكر فقد سلم. أي من كره بقلبه وأنكر بقلبه."],"takhrij":"صحيح: رواه مسلم في الإمارة (1854: 62) عن هدّاب بن خالد الأزدي، حدثنا همام بن يحيى، حدثنا قتادة، عن الحسن، عن ضبة بن محصن، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1854:62).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Umm Salamah narrated that the Messenger of Allah ﷺ said: “There will be rulers, and you will recognize some things and reject some things. Whoever recognizes will be free of blame, and whoever rejects will be safe, but the one who is pleased and follows…” They said: “Should we not fight them?” He said: “No, as long as they pray.” In another narration: “Whoever hates it has become free of blame, and whoever rejects it has become safe.” That is, whoever hates it in his heart and rejects it in his heart."]},"buhuth":{"en":["His phrase “the one who is pleased and follows” means that sin and punishment are upon the one who is pleased and follows. This contains evidence that whoever is unable to remove wrongdoing does not sin merely by remaining silent; rather, he sins by being pleased with it, or by not hating it in his heart, or by following it. This was stated by an-Nawawi."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1854:62)."},{"num":7642,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَيَكُونُ مِنْ بَعْدِي خُلَفَاءُ، يَعْمَلُونَ بِمَا يَعْلَمُونَ، وَيَفْعَلُونَ مَا يُؤْمَرُونَ، وَسَيَكُونُ مِنْ بَعْدِهِمْ خُلَفَاءُ، يَعْمَلُونَ بِمَا لَا يَعْلَمُونَ، وَيَفْعَلُونَ مَا لَا يُؤْمَرُونَ، فَمَنْ أَنْكَرَ بَرِئَ، وَمَنْ أَمْسَكَ سَلِمَ، وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ."],"takhrij":"حسن: رواه ابن حبان (6659)، والبخاري في التاريخ الكبير (1/329) كلاهما من طرق عن الأوزاعي، عن إبراهيم بن مرة، عن الزهري، عن أبي سلمة، عن أبي هريرة قال:فذكره.","grade":"حسن","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (6659) and al-Bukhari in al-Tarikh al-Kabir (1/329).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “After me there will be successors who act according to what they know and do what they are commanded. After them there will be successors who act according to what they do not know and do what they were not commanded. Whoever rejects will be free of blame, and whoever restrains himself will be safe, but the one who is pleased and follows…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (6659)، والبخاري في التاريخ الكبير (1/329)."},{"num":7643,"demo":false,"sanad":"","matn":["عن سَلَمَةَ بن الأكوع – فِي حَدِيثِ طَوِيلٍ- قَالَ: ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَعَانَا لِلْبَيْعَةِ فِي أَصْلِ الشَّجَرَةِ، قَالَ: فَبَايَعْتُهُ أَوَّلَ النَّاسِ، ثُمَّ بَايَعَ، وَبَايَعَ، حَتَّى إِذَا كَانَ فِي وَسَطٍ مِنَ النَّاسِ قَالَ: بَايِعْ يَا سَلَمَةُ. قَالَ: قُلْتُ: قَدْ بَايَعْتُكَ يَا رَسُولَ اللَّهِ فِي أَوَّلِ النَّاسِ، قَالَ: وَأَيْضًا، قَالَ: وَرَآنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَزِلًا (يَعْنِي: لَيْسَ مَعَهُ سِلَاحٌ)، قَالَ: فَأَعْطَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَفَةً أَوْ دَرَقَةً، ثُمَّ بَايَعَ، حَتَّى إِذَا كَانَ فِي آخِرِ النَّاسِ قَالَ: أَلَا تُبَايِعُنِي يَا سَلَمَةُ؟ قَالَ: قُلْتُ: قَدْ بَايَعْتُكَ يَا رَسُولَ اللَّهِ فِي أَوَّلِ النَّاسِ، وَفِي أَوْسَطِ النَّاسِ، قَالَ: وَأَيْضًا. قَالَ: فَبَايَعْتُهُ الثَّالِثَةَ."],"takhrij":"متفق عليه: رواه مسلم في الجهاد والسير (1806: 131) عن قتيبة بن سعيد حدثنا حاتم يعني بن إسماعيل، عن يزيد بن أبي عبيد قال: سمعت سلمة بن الأكوع يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب مبايعة الإمام أكثر من مرة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1806:131) and al-Bukhari (7208). Al-Bukhari’s wording is: He said: We pledged allegiance to the Prophet ﷺ under the tree, and he said to me: “Salamah, will you not pledge allegiance?” I said: “O Messenger of Allah, I already pledged allegiance the first time.” He said: “And the second.”","chapter_en":"Pledging Allegiance to the Leader More Than Once","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ, in a long hadith, said: Then the Messenger of Allah ﷺ called us to pledge allegiance at the base of the tree. He said: I was the first of the people to pledge allegiance to him. Then he continued accepting pledges, until when he was in the middle of the people, he said: “Pledge allegiance, Salamah.” I said: “I already pledged allegiance to you, O Messenger of Allah, among the first of the people.” He said: “Again.” He said: The Messenger of Allah ﷺ saw that I was unarmed — meaning I had no weapon — so the Messenger of Allah ﷺ gave me a small shield or a leather shield. Then he continued accepting pledges, until when he was among the last of the people, he said: “Will you not pledge allegiance to me, Salamah?” I said: “I already pledged allegiance to you, O Messenger of Allah, among the first people and among the middle of the people.” He said: “Again.” So I pledged allegiance to him a third time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (1806:131)، ورواه البخاري (7208). ولفظه: قال: بايعنا النبي ﷺ تحت الشجرة، فقال لي: (( يا سلمة ألا تبايع؟ )) قلت: يا رسول الله قد بايعت في الأول. قال: (( وفي الثاني ))."},{"num":7644,"demo":false,"sanad":"","matn":["عن عَوْفِ بْنِ مَالِكٍ الأشجعي قَالَ:  كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعَةً، أَوْ ثَمَانِيَةً، أَوْ سَبْعَةً، فَقَالَ: أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ، وَكُنَّا حَدِيثَ عَهْدٍ بِبَيْعَةٍ، فَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ، ثُمَّ، قَالَ: أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ؟ فَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ، ثُمَّ قَالَ: أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ، قَالَ: فَبَسَطْنَا أَيْدِيَنَا، وَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ، فَعَلَامَ نُبَايِعُكَ؟ قَالَ: عَلَى أَنْ تَعْبُدُوا اللَّهَ، وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَالصَّلَوَاتِ الْخَمْسِ، وَتُطِيعُوا، (وَأَسَرَّ كَلِمَةً خَفِيَّةً)، وَلَا تَسْأَلُوا النَّاسَ شَيْئًا فَلَقَدْ رَأَيْتُ بَعْضَ أُولَئِكَ النَّفَرِ يَسْقُطُ سَوْطُ أَحَدِهِمْ فَمَا يَسْأَلُ أَحَدًا يُنَاوِلُهُ إِيَّاهُ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1043) من طريقين عن مروان (ابن محمد الدمشقي)، حدثنا سعيد (هو ابن عبد العزيز)، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن أبي مسلم الخولاني قال: حدثني الحبيب الأمين عوف بن مالك الأشجعي فذكره.","grade":"صحيح","chapter_ar":"باب مبايعة الإمام أكثر من مرة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1043).","chapter_en":"Pledging Allegiance to the Leader More Than Once","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAwf ibn Malik al-Ashjaʿi said: We were with the Messenger of Allah ﷺ, nine, eight, or seven of us, and he said: “Will you not pledge allegiance to the Messenger of Allah?” We had only recently pledged allegiance, so we said: “We have already pledged allegiance to you, Messenger of Allah.” Then he said: “Will you not pledge allegiance to the Messenger of Allah?” We said: “We have already pledged allegiance to you, Messenger of Allah.” Then he said: “Will you not pledge allegiance to the Messenger of Allah?” He said: So we stretched out our hands and said: “We have already pledged allegiance to you, Messenger of Allah, so upon what shall we pledge allegiance to you?” He said: “That you worship Allah, associate nothing with Him, perform the five prayers, and obey.” Then he quietly said a hidden word: “And that you do not ask people for anything.” I later saw some of those people drop a whip, yet he would not ask anyone to hand it to him."]}},"tuhfa":{},"full":1,"rep":[240,4234],"tks":"صحيح: رواه مسلم (1043)."},{"num":7645,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْتَحِنُ مَنْ هَاجَرَ إِلَيْهِ مِنَ الْمُؤْمِنَاتِ بِهَذِهِ الآيَةِ بِقَوْلِ اللَّهِ: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ﴾ [سورة الممتحنة: 12] إِلَى قَوْلِهِ غَفُورٌ رَحِيمٌ قَالَ عُرْوَةُ: قَالَتْ عَائِشَةُ: فَمَنْ أَقَرَّ بِهَذَا الشَّرْطِ مِنَ الْمُؤْمِنَاتِ قَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : قَدْ بَايَعْتُكِ كَلاَمًا، وَلاَ وَاللَّهِ مَا مَسَّتْ يَدُهُ يَدَ امْرَأَةٍ قَطُّ فِي الْمُبَايَعَةِ مَا يُبَايِعُهُنَّ إِلاَّ بِقَوْلِهِ: قَدْ بَايَعْتُكِ عَلَى ذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4891)، ومسلم في الإمارة (1866: 88) كلاهما من طريق ابن شهاب، أخبرني عروة بن الزبير، أن عائشة زوج النبيصلى الله عليه وسلم أخبرته فذكرته. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4891) and Muslim (1866:88). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ used to test the believing women who migrated to him with this verse, from Allah’s statement: “O Prophet, when the believing women come to you pledging allegiance to you…” up to His statement: “Forgiving, Merciful.” ʿUrwah said: ʿA’ishah said: Any believing woman who accepted this condition, the Messenger of Allah ﷺ would say to her: “I have accepted your pledge verbally.” By Allah, his hand never touched the hand of a woman during the pledge of allegiance. He only accepted their pledge by saying: “I have accepted your pledge upon that.”"]},"intro":{"ar":["قال الله تعالى: (يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَىٰ أَنْ لَا يُشْرِكْنَ بِاللهِ شَيْئًا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَادَهُنَّ وَلَا يَأْتِينَ بِبُهْتَانٍ يَفْتَرِينَهُ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ فَبَايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ اللهَ إِنَّ اللهَ غَفُورٌ رَحِيمٌ) [الممتحنة: ١٢]"],"en":["Allah the Exalted says: “O Prophet, when the believing women come to you pledging allegiance to you that they will not associate anything with Allah, will not steal, will not commit unlawful intercourse, will not kill their children, will not bring a slander they invent between their hands and feet, and will not disobey you in what is right, then accept their pledge and seek Allah’s forgiveness for them. Indeed, Allah is Forgiving, Merciful.” [Surah al-Mumtahanah: 12]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4891)، ومسلم (1866:88). والسياق للبخاري."},{"num":7646,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ، قَالَتْ: بَايَعْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَأَ عَلَىَّ {أَنْ لاَ يُشْرِكْنَ بِاللَّهِ شَيْئًا} وَنَهَانَا عَنِ النِّيَاحَةِ، فَقَبَضَتِ امْرَأَةٌ مِنَّا يَدَهَا فَقَالَتْ: فُلاَنَةُ أَسْعَدَتْنِي، وَأَنَا أُرِيدُ أَنْ أَجْزِيَهَا، فَلَمْ يَقُلْ شَيْئًا، ثُمَّ رَجَعَتْ، فَمَا وَفَتِ امْرَأَةٌ إِلاَّ أُمُّ سُلَيْمٍ، وَأُمُّ الْعَلاَءِ، وَابْنَةُ أَبِي سَبْرَةَ امْرَأَةُ مُعَاذٍ، أَوِ ابْنَةُ أَبِي سَبْرَةَ، وَامْرَأَةُ مُعَاذٍ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7215)، ومسلم في الجنائز (936: 32) كلاهما من طريق حفصة، عن أم عطية.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7215) and Muslim (936:32). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Umm ʿAtiyyah said: We pledged allegiance to the Prophet ﷺ, and he recited to us: “that they will not associate anything with Allah,” and he forbade us from wailing over the dead. One woman among us withdrew her hand and said: “So-and-so helped me in mourning, and I want to repay her.” He said nothing, so she went, then returned. No woman fulfilled this except Umm Sulaym, Umm al-ʿAla’, the daughter of Abu Sabrah, the wife of Muʿadh — or the daughter of Abu Sabrah and the wife of Muʿadh."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13537],"tks":"متفق عليه: رواه البخاري (7215)، ومسلم (936:32). والسياق للبخاري."},{"num":7647,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُبَايِعُ النِّسَاءَ بِالْكَلاَمِ بِهَذِهِ الآيَةِ {لاَ يُشْرِكْنَ بِاللَّهِ شَيْئًا} قَالَتْ: وَمَا مَسَّتْ يَدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ امْرَأَةٍ، إِلاَّ امْرَأَةً يَمْلِكُهَا."],"takhrij":"صحيح: رواه البخاري في الأحكام (7214) عن محمود، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7214).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: The Prophet ﷺ used to accept the pledge of allegiance from women verbally through this verse: “that they will not associate anything with Allah.” She said: The hand of the Messenger of Allah ﷺ never touched the hand of any woman except a woman whom he lawfully possessed."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7214)."},{"num":7648,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: مَا مَسَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ امْرَأَةً قَطُّ إِلَّا أَنْ يَأْخُذَ عَلَيْهَا فَإِذَا أَخَذَ عَلَيْهَا فَأَعْطَتْهُ قَالَ: اذْهَبِي فَقَدْ بَايَعْتُكِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1866: 89) من طريق ابن وهب، حدثني مالك، عن ابن شهاب، عن عروة أن عائشة أخبرته عن بيعة النساء قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1866:89).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ never touched a woman with his hand at all. Rather, he would take the pledge from her, and when he had taken it and she had given it, he would say: “Go, for I have accepted your pledge.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1866:89)."},{"num":7649,"demo":false,"sanad":"","matn":["عَنْ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ أَنَّها قَالَتْ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نِسْوَةٍ بايعنه عَلَى الإسلام فَقُلْنَ: يَا رَسُولَ اللَّهِ نُبَايِعُكَ عَلَى أَنْ لَا نُشْرِكَ بِاللهِ شَيْئًا، وَلَا نَسْرِقَ، وَلَا نَزْنِيَ، وَلَا نَقْتُلَ أَوْلَادَنَا، وَلَا نَأْتِيَ بِبُهْتَانٍ نَفْتَرِيهِ بَيْنَ أَيْدِينَا وَأَرْجُلِنَا، وَلَا نَعْصِيَكَ فِي مَعْرُوفٍ، فَقَالَ رَسُولُ اللَّهِ : صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا اسْتَطَعْتُنَّ وَأَطَقْتُنَّ قَالَتْ: فَقُلْنَ: اللهُ وَرَسُولُهُ أَرْحَمُ بِنَا من أَنْفُسِنَا، هَلُمَّ نُبَايِعُكَ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ أَوْ مثل قَوْلِي لِامْرَأَةٍ وَاحِدَةٍ."],"takhrij":"صحيح: رواه مالك في البيعة (2) عن محمد بن المنكدر، عن أميمة بنت رقيقة فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (2), al-Tirmidhi (1597), al-Nasa’i (4181), Ibn Majah (2874), and Ahmad (27019).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Umaymah bint Ruqayqah said: I came to the Messenger of Allah ﷺ with a group of women who pledged allegiance to him upon Islam. They said: “Messenger of Allah, we pledge allegiance to you that we will not associate anything with Allah, will not steal, will not commit unlawful intercourse, will not kill our children, will not bring a slander we invent between our hands and feet, and will not disobey you in what is right.” The Messenger of Allah ﷺ said: “As much as you are able and capable.” She said: They said: “Allah and His Messenger are more merciful to us than we are to ourselves. Come, let us pledge allegiance to you, Messenger of Allah.” The Messenger of Allah ﷺ said: “I do not shake hands with women. My statement to one hundred women is only like my statement to one woman, or like my statement to a single woman.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14260],"tks":"صحيح: رواه مالك (2)، والترمذي (1597)، والنسائي (4181)، وابن ماجه (2874)، وأحمد (27019)."},{"num":7650,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: جَاءَتْ أُمَيْمَةُ بِنْتُ رُقَيْقَةَ، إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُبَايِعُهُ عَلَى الْإِسْلَامِ، فَقَالَ: أُبَايِعُكِ عَلَى أَنْ لَا تُشْرِكِي بِاللهِ شَيْئًا، وَلَا تَسْرِقِي، وَلَا تَزْنِي، وَلَا تَقْتُلِي وَلَدَكِ، وَلَا تَأْتِي بِبُهْتَانٍ تَفْتَرِينَهُ بَيْنَ يَدَيْكِ وَرِجْلَيْكِ، وَلَا تَنُوحِي، وَلَا تَبَرَّجِي تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى."],"takhrij":"حسن: رواه أحمد (6850) عن خلف بن الوليد، حدثنا ابن عياش، عن سليمان بن سليم، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6850).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, who said: Umaymah bint Ruqayqah came to the Messenger of Allah ﷺ to pledge allegiance to him upon Islam. He said: “I accept your pledge that you will not associate anything with Allah, will not steal, will not commit unlawful intercourse, will not kill your child, will not bring a slander you invent between your hands and feet, will not wail over the dead, and will not display yourself as women displayed themselves in the earlier age of ignorance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6850)."},{"num":7651,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ، عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو، أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ لَا يُصَافِحُ النِّسَاءَ فِي الْبَيْعَةِ."],"takhrij":"حسن: رواه أحمد (6998) عن عتاب بن زياد، أخبرنا عبـد الله، أخبرنا أسامة بن زيد، حدثني عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6998).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated that the Messenger of Allah ﷺ did not shake hands with women during the pledge of allegiance."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9184],"tks":"حسن: رواه أحمد (6998)."},{"num":7652,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ قَالَتْ: دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  النِّسَاءَ الْمُؤْمِنِينَ إِلَى الْبَيْعَةِ، فَقَالَتْ أَسْمَاءُ: يَا رَسُولَ اللَّهِ، أَلَا تَحْسِرُ لَنَا عَنْ يَدِكَ؟ فَقَالَ إِنِّي لَا أُصَافِحُ النِّسَاءَ."],"takhrij":"حسن: رواه إسحاق بن راهويه كما في المطالب (2109) –واللفظ له- وأحمد مختصرا (27594) من طريقين عن عبد الحميد بن بهرام، عن شهر بن حوشب، عن أسماء بنت يزيد فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ishaq ibn Rahwayh, as in al-Matalib (2109), and the wording is his; and by Ahmad in abridged form (27594).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Asma’ bint Yazid said: The Messenger of Allah ﷺ called the believing women to pledge allegiance. Asma’ said: “Messenger of Allah, will you not uncover your hand for us?” He said: “I do not shake hands with women.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14261],"tks":"حسن: رواه إسحاق بن راهويه كما في المطالب (2109) — واللفظ له — وأحمد مختصرا (27594)."},{"num":7653,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  جَاءَ عَبْدٌ، فَبَايَعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْهِجْرَةِ، وَلَمْ يَشْعُرْ أَنَّهُ عَبْدٌ، فَجَاءَ سَيِّدُهُ يُرِيدُهُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بِعْنِيهِ. فَاشْتَرَاهُ بِعَبْدَيْنِ أَسْوَدَيْنِ، ثُمَّ لَمْ يُبَايِعْ أَحَدًا بَعْدُ، حَتَّى يَسْأَلَهُ: أَعَبْدٌ هُوَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1602) من طرق عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب بيعة العبد","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1602).","chapter_en":"The Pledge of Allegiance of a Slave","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Jabir said: A slave came and pledged allegiance to the Prophet ﷺ for migration, and he did not realize that he was a slave. Then his master came seeking him, so the Prophet ﷺ said to him: “Sell him to me.” He bought him for two black slaves. After that, he would not accept anyone’s pledge until he asked him: “Are you a slave?”"]}},"tuhfa":{},"full":1,"rep":[5892],"tks":"صحيح: رواه مسلم (1602)."},{"num":7654,"demo":false,"sanad":"","matn":["عَنْ الشريد قَالَ: كَانَ فِي وَفْدِ ثَقِيفٍ رَجُلٌ مَجْذُومٌ فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّا قَدْ بَايَعْنَاكَ فَارْجِعْ."],"takhrij":"صحيح: رواه مسلم في السلام (2231) من طريقين عن يعلى بن عطاء، عن عمرو بن الشريد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب بيعة من به عاهة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2231).","chapter_en":"The Pledge of Allegiance of One Who Has an Affliction","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ash-Sharid said: Among the delegation of Thaqif there was a man afflicted with leprosy, so the Prophet ﷺ sent word to him: “We have accepted your pledge, so return.”"]}},"tuhfa":{},"full":1,"rep":[9786,11652],"tks":"صحيح: رواه مسلم (2231)."},{"num":7655,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن هِشَامٍ: وَكَانَ، قَدْ أَدْرَكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَهَبَتْ بِهِ أُمُّهُ زَيْنَبُ ابْنَةُ حُمَيْدٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ بَايِعْهُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُوَ صَغِيرٌ فَمَسَحَ رَأْسَهُ، وَدَعَا لَهُ، وَكَانَ يُضَحِّي بِالشَّاةِ الْوَاحِدَةِ عَنْ جَمِيعِ أَهْلِهِ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7210) عن علي بن عبد الله، حدثنا عبد الله بن يزيد، حدثنا سعيد بن أبي أيوب قال: حدثني أبو عقيل زهرة بن معبد، عن جده عبد الله بن هشام فذكره.","grade":"صحيح","chapter_ar":"باب لا تصح بيعة الصغير","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7210).","chapter_en":"The Pledge of Allegiance of a Child Is Not Valid","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullah ibn Hisham, who had met the Prophet ﷺ, was taken by his mother Zaynab bint Humayd to the Messenger of Allah ﷺ. She said: “Messenger of Allah, accept his pledge.” The Prophet ﷺ said: “He is young.” He wiped his head and supplicated for him. He used to offer one sheep as a sacrifice on behalf of all his family."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7210)."},{"num":7656,"demo":false,"sanad":"","matn":["عَنِ الْهِرْمَاسِ بْنِ زِيَادٍ، قَالَ: مَدَدْتُ يَدِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا غُلاَمٌ لِيُبَايِعَنِي فَلَمْ يُبَايِعْنِي."],"takhrij":"حسن: رواه النسائي (4183) عن عبد الرحمن بن محمد بن سلام، حدثنا عمرو بن يونس، عن عكرمة بن عمار، عن الهرماس بن زياد قال: فذكره.","grade":"حسن","chapter_ar":"باب لا تصح بيعة الصغير","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4183).","chapter_en":"The Pledge of Allegiance of a Child Is Not Valid","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Al-Hirmas ibn Ziyad said: I stretched out my hand to the Prophet ﷺ when I was a boy so that he would accept my pledge, but he did not accept my pledge."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4183)."},{"num":7657,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهَ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَتْ بَنُو إِسْرَائِيلَ تَسُوسُهُمُ الأَنْبِيَاءُ كُلَّمَا هلكَ نبيٌّ خَلَفَهُ نبيٌّ، وَإِنَّهُ لاَ نبيَّ بَعْدِي، وَسَيَكُونُ خُلَفَاءُ فَيَكْثُرُونَ قَالُوا: فَمَا تَأْمُرُنَا؟ قَالَ: فُوا بِبَيْعَةِ الأَوَّلِ فَالأَوَّلِ، أَعْطُوهُمْ حقَّهم، فإنّ اللَّهَ سَائِلُهُمْ عَمَّا اسْتَرْعَاهُمْ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3455)، ومسلم في الإمارة (1842: 44) كلاهما عن محمد بن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، عن فرات القزاز، قال: سمعت أبا حازم قال: قاعدت أبا هريرة خمس سنين فسمعته يحدث فذكره.","grade":"متفق عليه","chapter_ar":"باب الوفاء ببيعة الإمام الأول، ولا يبايع لأكثر من إمام في البلد الواحد","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3455) and Muslim (1842:44).","chapter_en":"Fulfilling the Pledge to the First Leader, and Not Pledging Allegiance to More Than One Leader in One Land","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “The Children of Israel were governed by the prophets. Whenever a prophet died, another prophet succeeded him. There will be no prophet after me, but there will be successors, and they will be many.” They said: “What do you command us?” He said: “Fulfill the pledge to the first, then the first. Give them their right, for Allah will question them about what He entrusted to them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[750],"tks":"متفق عليه: رواه البخاري (3455)، ومسلم (1842:44)."},{"num":7658,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَنَزَلْنَا مَنْزِلًا، فَمِنَّا مَنْ يُصْلِحُ خِبَاءَهُ، وَمِنَّا مَنْ يَنْتَضِلُ، وَمِنَّا مَنْ هُوَ فِي جَشَرِهِ، إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : الصَّلَاةَ جَامِعَةً، فَاجْتَمَعْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ: إِنَّهُ لَمْ يَكُنْ نبيٌّ قَبْلِي إِلَّا كَانَ حَقًّا عَلَيْهِ أَنْ يدلّ أُمَّتَهُ عَلَى خَيْرِ مَا يَعْلَمُهُ لَهُمْ، وَيُنْذِرَهُمْ شَرَّ مَا يَعْلَمُهُ لَهُمْ، وإنَّ أُمَّتَكُمْ هَذِهِ جُعِلَ عَافِيَتُهَا فِي أَوَّلِهَا، وَسَيُصِيبُ آخِرَهَا بَلَاءٌ وَأُمُورٌ تُنْكِرُونَهَا، وَتَجِيءُ فِتْنَةٌ، فَيُرَقِّقُ بَعْضُهَا بَعْضُهَا، وَتَجِيءُ الْفِتْنَةُ، فَيَقُولُ الْمُؤْمِنُ: هَذِهِ مُهْلِكَتِي، ثُمَّ تَنْكَشِفُ وَتَجِيءُ الْفِتْنَةُ، فَيَقُولُ الْمُؤْمِنُ: هَذِهِ هَذِهِ، فَمَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنِ النَّارِ، وَيُدْخَلَ الْجَنَّةَ، فَلْتَأْتِهِ مَنِيَّتُهُ وَهُوَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ، وَلْيَأْتِ إِلَى النَّاسِ الَّذِي يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ، وَمَنْ بَايَعَ إِمَامًا فَأَعْطَاهُ صَفْقَةَ يَدِهِ وَثَمَرَةَ قَلْبِهِ، فَلْيُطِعْهُ إِنِ اسْتَطَاعَ، فَإِنْ جَاءَ آخَرُ يُنَازِعُهُ فَاضْرِبُوا عُنُقَ الْآخَرِ فَدَنَوْتُ مِنْهُ فَقُلْتُ: أَنْشُدُكَ اللَّهَ آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ فَأَهْوَى إِلَى أُذُنَيْهِ وَقَلْبِهِ بِيَدَيْهِ، وَقَالَ: سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي، فَقُلْتُ لَهُ: هَذَا ابْنُ عَمِّكَ مُعَاوِيَةُ يَأْمُرُنَا أَنْ نَأْكُلَ أَمْوَالَنَا بَيْنَنَا بِالْبَاطِلِ، وَنَقْتُلَ أَنْفُسَنَا، وَاللهُ يَقُولُ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا﴾ [سورة النساء: 29] قَالَ: فَسَكَتَ سَاعَةً، ثُمَّ قَالَ: أطِعْه فِي طَاعَةِ اللهِ، واعْصِه فِي مَعْصِيَةِ اللهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1844) من طريقين عن جرير، عن الأعمش، عن زيد بن وهب، عن عبدالرحمن بن عبد رب الكعبة قال: دخلتُ المسجدَ، فإذا عبدالله بن عمرو بن العاص جالس في ظلّ الكعبة، والناس مجتمعون عليه، فأتيتهم، فجلستُ إليه قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الوفاء ببيعة الإمام الأول، ولا يبايع لأكثر من إمام في البلد الواحد","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Leadership (1844).","chapter_en":"Fulfilling the Pledge to the First Leader, and Not Pledging Allegiance to More Than One Leader in One Land","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: We were with the Messenger of Allah ﷺ on a journey, and we stopped at a place. Some of us were repairing their tents, some were practicing archery, and some were with their grazing animals, when the caller of the Messenger of Allah ﷺ called out: “The prayer is gathering.” So we gathered around the Messenger of Allah ﷺ and he said: “There was no prophet before me except that it was his duty to guide his nation to the best of what he knew for them, and to warn them against the worst of what he knew for them. This nation of yours has had its well-being placed in its beginning, and its latter part will be afflicted by trials and matters you will disapprove of. A trial will come, and each one will make the previous one seem light. A trial will come, and the believer will say: ‘This is my destruction.’ Then it will be removed, and another trial will come, and the believer will say: ‘This, this.’ Whoever loves to be moved away from the Fire and admitted into Paradise, let death come to him while he believes in Allah and the Last Day, and let him treat people in the way he loves to be treated. Whoever pledges allegiance to a leader, giving him the clasp of his hand and the fruit of his heart, let him obey him if he is able. If another comes to challenge him, then strike the neck of the latter.” I drew near to him and said: “I ask you by Allah, did you yourself hear this from the Messenger of Allah ﷺ?” He pointed with his hands to his ears and heart and said: “My ears heard it, and my heart understood it.” I said to him: “This cousin of yours, Muʿawiyah, commands us to consume our wealth among ourselves falsely and to kill ourselves, while Allah says: ‘O you who believe, do not consume your wealth among yourselves falsely, except through trade by mutual consent among you, and do not kill yourselves. Indeed, Allah is Merciful to you.’” He remained silent for a while, then said: “Obey him in obedience to Allah, and disobey him in disobedience to Allah.”"]},"buhuth":{"en":["His word “grazing animals”: Abu ʿUbayd said it refers to people who go out to pasture with their animals. Al-Asmaʿi said: They spend the night there, and some may think it is a journey in which the prayer may be shortened, but that is not the case.","His statement, “This nation of yours has had its well-being placed in its beginning, and its latter part will be afflicted by trials and matters you will disapprove of,” refers to the beginning of the nation: the era of the Prophet ﷺ and the era of the first three caliphs until ʿUthman, may Allah be pleased with him, was killed. Those years were the time of the unity of this nation and the stability of its affair. When ʿUthman was killed, trials surged like the waves of the sea and followed one another like pieces of a dark night, and they have continued one after another until our present day.","The statement of ʿAbd al-Rahman ibn ʿAbd Rabb al-Kaʿbah, “This cousin of yours, Muʿawiyah, commands us to consume our wealth among ourselves falsely and to kill ourselves,” means that ʿAbd al-Rahman ibn ʿAbd Rabb al-Kaʿbah understood this description to apply to Muʿawiyah ibn Abi Sufyan because of his dispute with ʿAli, may Allah be pleased with him, while the pledge to ʿAli had already preceded. He therefore viewed Mu‘awiyah’s spending of wealth on his soldiers and followers in the war against ʿAli as consuming wealth falsely.","This ʿAbd al-Rahman was not known for partisanship toward ʿAli, so this statement is understood as his own conclusion, not as a textual proof that people’s wealth was being consumed falsely.","Some of the early scholars said: If lands are far apart, then it is permissible for each land to have a ruler, as is the case today."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1844)."},{"num":7659,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلاَثَةٌ لاَ يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلاَ يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ: رَجُلٌ عَلَى فَضْلِ مَاءٍ بِالطَّرِيقِ يَمْنَعُ مِنْهُ ابْنَ السَّبِيلِ، وَرَجُلٌ بَايَعَ إِمَامًا لاَ يُبَايِعُهُ إِلاَّ لِدُنْيَاهُ، إِنْ أَعْطَاهُ مَا يُرِيدُ وَفَى لَهُ، وَإِلاَّ لَمْ يَفِ لَهُ، وَرَجُلٌ يُبَايِعُ رَجُلاً بِسِلْعَةٍ بَعْدَ الْعَصْرِ فَحَلَفَ بِاللَّهِ، لَقَدْ أُعْطِيَ بِهَا كَذَا وَكَذَا فَصَدَّقَهُ، فَأَخَذَهَا، وَلَمْ يُعْطَ بِهَا."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7212)، ومسلم في الإيمان (108: 173) كلاهما من طريق الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إثم من لم يف بالبيعة إلا من أجل الدنيا","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7212) and Muslim (108:173).","chapter_en":"The Sin of One Who Does Not Fulfill the Pledge Except for Worldly Gain","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There are three whom Allah will not speak to on the Day of Resurrection, will not purify, and for whom there will be a painful punishment: a man who has surplus water on the road but prevents a traveler from it; a man who pledges allegiance to a leader only for worldly gain, so if he gives him what he wants he fulfills it, and if not he does not fulfill it; and a man who sells an item to another man after the late afternoon prayer and swears by Allah that he was offered such and such for it, so the buyer believes him and takes it, though he was not offered that amount.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7212)، ومسلم (108:173)."},{"num":7660,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ: أَنَّ أَعْرَابِيًّا بَايَعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَأَصَابَ الأَعْرَابِيَّ وَعْكٌ بِالْمَدِينَةِ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدِ! أَقِلْنِي بَيْعَتِي، فَأَبَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ جَاءَهُ فَقَالَ: أَقِلْنِي بَيْعَتِي، فَأَبَى، ثُمَّ جَاءَهُ فَقَالَ: أَقِلْنِي بَيْعَتِي فَأَبَى، فَخَرَجَ الأَعْرَابِيُّ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّمَا الْمَدِينَةُ كَالْكِيرِ تَنْفِي خَبَثَهَا، وَيَنْصَعُ طِيبُهَا."],"takhrij":"متفق عليه: رواه مالك في الجامع (4) عن محمد بن المنكدر، عن جابر بن عبدالله فذكره. ورواه البخاري في الأحكام (7211)، ومسلم في الحج (383: 489) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب الترهيب من نقض البيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (4), al-Bukhari (7211), and Muslim (383:489).","chapter_en":"Warning Against Breaking the Pledge of Allegiance","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that a Bedouin pledged allegiance to the Messenger of Allah ﷺ, then the Bedouin suffered fever in Madinah. He came to the Prophet ﷺ and said: “Muhammad, release me from my pledge.” The Messenger of Allah ﷺ refused. Then he came again and said: “Release me from my pledge.” He refused. Then he came again and said: “Release me from my pledge.” He refused. So the Bedouin left. The Messenger of Allah ﷺ said: “Madinah is only like a furnace: it removes its impurity and purifies its goodness.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (4)، والبخاري (7211)، ومسلم (383:489)."},{"num":7661,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، قَالَ لَمَّا خَلَعَ أَهْلُ الْمَدِينَةِ يَزِيدَ بْنَ مُعَاوِيَةَ جَمَعَ ابْنُ عُمَرَ حَشَمَهُ وَوَلَدَهُ فَقَالَ إِنِّي سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُنْصَبُ لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ. وَإِنَّا قَدْ بَايَعْنَا هَذَا الرَّجُلَ عَلَى بَيْعِ اللَّهِ وَرَسُولِهِ، وَإِنِّي لاَ أَعْلَمُ غَدْرًا أَعْظَمَ مِنْ أَنْ يُبَايَعَ رَجُلٌ عَلَى بَيْعِ اللَّهِ وَرَسُولِهِ، ثُمَّ يُنْصَبُ لَهُ الْقِتَالُ، وَإِنِّي لاَ أَعْلَمُ أَحَدًا مِنْكُمْ خَلَعَهُ، وَلاَ بَايَعَ فِي هَذَا الأَمْرِ، إِلاَّ كَانَتِ الْفَيْصَلَ بَيْنِي وَبَيْنَهُ."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7111) عن سليمان بن حرب، عن حماد بن زيد، عن نافع ذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من نقض البيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7111).","chapter_en":"Warning Against Breaking the Pledge of Allegiance","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Nafiʿ said: When the people of Madinah removed Yazid ibn Muʿawiyah, Ibn ʿUmar gathered his servants and children and said: I heard the Prophet ﷺ say: “A banner will be raised for every betrayer on the Day of Resurrection.” We have pledged allegiance to this man upon the pledge of Allah and His Messenger, and I do not know of any betrayal greater than that a man should pledge allegiance upon the pledge of Allah and His Messenger, then set up fighting against him. I do not know of anyone among you who removes him, or pledges allegiance in this affair, except that there will be separation between me and him."]},"buhuth":{"en":["His word “separation” means cutting off and abandonment. Ibn Hajar said: In this hadith is the obligation of obeying the leader whose pledge has been established, and the prohibition of revolting against him even if he is unjust in his rule, and that he is not removed by sinful conduct. Fath al-Bari (13/71)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7111)."},{"num":7662,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ قَالَ:  جَاءَ عَبْدُ اللَّهِ بْنُ عُمَرَ إِلَى عَبْدِ اللَّهِ بْنِ مُطِيعٍ حِينَ كَانَ مِنْ أَمْرِ الْحَرَّةِ مَا كَانَ زَمَنَ يَزِيدَ بْنِ مُعَاوِيَةَ، فَقَالَ: اطْرَحُوا لِأَبِي عَبْدِ الرَّحْمَنِ وِسَادَةً، فَقَالَ: إِنِّي لَمْ آتِكَ لِأَجْلِسَ، أَتَيْتُكَ لِأُحَدِّثَكَ حَدِيثًا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُهُ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ خَلَعَ يَدًا مِنْ طَاعَةٍ لَقِيَ اللَّهَ يَوْمَ الْقِيَامَةِ لَا حُجَّةَ لَهُ، وَمَنْ مَاتَ وَلَيْسَ فِي عُنُقِهِ بَيْعَةٌ مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"صحيح: رواه مسلم في الإمارة (1851: 58) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا عاصم -وهو بن محمد بن زيد- عن زيد بن محمد، عن نافع قال: فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1851:58).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Nafiʿ said: ʿAbdullah ibn ʿUmar came to ʿAbdullah ibn Mutiʿ when the event of al-Harrah occurred during the time of Yazid ibn Muʿawiyah. He said: “Place a cushion for Abu ʿAbd al-Rahman.” He said: “I did not come to you to sit. I came to narrate to you a hadith I heard the Messenger of Allah ﷺ say. I heard the Messenger of Allah ﷺ say: ‘Whoever withdraws his hand from obedience will meet Allah on the Day of Resurrection with no proof for himself, and whoever dies without a pledge of allegiance upon his neck dies a death of the age of ignorance.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1851:58)."},{"num":7663,"demo":false,"sanad":"","matn":["عَنْ جُنْدَُبِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ قُتِلَ تَحْتَ رَايَةٍ عُِمِّيَّةٍ، يَدْعُو عَصَبِيَّةً أَوْ يَنْصُرُ عَصَبِيَّةً، فَقِتْلَةٌ جَاهِلِيَّةٌ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1850: 57) عن هُريم بن عبد الأعلى، حدثنا المعتمر قال: سمعت أبي يحدث عن أبي مجلز عن جندب بن عبد الله البجلي قال: فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1850:57).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Jundub ibn ʿAbdullah al-Bajali said: The Messenger of Allah ﷺ said: “Whoever is killed under a blind banner, calling to partisanship or supporting partisanship, then his killing is a killing of the age of ignorance.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1850:57)."},{"num":7664,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  مَنْ خَرَجَ مِنَ الطَّاعَةِ وَفَارَقَ الْجَمَاعَةَ فَمَاتَ مَاتَ مِيتَةً جَاهِلِيَّةً، وَمَنْ قَاتَلَ تَحْتَ رَايَةٍ عُِمِّيَّةٍ، يَغْضَبُ لِعَصَبَةٍ، أَوْ يَدْعُو إِلَى عَصَبَةٍ، أَوْ يَنْصُرُ عَصَبَةً فَقُتِلَ فَقِتْلَةٌ جَاهِلِيَّةٌ، وَمَنْ خَرَجَ عَلَى أُمَّتِي يَضْرِبُ بَرَّهَا وَفَاجِرَهَا، وَلَا يَتَحَاشَ مِنْ مُؤْمِنِهَا وَلَا يَفِي لِذِي عَهْدٍ عَهْدَهُ، فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1848) عن شيبان بن فروخ، حدثنا جرير بن حازم، حدثنا غيلان بن جرير، عن أبي قيس بن رياح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1848).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Whoever leaves obedience, separates from the community, and then dies, dies a death of the age of ignorance. Whoever fights under a blind banner, becoming angry for a faction, calling to a faction, or supporting a faction, and is killed, then his killing is a killing of the age of ignorance. Whoever rebels against my nation, striking its righteous and wicked alike, not sparing its believer, and not fulfilling the covenant of the one under covenant, then he is not from me and I am not from him.”"]}},"tuhfa":{},"full":1,"rep":[15013],"tks":"صحيح: رواه مسلم (1848)."},{"num":7665,"demo":false,"sanad":"","matn":["عَنْ رِبْعِىِّ بْنِ حِرَاشٍ قَالَ: انْطَلَقْتُ إِلَى حُذَيْفَةَ بِالْمَدَائِنِ لَيَالِيَ سَارَ النَّاسُ إِلَى عُثْمَانَ، فَقَالَ: يَا رِبْعِيُّ، مَا فَعَلَ قَوْمُكَ؟ قَالَ: قُلْتُ: عَنْ أَيِّ بَالِهِمْ تَسْأَلُ؟ قَالَ: مَنْ خَرَجَ مِنْهُمْ إِلَى هَذَا الرَّجُلِ، فَسَمَّيْتُ رِجَالًا فِيمَنْ خَرَجَ إِلَيْهِ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ فَارَقَ الْجَمَاعَةَ وَاسْتَذَلَّ الْإِمَارَةَ لَقِيَ اللَّهَ وَلَا وَجْهَ لَهُ عِنْدَهُ."],"takhrij":"حسن: رواه أحمد (23283، 23284) من طرق عن أبي النضر كثير بن أبي كثير، حدثنا ربعي بن حراش فذكره.","grade":"حسن","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23284, 23283).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Ribʿi ibn Hirash said: I went to Hudhayfah in al-Mada’in during the nights when people marched against ʿUthman. He said: “Ribʿi, what have your people done?” I said: “Which of their affairs are you asking about?” He said: “Who among them went out against this man?” So I named men among those who went out against him. He said: I heard the Messenger of Allah ﷺ say: “Whoever separates from the community and humiliates leadership will meet Allah with no standing before Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23284، 23283)."},{"num":7666,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ مَاتَ بِغَيْرِ إِمَامٍ، مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"حسن: رواه أحمد (16876)، وصحّحه ابن حبان (4573) كلاهما من طرق عن أبي بكر بن عياش، عن عاصم بن أبي النجود، عن أبي صالح، عن معاوية فذكره.","grade":"حسن","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (16876), graded authentic by Ibn Hibban (4573), and by Ibn Abi ʿAsim in al-Sunnah (1091).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Muʿawiyah said: The Messenger of Allah ﷺ said: “Whoever dies without a leader dies a death of the age of ignorance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (16876)، وصححه ابن حبان (4573)، وابن أبي عاصم في السنة (1091)."},{"num":7667,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عبيد، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: ثَلَاثَةٌ لَا تَسْأَلْ عَنْهُمْ: رَجُلٌ فَارَقَ الْجَمَاعَةَ، وَعَصَى إِمَامَهُ، وَمَاتَ عَاصِيًا، وَأَمَةٌ أَوْ عَبْدٌ أَبَقَ فَمَاتَ، وَامْرَأَةٌ غَابَ عَنْهَا زَوْجُهَا، قَدْ كَفَاهَا مُؤْنَةَ الدُّنْيَا فَتَبَرَّجَتْ بَعْدَهُ، فَلَا تَسْأَلْ عَنْهُمْ، وَثَلَاثَةٌ لَا تَسْأَلْ عَنْهُمْ: رَجُلٌ نَازَعَ اللهَ رِدَاءَهُ، فَإِنَّ رِدَاءَهُ الْكِبْرِيَاءُ وَإِزَارَهُ الْعِزَّةُ، وَرَجُلٌ شَكَّ فِي أَمْرِ اللهِ وَالْقَنُوطُ مِنْ رَحْمَةِ اللَّهِ."],"takhrij":"صحيح: رواه أحمد (23943)، وصحّحه ابن حبان (4559)، والحاكم (411) كلهم من طريق أبي عبد الرحمن عبد الله بن يزيد المقرئ، حدثنا حيوة، حدثنا أبو هانئ، أن أبا علي عمرو بن مالك الجنبي حدثه عن فضالة بن عبيد فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23943), graded authentic by Ibn Hibban (4559), and al-Hakim (1/119).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Fadalah ibn ʿUbayd narrated from the Messenger of Allah ﷺ that he said: “There are three about whom you should not ask: a man who separates from the community, disobeys his leader, and dies in disobedience; a female slave or male slave who runs away and dies; and a woman whose husband is absent, while he has provided her with enough worldly provision, but she displays herself after him, so do not ask about them. And three about whom you should not ask: a man who contends with Allah over His cloak, for His cloak is majesty and His lower garment is might; a man who doubts the command of Allah; and one who despairs of the mercy of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23943)، وصححه ابن حبان (4559)، والحاكم (411)."},{"num":7668,"demo":false,"sanad":"","matn":["عن محمد بن زيد بن عبد الله بن عمر قال: قال أناس لابن عمر: إنا ندخل على سلطاننا فنقول لهم خلاف ما نتكلم إذا خرجنا من عندهم قال: كنا نعدها نفاقا. وفي رواية: كنا نعدُّ هذا نفاقا على عهد النبي صلى الله عليه وسلم."],"takhrij":"صحيح: رواه البخاري في الأحكام (7178) عن أبي نعيم، حدثنا عاصم بن محمد بن زيد بن عبد الله بن عمر، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب كراهية المبالغة في مدح السلطان في وجهه والطعن عليه في غيبته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7178). The other wording was narrated by al-Tayalisi (2067), Ibn Majah (3975), and Ahmad (5829).","chapter_en":"The Dislike of Excessively Praising the Ruler to His Face and Criticizing Him in His Absence","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Muhammad ibn Zayd ibn ʿAbdullah ibn ʿUmar said: Some people said to Ibn ʿUmar: “We enter upon our rulers and say to them the opposite of what we say when we leave them.” He said: “We used to count that as hypocrisy.” In another wording: “We used to count this as hypocrisy during the time of the Prophet ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7178)، والرواية الأخرى رواها الطيالسي (2067)، وابن ماجه (3975)، وأحمد (5829)."},{"num":7669,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِكَعْبِ بْنِ عُجْرَةَ: أَعَاذَكَ اللَّهُ مِنْ إِمَارَةِ السُّفَهَاءِ، قَالَ: وَمَا إِمَارَةُ السُّفَهَاءِ؟، قَالَ: أُمَرَاءُ يَكُونُونَ بَعْدِي، لَا يَقْتَدُونَ بِهَدْيِي، وَلَا يَسْتَنُّونَ بِسُنَّتِي، فَمَنْ صَدَّقَهُمْ بِكَذِبِهِمْ، وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ، فَأُولَئِكَ لَيْسُوا مِنِّي، وَلَسْتُ مِنْهُمْ، وَلَا يَرِدُوا عَلَيَّ حَوْضِي، وَمَنْ لَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ، وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ، فَأُولَئِكَ مِنِّي وَأَنَا مِنْهُمْ، وَسَيَرِدُوا عَلَيَّ حَوْضِي. يَا كَعْبُ بْنَ عُجْرَةَ، الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ، وَالصَّلَاةُ قُرْبَانٌ - أَوْ قَالَ: بُرْهَانٌ - يَا كَعْبُ بْنَ عُجْرَةَ، إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ لَحْمٌ نَبَتَ مِنْ سُحْتٍ، النَّارُ، أَوْلَى بِهِ. يَا كَعْبُ بْنَ عُجْرَةَ، النَّاسُ غَادِيَانِ: فَمُبْتَاعٌ نَفْسَهُ فَمُعْتِقُهَا، وَبَائِعٌ نَفْسَهُ فَمُوبِقُهَا."],"takhrij":"حسن: رواه أحمد (14441) عن عبد الرزاق، أخبرنا معمر، عن ابن خثيم، عن عبد الرحمن بن سابط، عن جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إمارة السفهاء، والزجر عن إعانتهم على ظلمهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14441) and ʿAbd al-Razzaq (20719).","chapter_en":"What Has Been Reported Concerning the Leadership of Foolish People, and the Warning Against Helping Them in Their Oppression","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that the Prophet ﷺ said to Kaʿb ibn ʿUjrah: “May Allah protect you from the leadership of foolish people.” He said: “What is the leadership of foolish people?” He said: “Leaders who will come after me; they will not follow my guidance and will not act according to my way. Whoever believes them in their lies and helps them in their oppression, they are not from me and I am not from them, and they will not come to my reservoir. Whoever does not believe them in their lies and does not help them in their oppression, they are from me and I am from them, and they will come to my reservoir. Kaʿb ibn ʿUjrah, fasting is a shield, charity extinguishes sin, and prayer is nearness — or he said: proof. Kaʿb ibn ʿUjrah, no flesh that grows from unlawful earnings will enter Paradise; the Fire is more deserving of it. Kaʿb ibn ʿUjrah, people go out in two ways: one buys himself and frees himself, and another sells himself and destroys himself.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[859],"tks":"حسن: رواه أحمد (14441)، وعبد الرزاق (20719)."},{"num":7670,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ عُجْرَةَ، قَالَ: خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ تِسْعَةٌ، خَمْسَةٌ، وَأَرْبَعَةٌ، أَحَدُ الْعَدَدَيْنِ مِنَ الْعَرَبِ، وَالآخَرُ مِنَ الْعَجَمِ، فَقَالَ: اسْمَعُوا، هَلْ سَمِعْتُمْ أَنَّهُ سَيَكُونُ بَعْدِي أُمَرَاءُ، فَمَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِكَذِبِهِمْ، وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ، وَلَيْسَ بِوَارِدٍ عَلَىَّ الْحَوْضَ، وَمَنْ لَمْ يَدْخُلْ عَلَيْهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ وَلَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ، وَهُوَ وَارِدٌ عَلَىَّ."],"takhrij":"صحيح: رواه الترمذي (2259)، والنسائي (4207، 4208)، وأحمد (18126)، وابن حبان (282، 283، 285)، والحاكم (263) كلهم من طريق أبي حصين، (هو عثمان بن عاصم الأسدي)، عن الشّعبيّ، عن عاصم العدويّ، عن كعب بن عُجرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إمارة السفهاء، والزجر عن إعانتهم على ظلمهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (2259), al-Nasa’i (4208, 4207), and Ahmad (18126), graded authentic by Ibn Hibban (282, 283, 285), and narrated by al-Hakim (263).","chapter_en":"What Has Been Reported Concerning the Leadership of Foolish People, and the Warning Against Helping Them in Their Oppression","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Kaʿb ibn ʿUjrah said: The Messenger of Allah ﷺ came out to us while we were nine: five and four, one of the two numbers being Arabs and the other non-Arabs. He said: “Listen. Have you heard that there will be leaders after me? Whoever enters upon them, believes them in their lies, and helps them in their oppression, he is not from me and I am not from him, and he will not come to my reservoir. Whoever does not enter upon them, does not help them in their oppression, and does not believe them in their lies, he is from me and I am from him, and he will come to me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2259)، والنسائي (4208، 4207)، وأحمد (18126)، وصححه ابن حبان (282، 283، 285)، والحاكم (263)."},{"num":7671,"demo":false,"sanad":"","matn":["عن حُذَيْفَةَ بن الْيَمَانِ يَقُولُ: كَانَ النَّاسُ يَسْأَلُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَيْرِ، وَكُنْتُ أَسْأَلُهُ عَنِ الشَّرِّ، مَخَافَةَ أَنْ يُدْرِكَنِي فَقُلْتُ: يَا رَسُولَ اللَّهِ إِنَّا كُنَّا فِي جَاهِلِيَّةٍ وَشَرٍّ فَجَاءَنَا اللَّهُ بِهَذَا الْخَيْرِ، فَهَلْ بَعْدَ هَذَا الْخَيْرِ مِنْ شَرٍّ؟ قَالَ: نَعَمْ. قُلْتُ: وَهَلْ بَعْدَ ذَلِكَ الشَّرِّ مِنْ خَيْرٍ؟ قَالَ: نَعَمْ، وَفِيهِ دَخَنٌ. قُلْتُ: وَمَا دَخَنُهُ؟ قَالَ: قَوْمٌ يَهْدُونَ بِغَيْرِ هَدْىٍ، تَعْرِفُ مِنْهُمْ وَتُنْكِرُ. قُلْتُ: فَهَلْ بَعْدَ ذَلِكَ الْخَيْرِ مِنْ شَرٍّ؟ قَالَ: نَعَمْ، دُعَاةٌ عَلَى أَبْوَابِ جَهَنَّمَ، مَنْ أَجَابَهُمْ إِلَيْهَا قَذَفُوهُ فِيهَا. قُلْتُ: يَا رَسُولَ اللَّهِ صِفْهُمْ لَنَا. قَالَ: هُمْ مِنْ جِلْدَتِنَا، وَيَتَكَلَّمُونَ بِأَلْسِنَتِنَا. قُلْتُ: فَمَا تَأْمُرُنِي إِنْ أَدْرَكَنِي ذَلِكَ قَالَ: تَلْزَمُ جَمَاعَةَ الْمُسْلِمِينَ وَإِمَامَهُمْ. قُلْتُ: فَإِنْ لَمْ يَكُنْ لَهُمْ جَمَاعَةٌ وَلاَ إِمَامٌ قَالَ: فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا، وَلَوْ أَنْ تَعَضَّ بِأَصْلِ شَجَرَةٍ، حَتَّى يُدْرِكَكَ الْمَوْتُ، وَأَنْتَ عَلَى ذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7084)، ومسلم في الإمارة (1847) كلاهما عن محمد بن المثنى، حدثنا الوليد بن مسلم، حدثنا ابن جابر، حدثني بسر بن عبيدالله الحضرمي، أنه سمع أبا إدريس الخولاني، أنه سمع حذيفة بن اليمان يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب لزوم جماعة المسلمين وإمامهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7084) and Muslim (1847).","chapter_en":"The Obligation of Adhering to the Community of Muslims and Their Leader","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Hudhayfah ibn al-Yaman said: People used to ask the Messenger of Allah ﷺ about good, while I used to ask him about evil, fearing that it might reach me. I said: “Messenger of Allah, we were in ignorance and evil, then Allah brought us this good. Will there be evil after this good?” He said: “Yes.” I said: “Will there be good after that evil?” He said: “Yes, but in it there will be impurity.” I said: “What is its impurity?” He said: “People who guide by other than my guidance; you will recognize some of what they do and reject some.” I said: “Will there be evil after that good?” He said: “Yes, callers at the gates of Hell; whoever responds to them, they will throw him into it.” I said: “Messenger of Allah, describe them to us.” He said: “They are from our own people and speak our language.” I said: “What do you command me to do if that reaches me?” He said: “Adhere to the community of Muslims and their leader.” I said: “What if they have no community and no leader?” He said: “Then withdraw from all those groups, even if you must bite onto the root of a tree until death reaches you while you are upon that.”"]},"buhuth":{"en":["His statement in the hadith, “Adhere to the community of Muslims,” al-Tabari said: “Meaning those who are in obedience to the one whom they have collectively appointed as leader. Whoever breaks his pledge has left the community.” He said: “In the hadith is that whenever people have no leader and split into factions, one should not follow anyone into division, and should withdraw from all of them if able, out of fear of falling into evil.” See Fath al-Bari (10/37)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15752],"tks":"متفق عليه: رواه البخاري (7084)، ومسلم (1847)."},{"num":7672,"demo":false,"sanad":"","matn":["عَنْ تَمِيمٍ الدَّارِيِّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  الدِّينُ النَّصِيحَةُ، قُلْنَا: لِمَنْ؟ قَالَ: لِلهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (55) عن محمد بن عباد المكي، حدثنا سفيان قال: قلت لسهيل: إن عمرا حدثنا عن القعقاع، عن أبيك. قال: ورجوت أن يسقط عني رجلا قال: فقال: سمعته من الذي سمعه منه أبي -كان صديقا له بالشام- ثم حدثنا سفيان، عن سهيل، عن عطاء بن يزيد، عن تميم الداري فذكره.","grade":"صحيح","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (55).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Tamim al-Dari narrated that the Prophet ﷺ said: “Religion is sincere counsel.” We said: “For whom?” He said: “For Allah, His Book, His Messenger, the leaders of the Muslims, and their common people.”"]},"intro":{"ar":["وقد أرسل الله تعالى موسى وهارون إلى فرعون فقال: (اذْهَبَا إِلَىٰ فِرْعَوْنَ إِنَّهُ طَغَىٰ ٤٣ فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَىٰ) [طه: ٤٣-٤٤]"],"en":["Allah the Exalted sent Moses and Aaron to Pharaoh and said: “Go, both of you, to Pharaoh. Indeed, he has transgressed. And speak to him with gentle speech, that perhaps he may remember or fear.” [Surah Ta Ha: 43–44]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[145],"tks":"صحيح: رواه مسلم (55)."},{"num":7673,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الدِّينُ النَّصِيحَةُ، قَالَ: قُلْنَا: لِمَنْ يَا رَسُولَ اللَّهِ؟، قَالَ: لِلَّهِ، وَلِرَسُولِهِ، وَلِكِتَابِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ."],"takhrij":"حسن: رواه البزار – كشف الأستار (62)، والدارمي (2796)، والطحاوي في شرح المشكل (1447) كلهم من طرقٍ عن هشام بن سعد، عن زيد بن أسلم ونافع، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar — Kashf al-Astar (62), al-Darimi (2796), and al-Tahawi in Sharh al-Mushkil (1447).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said to us: “Religion is sincere counsel.” He said: We said: “For whom, Messenger of Allah?” He said: “For Allah, His Messenger, His Book, the leaders of the Muslims, and their common people.”"]},"buhuth":{"en":["The meaning of sincere counsel for Allah, Glorified is He, is sound belief in His oneness and sincerity of intention in worshiping Him. Sincere counsel for the Book of Allah is to believe in it and act according to what is in it. Sincere counsel for His Messenger is to affirm his prophethood and give obedience to him in what he commanded and forbade. Sincere counsel for the leaders of the Muslims is to obey them in truth and not to consider revolt against them with the sword if they are unjust. Sincere counsel for the general Muslims is to guide them to what benefits them. This was mentioned by al-Khattabi in Maʿalim al-Sunan."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار — كشف الأستار (62)، والدارمي (2796)، والطحاوي في شرح المشكل (1447)."},{"num":7674,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن ثَابِتٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ثَلَاثُ خِصَالٍ لَا يغلّ عَلَيْهِنَّ قَلْبُ مُسْلِمٍ أَبَدًا: إِخْلَاصُ الْعَمَلِ لِلَّهِ، وَمُنَاصَحَةُ وُلَاةِ الْأَمْرِ، وَلُزُومُ الْجَمَاعَةِ، فَإِنَّ دَعْوَتَهُمْ تُحِيطُ مِنْ وَرَائِهِمْ."],"takhrij":"صحيح: رواه أحمد (21590)، وصحّحه ابن حبان (67) كلاهما من طريق شعبة، حدثنا عمر بن سليمان من ولد عمر بن الخطاب، عن عبد الرحمن بن أبان بن عثمان، عن أبيه، عن زيد بن ثابت فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (21590), and graded authentic by Ibn Hibban (67).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Zayd ibn Thabit said: I heard the Messenger of Allah ﷺ say: “There are three qualities over which the heart of a Muslim will never harbor rancor: making deeds sincere for Allah, sincerely advising those in authority, and adhering to the community; for their supplication surrounds those behind them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21590)، وصححه ابن حبان (67)."},{"num":7675,"demo":false,"sanad":"","matn":["عن شريح بْنِ عبيد الحضرمي، وَغَيْرُهُ، قَالَ: جَلَدَ عِيَاضُ بْنُ غَنْمٍ صَاحِبَ دَارَا حِينَ فُتِحَتْ، فَأَغْلَظَ لَهُ هِشَامُ بْنُ حَكِيمٍ الْقَوْلَ حَتَّى غَضِبَ عِيَاضٌ، ثُمَّ مَكَثَ لَيَالِيَ، فَأَتَاهُ هِشَامُ بْنُ حَكِيمٍ فَاعْتَذَرَ إِلَيْهِ، ثُمَّ قَالَ هِشَامٌ لِعِيَاضٍ: أَلَمْ تَسْمَعِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ مِنْ أَشَدِّ النَّاسِ عَذَابًا، أَشَدَّهُمْ عَذَابًا فِي الدُّنْيَا لِلنَّاسِ؟ ؟ فَقَالَ عِيَاضُ بْنُ غَنْمٍ: يَا هِشَامُ بْنَ حَكِيمٍ، قَدْ سَمِعْنَا مَا سَمِعْتَ، وَرَأَيْنَا مَا رَأَيْتَ، أَوَلَمْ تَسْمَعْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ: مَنْ أَرَادَ أَنْ يَنْصَحَ لِسُلْطَانٍ بِأَمْرٍ، فَلَا يُبْدِ لَهُ عَلَانِيَةً، وَلَكِنْ لِيَأْخُذْ بِيَدِهِ، فَيَخْلُوَ بِهِ، فَإِنْ قَبِلَ مِنْهُ فَذَاكَ، وَإِلَّا كَانَ قَدْ أَدَّى الَّذِي عَلَيْهِ لَهُ، وَإِنَّكَ يَا هِشَامُ لَأَنْتَ الْجَرِيءُ، إِذْ تَجْتَرِئُ عَلَى سُلْطَانِ اللهِ، فَهَلَّا خَشِيتَ أَنْ يَقْتُلَكَ السُّلْطَانُ، فَتَكُونَ قَتِيلَ سُلْطَانِ اللهِ تَبَارَكَ وَتَعَالَى."],"takhrij":"حسن: رواه أحمد (15333) عن أبي المغيرة، حدثنا صفوان، حدثنا شريح بن عبيد الحضرمي وغيره فذكروه.","grade":"حسن","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (15333).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Shurayh ibn ʿUbayd al-Hadrami and others said: ʿIyad ibn Ghanm flogged the governor of Dara when it was conquered, so Hisham ibn Hakim spoke harshly to him until ʿIyad became angry. Then some nights passed, and Hisham ibn Hakim came to him and apologized to him. Then Hisham said to ʿIyad: “Did you not hear the Prophet ﷺ say: ‘Among the people most severely punished are those who punish people most severely in this world’?” ʿIyad ibn Ghanm said: “Hisham ibn Hakim, we have heard what you heard, and we have seen what you saw. Did you not hear the Messenger of Allah ﷺ say: ‘Whoever wishes to advise a ruler regarding a matter should not do so openly. Rather, let him take him by the hand and be alone with him. If he accepts from him, then that is it; otherwise, he has fulfilled what was due from him toward him.’ Hisham, you are indeed bold, since you are bold against the authority of Allah. Did you not fear that the ruler might kill you, so that you would be killed by the authority of Allah, Blessed and Exalted?”"]},"buhuth":{"en":["The methodology of the people of the Prophetic way and the Muslim community is to advise those in authority privately, and that this should not be done upon pulpits and in public gatherings.","The Companions used to advise governors privately. It was said to Usamah ibn Zayd: “What prevents you from entering upon ʿUthman and speaking to him about what he is doing?” Usamah replied: “Do you think that I do not speak to him unless I make you hear it? I speak to him privately, without opening a door that I would not like to be the first to open.” Narrated by al-Bukhari (3267) and Muslim (2989).","His Eminence Shaykh ʿAbd al-ʿAziz ibn Baz, may Allah have mercy on him, said: “It is not from the methodology of the early generations to publicize the faults of rulers and mention that upon pulpits, because that leads to upheavals, to abandoning hearing and obeying in what is right, and to rebellion that harms and does not benefit. Rather, the way followed by the early generations was to advise privately between themselves and the ruler, to write to him, or to contact the scholars who could reach him so that he would be directed to good.” Rights of the Shepherd and the Flock, pages 27–28, the Shaykh’s verdict at the end of the mentioned treatise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15333)."},{"num":7676,"demo":false,"sanad":"","matn":["عن عرفجة قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِنَّهُ سَتَكُونُ هَنَاتٌ وَهَنَاتٌ، فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ هَذِهِ الْأُمَّةِ، وَهِْيَ جَمِيعٌ، فَاضْرِبُوهُ بِالسَّيْفِ كَائِنًا مَنْ كَانَ.","وفي لفظ: رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم عَلَى الْمِنْبَرِ يَخْطُبُ النَّاسَ، فَقَالَ: إِنَّهُ سَيَكُونُ بَعْدِي هَنَاتٌ وَهَنَاتٌ، فَمَنْ رَأَيْتُمُوُه فَارَقَ الْجَمَاعَةَ، أَوْ يُرِيدُ يُفَرِّقُ أَمْرَ أُمَّةِ مُحَمَّدٍ صلى الله عليه وسلم كَائِنًا مَنْ كَانَ، فَاقْتُلُوهُ؛ فَإِنَّ يَدَ اللهِ عَلَى الْجَمَاعَةِ، فَإِنِّ الشَّيْطَانَ مَعَ مَنْ فَارَقَ الْجَمَاعَةَ يَرْكُضُ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1852) من طريق غندر، حدثنا شعبة، عن زياد بن علاقة قال: سمعت عرفجة قال فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل من خرج على الإمام وجماعة المسلمين","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1852). The second wording was narrated by al-Nasā’ī (4020) and authenticated by Ibn Ḥibbān (4577).","chapter_en":"The Command to Kill Whoever Rebels Against the Leader and the Community of Muslims","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿArfajah reported: I heard the Messenger of Allah ﷺ say: “There will be disturbances and troubles. Whoever seeks to divide the affairs of this Ummah while it is united, then strike him with the sword, whoever he may be.” In another wording: I saw the Prophet ﷺ while he was on the pulpit addressing the people, and he said: “After me there will be disturbances and troubles. Whoever you see separating from the community, or seeking to divide the affairs of the Ummah of Muḥammad ﷺ, whoever he may be, then kill him. For the Hand of Allah is over the community, and Satan runs alongside the one who separates from the community.”"]},"buhuth":{"en":["The expression “hanāt and hanāt” uses the plural of hanah, a word that may refer generally to matters or occurrences; here it means trials, disturbances, and newly arising events."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1852)، واللفظ الثاني رواه النسائي (4020)، وصححه ابن حبان (4577)."},{"num":7677,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ، قَالَ:  دَخَلْتُ الْمَسْجِدَ فَإِذَا عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ جَالِسٌ فِي ظِلِّ الْكَعْبَةِ، وَالنَّاسُ مُجْتَمِعُونَ عَلَيْهِ، فَأَتَيْتُهُمْ، فَجَلَسْتُ إِلَيْهِ فَقَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَنَزَلْنَا مَنْزِلًا، فَمِنَّا مَنْ يُصْلِحُ خِبَاءَهُ، وَمِنَّا مَنْ يَنْتَضِلُ، وَمِنَّا مَنْ هُوَ فِي جَشَرِهِ، إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الصَّلَاةَ جَامِعَةً، فَاجْتَمَعْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلَّا كَانَ حَقًّا عَلَيْهِ أَنْ يَدُلَّ أُمَّتَهُ عَلَى خَيْرِ مَا يَعْلَمُهُ لَهُمْ، وَيُنْذِرَهُمْ شَرَّ مَا يَعْلَمُهُ لَهُمْ، وَإِنَّ أُمَّتَكُمْ هَذِهِ جُعِلَ عَافِيَتُهَا فِي أَوَّلِهَا، وَسَيُصِيبُ آخِرَهَا بَلَاءٌ، وَأُمُورٌ تُنْكِرُونَهَا، وَتَجِيءُ فِتْنَةٌ، فَيُرَقِّقُ بَعْضُهَا بَعْضًا، وَتَجِيءُ الْفِتْنَةُ، فَيَقُولُ الْمُؤْمِنُ: هَذِهِ مُهْلِكَتِي، ثُمَّ تَنْكَشِفُ، وَتَجِيءُ الْفِتْنَةُ، فَيَقُولُ الْمُؤْمِنُ: هَذِهِ هَذِهِ، فَمَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنِ النَّارِ، وَيُدْخَلَ الْجَنَّةَ، فَلْتَأْتِهِ مَنِيَّتُهُ، وَهُوَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ، وَلْيَأْتِ إِلَى النَّاسِ الَّذِي يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ، وَمَنْ بَايَعَ إِمَامًا، فَأَعْطَاهُ صَفْقَةَ يَدِهِ، وَثَمَرَةَ قَلْبِهِ، فَلْيُطِعْهُ إِنِ اسْتَطَاعَ، فَإِنْ جَاءَ آخَرُ يُنَازِعُهُ فَاضْرِبُوا عُنُقَ الْآخَرِ. فَدَنَوْتُ مِنْهُ فَقُلْتُ لَهُ: أَنْشُدُكَ اللَّهَ، آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَأَهْوَى إِلَى أُذُنَيْهِ وَقَلْبِهِ بِيَدَيْهِ وَقَالَ: سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي، فَقُلْتُ لَهُ: هَذَا ابْنُ عَمِّكَ مُعَاوِيَةُ، يَأْمُرُنَا أَنْ نَأْكُلَ أَمْوَالَنَا بَيْنَنَا بِالْبَاطِلِ وَنَقْتُلَ أَنْفُسَنَا، وَاللهُ يَقُولُ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ وَلا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا﴾. قَالَ: فَسَكَتَ سَاعَةً ثُمَّ قَالَ: أَطِعْهُ فِي طَاعَةِ اللهِ، وَاعْصِهِ فِي مَعْصِيَةِ اللهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1844: 46) من طريق جرير، عن الأعمش، عن زيد بن وهب، عن عبد الرحمن بن عبد رب الكعبة قال: فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل من خرج على الإمام وجماعة المسلمين","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1844:46).","chapter_en":"The Command to Kill Whoever Rebels Against the Leader and the Community of Muslims","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿAbd al-Rahman ibn ʿAbd Rabb al-Kaʿbah said: I entered the mosque and saw ʿAbdullah ibn ʿAmr ibn al-ʿAs sitting in the shade of the Kaʿbah, with people gathered around him. I came to them and sat with him, and he said: We were with the Messenger of Allah ﷺ on a journey, and we stopped at a place. Some of us were repairing their tents, some were practicing archery, and some were with their grazing animals, when the caller of the Messenger of Allah ﷺ called out: “The prayer is gathering.” So we gathered to the Messenger of Allah ﷺ, and he said: “There was no prophet before me except that it was a duty upon him to guide his nation to the best of what he knew for them, and to warn them of the worst of what he knew for them. The well-being of this nation of yours has been placed in its beginning, and its end will be struck by affliction and matters you will reject. A trial will come, and each one will make the one before it seem small. A trial will come and the believer will say: ‘This is my destruction,’ then it will be removed. Another trial will come and the believer will say: ‘This, this.’ So whoever loves to be moved away from the Fire and admitted into Paradise, let his death come to him while he believes in Allah and the Last Day, and let him treat people as he would love to be treated. Whoever pledges allegiance to a leader, giving him the clasp of his hand and the fruit of his heart, let him obey him if he is able. If another comes to dispute with him, strike the neck of the latter.” I came close to him and said: “I ask you by Allah, did you hear this from the Messenger of Allah ﷺ?” He pointed with his hands to his ears and his heart and said: “My ears heard it and my heart retained it.” I said to him: “This cousin of yours, Muʿawiyah, commands us to consume our wealth among ourselves falsely and to kill ourselves, while Allah says: ‘O you who believe, do not consume your wealth among yourselves falsely, except that it be trade by mutual consent among you, and do not kill yourselves. Indeed, Allah is Merciful to you.’” [Women: 29] He remained silent for a while, then said: “Obey him in obedience to Allah, and disobey him in disobedience to Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1844:46)."},{"num":7678,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا بُويِعَ لِخَلِيفَتَيْنِ فَاقْتُلُوا الآخَرَ مِنْهُمَا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1853) عن وهب بن بقية الواسطي حدثنا خالد بن عبد الله عن الجريري، عن أبي نضرة، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل من خرج على الإمام وجماعة المسلمين","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1853).","chapter_en":"The Command to Kill Whoever Rebels Against the Leader and the Community of Muslims","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “If allegiance is pledged to two caliphs, then kill the latter of them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1853)."},{"num":7679,"demo":false,"sanad":"","matn":["قَالَ: عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا فَوَاللَّهِ، لأَنْ أَخِرَّ مِنَ السَّمَاءِ أَحَبُّ إِلَىَّ مِنْ أَنْ أَكْذِبَ عَلَيْهِ، وَإِذَا حَدَّثْتُكُمْ فِيمَا بَيْنِي وَبَيْنَكُمْ فَإِنَّ الْحَرْبَ خَدْعَةٌ، وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: سَيَخْرُجُ قَوْمٌ فِي آخِرِ الزَّمَانِ، حُدَّاثُ الأَسْنَانِ، سُفَهَاءُ الأَحْلاَمِ، يَقُولُونَ مِنْ خَيْرِ قَوْلِ الْبَرِيَّةِ، لاَ يُجَاوِزُ إِيمَانُهُمْ حَنَاجِرَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، فَأَيْنَمَا لَقِيتُمُوهُمْ فَاقْتُلُوهُمْ، فَإِنَّ فِي قَتْلِهِمْ أَجْرًا لِمَنْ قَتَلَهُمْ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدين (6930)، ومسلم في الزكاة (1066: 154) كلاهما من طريق الأعمش، حدثنا خيثمة، حدثنا سويد بن غفلة، قال علي فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6930) and Muslim (1066:154).","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: When I narrate a hadith to you from the Messenger of Allah ﷺ, then by Allah, falling from the sky is dearer to me than lying about him. But when I speak to you concerning matters between me and you, then war is strategy. I heard the Messenger of Allah ﷺ say: “A people will emerge at the end of time, young in age and foolish in understanding. They will speak with the best speech of creation, but their faith will not pass beyond their throats. They will pass out of the religion as an arrow passes through the prey. Wherever you meet them, kill them, for in killing them there is reward on the Day of Resurrection for whoever kills them.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6930)، ومسلم (1066:154)."},{"num":7680,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: بَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ جَاءَ عَبْدُ اللَّهِ بْنُ ذِي الْخُوَيْصِرَةِ التَّمِيمِيُّ فَقَالَ: اعْدِلْ يَا رَسُولَ اللَّهِ. فَقَالَ: وَيْلَكَ مَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ. قَالَ عُمَرُ بْنُ الْخَطَّابِ: دَعْنِي أَضْرِبْ عُنُقَهُ. قَالَ: دَعْهُ فَإِنَّ لَهُ أَصْحَابًا يَحْقِرُ أَحَدُكُمْ صَلاَتَهُ مَعَ صَلاَتِهِ، وَصِيَامَهُ مَعَ صِيَامِهِ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، يُنْظَرُ فِي قُذَذِهِ، فَلاَ يُوجَدُ فِيهِ شَىْءٌ، يُنْظَرُ فِي نَصْلِهِ، فَلاَ يُوجَدُ فِيهِ شَىْءٌ، ثُمَّ يُنْظَرُ فِي رِصَافِهِ فَلاَ يُوجَدُ فِيهِ شَىْءٌ، ثُمَّ يُنْظَرُ فِي نَضِيِّهِ، فَلاَ يُوجَدُ فِيهِ شَىْءٌ، قَدْ سَبَقَ الْفَرْثَ وَالدَّمَ، آيَتُهُمْ رَجُلٌ إِحْدَى يَدَيْهِ ـ أَوْ قَالَ: ثَدْيَيْهِ ـ مِثْلُ ثَدْىِ الْمَرْأَةِ ـ أَوْ قَالَ: مِثْلُ الْبَضْعَةِ ـ تَدَرْدَرُ، يَخْرُجُونَ عَلَى حِينِ فُرْقَةٍ مِنَ النَّاسِ.","قَالَ أَبُو سَعِيدٍ: أَشْهَدُ سَمِعْتُ مِنَ النَّبِيِّ صلى الله عليه وسلم وَأَشْهَدُ أَنَّ عَلِيًّا قَتَلَهُمْ وَأَنَا مَعَهُ جِيءَ بِالرَّجُلِ عَلَى النَّعْتِ الَّذِي نَعَتَهُ النَّبِيُّ صلى الله عليه وسلم قَالَ فَنَزَلَتْ فِيهِ: ﴿وَمِنْهُمْ مَنْ يَلْمِزُكَ فِي الصَّدَقَاتِ﴾ [التوبة: 58]."],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدين (6933)، ومسلم في الزكاة (1064: 148) كلاهما من حديث الزهري، عن أبي سلمة، عن أبي سعيد فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6933) and Muslim (1064:148). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: While the Prophet ﷺ was distributing, ʿAbdullah ibn Dhi al-Khuwaysirah al-Tamimi came and said: “Be just, Messenger of Allah.” He said: “Woe to you! Who will be just if I am not just?” ʿUmar ibn al-Khattab said: “Let me strike his neck.” He said: “Leave him, for he will have companions. One of you would consider his prayer insignificant compared to their prayer, and his fasting compared to their fasting. They will pass out of the religion as an arrow passes through the prey. One looks at its feathers and finds nothing on them, then looks at its iron head and finds nothing on it, then looks at its binding and finds nothing on it, then looks at its shaft and finds nothing on it; it has passed through dung and blood. Their sign is a man whose one hand — or he said: one breast — is like a woman’s breast, or like a piece of flesh, moving loosely. They will emerge at a time of division among the people.” Abu Saʿid said: I testify that I heard this from the Prophet ﷺ, and I testify that ʿAli killed them while I was with him, and the man was brought according to the description that the Prophet ﷺ had given. He said: Then this was revealed about him: “And among them are those who criticize you concerning the charities.” [Repentance: 58]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6933)، ومسلم (1064:148)، واللفظ للبخاري."},{"num":7681,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذُهَيْبَةٍ، فَقَسَمَهَا بَيْنَ الأَرْبَعَةِ الأَقْرَعِ بْنِ حَابِسٍ الْحَنْظَلِيِّ ثُمَّ الْمُجَاشِعِيِّ، وَعُيَيْنَةَ بْنِ بَدْرٍ الْفَزَارِيِّ، وَزَيْدٍ الطَّائِيِّ ثُمَّ أَحَدِ بَنِي نَبْهَانَ، وَعَلْقَمَةَ بْنِ عُلاَثَةَ الْعَامِرِيِّ ثُمَّ أَحَدِ بَنِي كِلاَبٍ، فَغَضِبَتْ قُرَيْشٌ وَالأَنْصَارُ، قَالُوا: يُعْطِي صَنَادِيدَ أَهْلِ نَجْدٍ، وَيَدَعُنَا. قَالَ: إِنَّمَا أَتَأَلَّفُهُمْ. فَأَقْبَلَ رَجُلٌ غَائِرُ الْعَيْنَيْنِ، مُشْرِفُ الْوَجْنَتَيْنِ، نَاتِئُ الْجَبِينِ، كَثُّ اللِّحْيَةِ، مَحْلُوقٌ فَقَالَ: اتَّقِ اللَّهَ يَا مُحَمَّدُ. فَقَالَ: مَنْ يُطِعِ اللَّهَ إِذَا عَصَيْتُ، أَيَأْمَنُنِي اللَّهُ عَلَى أَهْلِ الأَرْضِ فَلاَ تَأْمَنُونِي. فَسَأَلَهُ رَجُلٌ قَتْلَهُ ـ أَحْسِبُهُ خَالِدَ بْنَ الْوَلِيدِ، ـ فَمَنَعَهُ، فَلَمَّا وَلَّى قَالَ: إِنَّ مِنْ ضِئْضِئِ هَذَا ـ أَوْ فِي عَقِبِ هَذَا ـ قَوْمٌ يَقْرَءُونَ الْقُرْآنَ، لاَ يُجَاوِزُ حَنَاجِرَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ مُرُوقَ السَّهْمِ مِنَ الرَّمِيَّةِ، يَقْتُلُونَ أَهْلَ الإِسْلاَمِ، وَيَدَعُونَ أَهْلَ الأَوْثَانِ، لَئِنْ أَنَا أَدْرَكْتُهُمْ لأَقْتُلَنَّهُمْ قَتْلَ عَادٍ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3344)، ومسلم في الزكاة (1064: 143) كلاهما من طريق سعيد بن مسروق، عن عبد الرحمن بن أبي نعم، عن أبي سعيد الخدري قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3344) and Muslim (1064:143).","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: ʿAli sent a small piece of gold to the Prophet ﷺ, so he distributed it among four people: al-Aqraʿ ibn Habis al-Hanzali, then al-Mujashiʿi; ʿUyaynah ibn Badr al-Fazari; Zayd al-Ta’i, then one of Banu Nabhan; and ʿAlqamah ibn ʿUlathah al-ʿAmiri, then one of Banu Kilab. Quraysh and the Ansar became angry and said: “He gives to the chiefs of the people of Najd and leaves us!” He said: “I am only reconciling their hearts.” Then a man came forward with sunken eyes, prominent cheeks, a protruding forehead, a thick beard, and a shaved head. He said: “Fear Allah, Muhammad!” He said: “Who would obey Allah if I disobeyed Him? Allah has entrusted me over the people of the earth, yet you do not trust me?” A man asked permission to kill him — I think it was Khalid ibn al-Walid — but he prevented him. When the man turned away, he said: “From the offspring of this man, or from those who come after him, will be a people who recite the Qur’an but it will not pass beyond their throats. They will pass out of the religion as an arrow passes through the prey. They will kill the people of Islam and leave the people of idols. If I reach them, I will surely kill them with the killing of ʿAd.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3344)، ومسلم (1064:143)."},{"num":7682,"demo":false,"sanad":"","matn":["عن زَيْدِ بن وَهْبٍ الجهني: أَنَّهُ كَانَ فِي الْجَيْشِ الَّذِينَ كَانُوا مَعَ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ الَّذِينَ سَارُوا إِلَى الْخَوَارِجِ، فَقَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ: أَيُّهَا النَّاسُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَخْرُجُ قَوْمٌ مِنْ أُمَّتِي يَقْرَءُونَ الْقُرْآنَ، لَيْسَ قِرَاءَتُكُمْ إِلَى قِرَاءَتِهِمْ بِشَيْءٍ، وَلَا صَلَاتُكُمْ إِلَى صَلَاتِهِمْ بِشَيْءٍ، وَلَا صِيَامُكُمْ إِلَى صِيَامِهِمْ بِشَيْءٍ، يَقْرَءُونَ الْقُرْآنَ يَحْسِبُونَ أَنَّهُ لَهُمْ وَهُوَ عَلَيْهِمْ، لَا تُجَاوِزُ صَلَاتُهُمْ تَرَاقِيَهُمْ، يَمْرُقُونَ مِنَ الْإِسْلَامِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، لَوْ يَعْلَمُ الْجَيْشُ الَّذِينَ يُصِيبُونَهُمْ مَا قُضِيَ لَهُمْ عَلَى لِسَانِ نَبِيِّهِمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَاتَّكَلُوا عَنِ الْعَمَلِ، وَآيَةُ ذَلِكَ أَنَّ فِيهِمْ رَجُلًا لَهُ عَضُدٌ وَلَيْسَ لَهُ ذِرَاعٌ، عَلَى رَأْسِ عَضُدِهِ مِثْلُ حَلَمَةِ الثَّدْيِ عَلَيْهِ شَعَرَاتٌ بِيضٌ فَتَذْهَبُونَ إِلَى مُعَاوِيَةَ وَأَهْلِ الشَّامِ وَتَتْرُكُونَ هَؤُلَاءِ يَخْلُفُونَكُمْ فِي ذَرَارِيِّكُمْ، وَأَمْوَالِكُمْ، وَاللهِ إِنِّي لَأَرْجُو أَنْ يَكُونُوا هَؤُلَاءِ الْقَوْمَ، فَإِنَّهُمْ قَدْ سَفَكُوا الدَّمَ الْحَرَامَ وَأَغَارُوا فِي سَرْحِ النَّاسِ، فَسِيرُوا عَلَى اسْمِ اللَّهِ.","قَالَ سَلَمَةُ بْنُ كُهَيْلٍ: فَنَزَّلَنِي زَيْدُ بْنُ وَهْبٍ مَنْزِلًا حَتَّى قَالَ: مَرَرْنَا عَلَى قَنْطَرَةٍ فَلَمَّا الْتَقَيْنَا، وَعَلَى الْخَوَارِجِ يَوْمَئِذٍ عَبْدُ اللهِ بْنُ وَهْبٍ الرَّاسِبِيُّ فَقَالَ لَهُمْ: أَلْقُوا الرِّمَاحَ، وَسُلُّوا سُيُوفَكُمْ مِنْ جُفُونِهَا، فَإِنِّي أَخَافُ أَنْ يُنَاشِدُوكُمْ كَمَا نَاشَدُوكُمْ يَوْمَ حَرُورَاءَ فَرَجَعُوا، فَوَحَّشُوا بِرِمَاحِهِمْ وَسَلُّوا السُّيُوفَ، وَشَجَرَهُمُ النَّاسُ بِرِمَاحِهِمْ قَالَ: وَقُتِلَ بَعْضُهُمْ عَلَى بَعْضٍ، وَمَا أُصِيبَ مِنَ النَّاسِ يَوْمَئِذٍ إِلَّا رَجُلَانِ فَقَالَ عليرضي الله عنه: الْتَمِسُوا فِيهِمُ الْمُخْدَجَ فَالْتَمَسُوهُ، فَلَمْ يَجِدُوهُ فَقَامَ عَلِيٌّ رضي الله عنه بِنَفْسِهِ حَتَّى أَتَى نَاسًا قَدْ قُتِلَ بَعْضُهُمْ عَلَى بَعْضٍ قَالَ: أَخِّرُوهُمْ، فَوَجَدُوهُ مِمَّا يَلِي الْأَرْضَ فَكَبَّرَ ثُمَّ قَالَ: صَدَقَ اللهُ وَبَلَّغَ رَسُولُهُ قَالَ: فَقَامَ إِلَيْهِ عَبِيدَةُ السَّلْمَانِيُّ فَقَالَ: يَا أَمِيرَ الْمُؤْمِنِينَ! اللهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ لَسَمِعْتَ هَذَا الْحَدِيثَ مِنْ رَسُولِ اللهِ صلى الله عليه وسلم؟ فَقَالَ: إِي وَاللهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ حَتَّى اسْتَحْلَفَهُ ثَلَاثًا وَهُوَ يَحْلِفُ لَهُ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1066: 156) عن عبد بن حميد، حدثنا عبد الرزاق بن همام، حدثنا عبد الملك بن أبي سليمان، حدثنا سلمة بن كهيل، حدثني زيد بن وهب قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1066:156).","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Zayd ibn Wahb al-Juhani was in the army that was with ʿAli, may Allah be pleased with him, which marched against the Kharijites. ʿAli, may Allah be pleased with him, said: “People, I heard the Messenger of Allah ﷺ say: ‘A people will emerge from my nation who recite the Qur’an. Your recitation will be nothing compared to their recitation, your prayer will be nothing compared to their prayer, and your fasting will be nothing compared to their fasting. They recite the Qur’an thinking it is for them, while it is against them. Their prayer will not pass beyond their collarbones. They will pass out of Islam as an arrow passes through the prey.’ If the army who strikes them knew what had been decreed for them upon the tongue of their Prophet ﷺ, they would rely upon that and abandon work. The sign of that is that among them is a man who has an upper arm but no forearm; at the end of his upper arm is something like the nipple of a breast, with white hairs upon it. Will you go to Muʿawiyah and the people of Syria and leave these people behind you among your children and wealth? By Allah, I hope that these are those people, for they have shed inviolable blood and raided the people’s grazing animals. So march in the name of Allah.” Salamah ibn Kuhayl said: Zayd ibn Wahb described the places to me until he said: We passed over a bridge. When we met, the Kharijites that day were led by ʿAbdullah ibn Wahb al-Rasibi. He said to them: “Throw down the spears and draw your swords from their sheaths, for I fear that they will appeal to you as they appealed to you on the day of Harura’.” So they returned, cast aside their spears, and drew their swords. The people thrust at them with spears. He said: They were killed one upon another, and only two of the people were injured that day. ʿAli, may Allah be pleased with him, said: “Search among them for the defective one.” They searched but did not find him. Then ʿAli himself stood up and came to people who had been killed piled upon one another. He said: “Move them back.” They found him beneath them, so he proclaimed greatness and said: “Allah spoke the truth, and His Messenger conveyed.” Then ʿUbaydah al-Salmani stood and said: “Commander of the believers, by Allah, besides whom there is no deity, did you truly hear this hadith from the Messenger of Allah ﷺ?” He said: “Yes, by Allah, besides whom there is no deity.” He made him swear three times, and he swore to him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1066:156)."},{"num":7683,"demo":false,"sanad":"","matn":["عن محمد بن جُبَيْرٍ بْنِ مُطْعِمٍ يُحَدِّثُ: أَنَّهُ بَلَغَ مُعَاوِيَةَ وَهْوَ عِنْدَهُ فِي وَفْدٍ مِنْ قُرَيْشٍ أَنَّ عَبْدَ اللَّهِ بْنَ عَمْرٍو يُحَدِّثُ أَنَّهُ سَيَكُونُ مَلِكٌ مِنْ قَحْطَانَ، فَغَضِبَ، فَقَامَ فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ: أَمَّا بَعْدُ فَإِنَّهُ بَلَغَنِي أَنَّ رِجَالاً مِنْكُمْ يُحَدِّثُونَ أَحَادِيثَ لَيْسَتْ فِي كِتَابِ اللَّهِ، وَلاَ تُؤْثَرُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأُولَئِكَ جُهَّالُكُمْ، فَإِيَّاكُمْ وَالأَمَانِيَّ الَّتِي تُضِلُّ أَهْلَهَا، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ هَذَا الأَمْرَ فِي قُرَيْشٍ، لاَ يُعَادِيهِمْ أَحَدٌ إِلاَّ كَبَّهُ اللَّهُ عَلَى وَجْهِهِ مَا أَقَامُوا الدِّينَ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7139) عن أبي اليمان، أخبرنا شعيب، عن الزهري، قال: كان محمد بن جبير بن مطعم يحدث فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7139).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Muhammad ibn Jubayr ibn Mutʿim narrated that it reached Muʿawiyah, while he was with him in a delegation from Quraysh, that ʿAbdullah ibn ʿAmr was narrating that there would be a king from Qahtan. So he became angry, stood up, praised Allah as He deserves, then said: “As for what follows: It has reached me that some men among you narrate reports that are not in the Book of Allah and are not transmitted from the Messenger of Allah ﷺ. Those are your ignorant ones. Beware of hopes that mislead their people, for I heard the Messenger of Allah ﷺ say: ‘This affair is among Quraysh. No one opposes them except that Allah will throw him into the Fire upon his face, so long as they establish the religion.’”"]},"buhuth":{"en":["There is no disagreement among the scholars of the people of the Prophetic way and the Muslim community that the supreme leader — meaning the ruler over all Islamic lands — is required to be from Quraysh. However, the legal texts indicate that this required preference for them in leadership is conditional upon their establishing the religion and obeying Allah and His Messenger. If they oppose the command of Allah, then giving precedence to others who obey Allah the Exalted, implement His commands, and establish His prescribed limits is more appropriate.","The proof for this is his statement ﷺ: “so long as they establish the religion,” because the expression “so long as” is a time-related qualifier attached to his statement: “This affair is among Quraysh.” The meaning is: this affair remains in Quraysh for the duration that they establish the religion. Its implication is that if they do not establish the religion, then it is not for them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7139)."},{"num":7684,"demo":false,"sanad":"","matn":["عن مُعَاوِيَةَ قَالَ: قَالَ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: النَّاسُ تَبَعٌ لِقُرَيْشٍ فِي هَذَا الْأَمْرِ، خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا، وَاللهِ لَوْلَا أَنْ تَبْطَرَ قُرَيْشٌ لَأَخْبَرْتُهَا مَا لِخِيَارِهَا عِنْدَ اللَّهِ عَزَّ."],"takhrij":"صحيح: رواه أحمد (16927)، وابن أبي شيبة (33054) كلاهما عن أبي نعيم الفضل بن دكين، حدثنا عبد الله بن مبشر مولى أم حبيبة، عن زيد بن أبي عتاب، عن معاوية فذكره. وعند ابن أبي شيبة: قام معاوية على المنبر فقال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (16927) and Ibn Abi Shaybah (33054).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Muʿawiyah said: The Messenger of Allah ﷺ said: “People follow Quraysh in this affair. The best of them in the age of ignorance are the best of them in Islam when they gain understanding. By Allah, were it not that Quraysh might become arrogant, I would have informed them of what their best have with Allah, Mighty and Majestic.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (16927)، وابن أبي شيبة (33054)."},{"num":7685,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: النَّاسُ تَبَعٌ لِقُرَيْشٍ فِي هَذَا الشَّأْنِ، مُسْلِمُهُمْ تَبَعٌ لِمُسْلِمِهِمْ، وَكَافِرُهُمْ تَبَعٌ لِكَافِرِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3495)، ومسلم في الإمارة (1818) كلاهما من طريق قتيبة بن سعيد، حدثنا المغيرة الحزامي، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3495) and Muslim (1818).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “People follow Quraysh in this matter; their Muslims follow their Muslims, and their disbelievers follow their disbelievers.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3495)، ومسلم (1818)."},{"num":7686,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لِي عَلَى قُرَيْشٍ حَقًّا، وَإِنَّ لِقُرَيْشٍ عَلَيْكُمْ حَقًّا مَا حَكَمُوا وَعَدَلُوا، وَائْتُمِنُوا فَأَدُّوا، وَاسْتُرْحِمُوا فَرَحِمُوا، فَمَنْ لَمْ يَفْعَلْ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ."],"takhrij":"صحيح: رواه أحمد (7653) عن عبد الرزاق – وهو في مصنفه (19902) واللفظ له-، وصحّحه ابن حبان (4581) عن معمر، عن ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة فذكره. ولم يذكر أحمد قوله: \"فمن لم يفعل ذلك فعليه لعنة الله\".","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (7653) from ʿAbd al-Razzaq — and it is in his Musannaf (19902), with this wording — and graded authentic by Ibn Hibban (4581).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I have a right over Quraysh, and Quraysh has a right over you, so long as when they rule, they act justly; when they are entrusted, they fulfill the trust; and when mercy is sought from them, they show mercy. Whoever does not do that, upon him is the curse of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (7653) عن عبد الرزاق — وهو في مصنفه (19902)، واللفظ له — وصححه ابن حبان (4581)."},{"num":7687,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَزَالُ الأَمْرُ فِي قُرَيْشٍ مَا بَقِيَ مِنْهُمُ اثْنَانِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7140)، ومسلم في الإمارة (1820) كلاهما عن أحمد بن عبد الله بن يونس حدثنا عاصم بن محمد بن زيد، سمعت أبي يقول: قال ابن عمر: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7140) and Muslim (1820).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “This affair will remain among Quraysh as long as two of them remain.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7140)، ومسلم (1820)."},{"num":7688,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عبدالله قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : النَّاسُ تَبَعٌ لِقُرَيْشٍ فِي الْخَيْرِ وَالشَّرِّ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1819) عن يحيى بن حبيب الحارثي، حدثنا روح، حدثنا ابن جريج، حدثني أبو الزبير، عن جابر قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1819).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Prophet ﷺ said: “People follow Quraysh in good and in evil.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1819)."},{"num":7689,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  لَا يَزَالُ أَمْرُ النَّاسِ مَاضِيًا مَا وَلِيَهُمُ اثْنَا عَشَرَ رَجُلًا، ثُمَّ تَكَلَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَلِمَةٍ خَفِيَتْ عَلَيَّ، فَسَأَلْتُ أَبِي: مَاذَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: كُلُّهُمْ مِنْ قُرَيْشٍ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (722، 7223)، ومسلم في الإمارة (1821: 6) كلاهما من حديث عبد الملك بن عمير، عن جابر بن سمرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7222, 7223) and Muslim (1821:6). The wording is from Muslim. Muslim also narrated it through another route with the wording: “This religion will remain mighty and protected until there have been twelve caliphs.”","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn Samurah said: I heard the Prophet ﷺ say: “The affair of the people will continue to proceed as long as twelve men rule them.” Then the Prophet ﷺ said a word that was unclear to me, so I asked my father: “What did the Messenger of Allah ﷺ say?” He said: “All of them are from Quraysh.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7222، 7223)، ومسلم (1821:6)، والسياق لمسلم."},{"num":7690,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ:  كَتَبْتُ إِلَى جَابِرِ بْنِ سَمُرَةَ مَعَ غُلَامِي نَافِعٍ: أَنْ أَخْبِرْنِي بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَكَتَبَ إِلَيَّ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ جُمُعَةٍ عَشِيَّةَ رُجِمَ الْأَسْلَمِيُّ يَقُولُ: لَا يَزَالُ الدِّينُ قَائِمًا حَتَّى تَقُومَ السَّاعَةُ، أَوْ يَكُونَ عَلَيْكُمُ اثْنَا عَشَرَ خَلِيفَةً، كُلُّهُمْ مِنْ قُرَيْشٍ. وَسَمِعْتُهُ يَقُولُ: عُصَيْبَةٌ مِنَ الْمُسْلِمِينَ يَفْتَتِحُونَ الْبَيْتَ الْأَبْيَضَ، بَيْتَ كِسْرَى أَوْ آلِ كِسْرَى. وَسَمِعْتُهُ يَقُولُ: إِنَّ بَيْنَ يَدَيِ السَّاعَةِ كَذَّابِينَ فَاحْذَرُوهُمْ. وَسَمِعْتُهُ يَقُولُ: إِذَا أَعْطَى اللهُ أَحَدَكُمْ خَيْرًا، فَلْيَبْدَأْ بِنَفْسِهِ وَأَهْلِ بَيْتِهِ. وَسَمِعْتُهُ يَقُولُ: أَنَا الْفَرَطُ عَلَى الْحَوْضِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1822: 10) من طريق حاتم بن إسماعيل عن المهاجر بن مسمار، عن عامر بن سعد بن أبي وقاص قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1822:10).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["ʿAmir ibn Saʿd ibn Abi Waqqas said: I wrote to Jabir ibn Samurah through my servant Nafiʿ, saying: “Inform me of something you heard from the Messenger of Allah ﷺ.” He wrote back to me: “I heard the Messenger of Allah ﷺ on a Friday, on the evening when the Aslami man was stoned, saying: ‘The religion will remain established until the Hour comes, or until there have been over you twelve caliphs, all of them from Quraysh.’ I also heard him say: ‘A small group of Muslims will conquer the White House, the house of Chosroes or the family of Chosroes.’ I heard him say: ‘Before the Hour there will be liars, so beware of them.’ I heard him say: ‘When Allah gives one of you good, let him begin with himself and his household.’ And I heard him say: ‘I will be the one who reaches the Basin before you.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1822:10)."},{"num":7691,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ: كُنَّا قُعُودًا فِي الْمَسْجِدِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ بَشِيرٌ رَجُلًا يَكُفُّ حَدِيثَهُ، فَجَاءَ أَبُو ثَعْلَبَةَ الْخُشَنِيُّ، فَقَالَ: يَا بَشِيرُ بْنَ سَعْدٍ أَتَحْفَظُ حَدِيثَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي الْأُمَرَاءِ؟ فَقَالَ حُذَيْفَةُ: أَنَا أَحْفَظُ خُطْبَتَهُ، فَجَلَسَ أَبُو ثَعْلَبَةَ، فَقَالَ حُذَيْفَةُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَكُونُ النُّبُوَّةُ فِيكُمْ مَا شَاءَ اللَّهُ أَنْ تَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ خِلَافَةٌ عَلَى مِنْهَاجِ النُّبُوَّةِ، فَتَكُونُ مَا شَاءَ اللَّهُ أَنْ تَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ اللَّهُ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ مُلْكًا عَاضًّا، فَيَكُونُ مَا شَاءَ اللَّهُ أَنْ يَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ مُلْكًا جَبْرِيَّةً، فَتَكُونُ مَا شَاءَ اللَّهُ أَنْ تَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ خِلَافَةً عَلَى مِنْهَاجِ نُبُوَّةٍ ثُمَّ سَكَتَ.","قال حبيب: فلما قام عمر بن عبد العزيز، وكان يزيد بن النعمان ابن بشير في صحابته، فكتبت إليه بهذا الحديث أذكره إياه، فقلت له: إني أرجو أن يكون أمير المؤمنين -يعني: عمر- بعد الملك العاض والجبرية فأدخل كتابي على عمر بن عبد العزيز، فسر به، وأعجبه."],"takhrij":"حسن: رواه أحمد (18406) عن سليمان بن داود الطيالسي حدثني داود بن إبراهيم الواسطي، حدثني حبيب بن سالم، عن النعمان بن بشير فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (18406).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Al-Nuʿman ibn Bashir said: We were sitting in the mosque with the Messenger of Allah ﷺ, and Bashir was a man who spoke little. Abu Thaʿlabah al-Khushani came and said: “Bashir ibn Saʿd, do you remember the hadith of the Messenger of Allah ﷺ concerning rulers?” Hudhayfah said: “I remember his sermon.” So Abu Thaʿlabah sat down, and Hudhayfah said: The Messenger of Allah ﷺ said: “Prophethood will remain among you for as long as Allah wills it to remain, then He will raise it when He wills to raise it. Then there will be caliphate upon the method of prophethood, and it will remain for as long as Allah wills it to remain, then He will raise it when Allah wills to raise it. Then there will be biting kingship, and it will remain for as long as Allah wills it to remain, then He will raise it when He wills to raise it. Then there will be coercive kingship, and it will remain for as long as Allah wills it to remain, then He will raise it when He wills to raise it. Then there will be caliphate upon the method of prophethood.” Then he became silent. Habib said: When ʿUmar ibn ʿAbd al-ʿAziz became ruler, and Yazid ibn al-Nuʿman ibn Bashir was among his companions, I wrote this hadith to him to remind him of it. I said to him: “I hope that the Commander of the Believers — meaning ʿUmar — is after the biting and coercive kingship.” My letter was brought to ʿUmar ibn ʿAbd al-ʿAziz, and he was pleased with it and admired it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (18406)."},{"num":7692,"demo":false,"sanad":"","matn":["عن أَبِي بَرْزَةَ يرفعه إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْأَئِمَّةُ مِنْ قُرَيْشٍ: إِذَا اسْتُرْحِمُوا رَحِمُوا، وَإِذَا عَاهَدُوا وَفَوْا، وَإِذَا حَكَمُوا عَدَلُوا، فَمَنْ لَمْ يَفْعَلْ ذَلِكَ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ."],"takhrij":"حسن: رواه أحمد (19777) عن سليمان بن داود – هو الطيالسي-حدثنا سكين، حدثنا سيار بن سلامة سمع أبا برزة يرفعه إلى النبي صلى الله عليه وسلم قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (19777).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Barzah traced it back to the Prophet ﷺ, who said: “The leaders are from Quraysh. When mercy is sought from them, they show mercy; when they make a covenant, they fulfill it; and when they judge, they judge justly. Whoever among them does not do that, upon him is the curse of Allah, the angels, and all people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (19777)."},{"num":7693,"demo":false,"sanad":"","matn":["عن الْحَارِثِ بْنِ أَبِي الحارث، وَكَثِيرِ بْنِ مُرَّةَ، وَعَمْرِو بْنِ الْأَسْوَدِ، وَأَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُمْ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ خِيَارَ أَئِمَّةِ قُرَيْشٍ خِيَارُ أَئِمَّةِ النَّاسِ."],"takhrij":"حسن: رواه الطبراني في الكبير (7517)، والبخاري في التاريخ الكبير (2/262) كلاهما من حديث إسماعيل بن عياش، عن ضمضم بن زرعة، عن شريح بن عبيد، عن الحارث بن ألحارث، وكثير بن مرة، وعمرو بن الأسود وأبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (8/128) and al-Bukhari in al-Tarikh al-Kabir (2/262).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Al-Harith ibn Abi al-Harith, Kathir ibn Murrah, ʿAmr ibn al-Aswad, and Abu Umamah narrated from the Prophet ﷺ that he said: “The best leaders of Quraysh are the best leaders of the people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (7517)، والبخاري في التاريخ الكبير (2/262)."},{"num":7694,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ: بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْأُمَرَاءُ مِنْ قُرَيْشٍ مَا عَمِلُوا فِيكُمْ بِثَلَاثٍ: مَا رَحِمُوا إِذَا اسْتُرْحِمُوا، وَأَقْسَطُوا إِذَا قَسَمُوا، وَعَدَلُوا إِذَا حَكَمُوا."],"takhrij":"حسن: رواه الحاكم (8528) والبيهقي (16545) كلاهما من حديث الصعق بن حزن، ثنا علي بن الحكم البناني، عن أنس بن مالك رضي الله عنه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (8528) and al-Bayhaqi (8/144).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “The rulers are from Quraysh so long as they act among you according to three things: they show mercy when mercy is sought from them, they are fair when they distribute, and they are just when they judge.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (8528)، والبيهقي (16545)."},{"num":7695,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُمْهَانَ، عَنْ سَفِينَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خِلاَفَةُ النُّبُوَّةِ ثَلاَثُونَ سَنَةً، ثُمَّ يُؤْتِي اللَّهُ الْمُلْكَ - أَوْ مُلْكَهُ - مَنْ يَشَاءُ.","قَالَ سَعِيدٌ: قَالَ لِي سَفِينَةُ: أَمْسِكْ عَلَيْكَ أبو بَكْرٍ سَنَتَيْنِ، وَعُمَرَ عَشْرًا وَعُثْمَانَ اثْنَتَىْ عشر، وَعَلِيٌّ كَذَا.","قال سعيد: قلت لسفينة: إن هولاء يزعمون أن عليا لم يكن بخليفة قال: كذبت أستاه بني الزرقاء- يعني بني مروان. هذا لفظ أبي داود.","ولفظ أحمد: قَالَ رَسُولَ اللهِ صلى الله عليه وسلم: الْخِلَافَةُ ثَلَاثُونَ عَامًا، ثُمَّ يَكُونُ بَعْدَ ذَلِكَ الْمُلْكُ. قَالَ سَفِينَةُ: أَمْسِكْ خِلَافَةَ أَبِي بَكْرٍ سَنَتَيْنِ، وَخِلَافَةَ عُمَرَ عَشْرَ سِنِينَ، وَخِلَافَةَ عُثْمَانَ اثْنَتَيْ عَشْرَةَ سَنَةً، وَخِلَافَةَ عَلِيٍّ سِتَّ سِنِينَ."],"takhrij":"حسن: رواه أبو داود (4646، 4647)، والترمذي (2226)، وأحمد (21919، 21923، 21928)، وصحّحه ابن حبان (6943)، والحاكم (3/71، 145) كلهم من طرق عن سعيد بن جمهان،ـ عن سفينة فذكره. ومنهم من ذكر المرفوع فقط.","grade":"حسن","chapter_ar":"باب خلافة النبوة ثلاثون سنة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4646, 4647), al-Tirmidhi (2226), who graded it good, Ahmad (21919, 21923, 21928), Ibn Hibban (6943), who authenticated it, and al-Hakim (3/71, 145).","chapter_en":"The Prophetic Caliphate Is Thirty Years","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["Saʿid ibn Jumhan narrated from Safinah that the Messenger of Allah ﷺ said: “The Prophetic caliphate will last thirty years, then Allah will give kingship — or His kingship — to whom He wills.” Saʿid said: Safinah said to me: “Count Abu Bakr as two years, ʿUmar as ten, ʿUthman as twelve, and ʿAli as such-and-such.” Saʿid said: I said to Safinah: “These people claim that ʿAli was not a caliph.” He said: “The backsides of the sons of al-Zarqa’ have lied,” meaning the sons of Marwan. This is the wording of Abu Dawud.","The wording of Ahmad is: The Messenger of Allah ﷺ said: “The caliphate will be thirty years, then after that there will be kingship.” Safinah said: “Count the caliphate of Abu Bakr as two years, the caliphate of ʿUmar as ten years, the caliphate of ʿUthman as twelve years, and the caliphate of ʿAli as six years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4646، 4647)، والترمذي (2226) وحسنه، وأحمد (21919، 21923، 21928)، وصححه ابن حبان (6943)، والحاكم (3/71، 145)."},{"num":7696,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قِيلَ لِعُمَرَ: أَلاَ تَسْتَخْلِفُ؟ قَالَ: إِنْ أَسْتَخْلِفْ فَقَدِ اسْتَخْلَفَ مَنْ هُوَ خَيْرٌ مِنِّي أَبُو بَكْرٍ، وَإِنْ أَتْرُكْ فَقَدْ تَرَكَ مَنْ هُوَ خَيْرٌ مِنِّي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَثْنَوْا عَلَيْهِ فَقَالَ: رَاغِبٌ رَاهِبٌ، وَدِدْتُ أَنِّي نَجَوْتُ مِنْهَا كَفَافًا لاَ لِي وَلاَ عَلَىَّ، لاَ أَتَحَمَّلُهَا حَيًّا وَمَيِّتًا."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7218)، ومسلم في الإمارة (1823: 11) كلاهما من طريق هشام بن عروة، عن أبيه، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7218) and Muslim (1823:11).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: It was said to ʿUmar: “Will you not appoint a successor?” He said: “If I appoint a successor, then one better than me appointed a successor: Abu Bakr. And if I leave it, then one better than me left it: the Messenger of Allah ﷺ.” They praised him, and he said: “One hoping and fearing. I wish that I could escape it evenly, neither for me nor against me. I do not want to bear it alive or dead.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7218)، ومسلم (1823:11)."},{"num":7697,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ:  دَخَلْتُ عَلَى حَفْصَةَ، فَقَالَتْ: أَعَلِمْتَ أَنَّ أَبَاكَ غَيْرُ مُسْتَخْلِفٍ؟ قَالَ: قُلْتُ: مَا كَانَ لِيَفْعَلَ، قَالَتْ: إِنَّهُ فَاعِلٌ، قَالَ: فَحَلَفْتُ أَنِّي أُكَلِّمُهُ فِي ذَلِكَ، فَسَكَتُّ، حَتَّى غَدَوْتُ، وَلَمْ أُكَلِّمْهُ، قَالَ: فَكُنْتُ كَأَنَّمَا أَحْمِلُ بِيَمِينِي جَبَلًا، حَتَّى رَجَعْتُ، فَدَخَلْتُ عَلَيْهِ، فَسَأَلَنِي عَنْ حَالِ النَّاسِ، وَأَنَا أُخْبِرُهُ، قَالَ: ثُمَّ قُلْتُ لَهُ: إِنِّي سَمِعْتُ النَّاسَ يَقُولُونَ مَقَالَةً، فَآلَيْتُ أَنْ أَقُولَهَا لَكَ، زَعَمُوا أَنَّكَ غَيْرُ مُسْتَخْلِفٍ، وَإِنَّهُ لَوْ كَانَ لَكَ رَاعِي إِبِلٍ أَوْ رَاعِي غَنَمٍ ثُمَّ جَاءَكَ وَتَرَكَهَا، رَأَيْتَ أَنْ قَدْ ضَيَّعَ، فَرِعَايَةُ النَّاسِ أَشَدُّ. قَالَ: فَوَافَقَهُ قَوْلِي، فَوَضَعَ رَأْسَهُ سَاعَةً ثُمَّ رَفَعَهُ إِلَيَّ فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يَحْفَظُ دِينَهُ، وَإِنِّي لَئِنْ لَا أَسْتَخْلِفْ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَسْتَخْلِفْ، وَإِنْ أَسْتَخْلِفْ فَإِنَّ أَبَا بَكْرٍ قَدِ اسْتَخْلَفَ، قَالَ: فَوَاللهِ مَا هُوَ إِلَّا أَنْ ذَكَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ، فَعَلِمْتُ أَنَّهُ لَمْ يَكُنْ لِيَعْدِلَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَدًا، وَأَنَّهُ غَيْرُ مُسْتَخْلِفٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1823: 12) من طريق عبد الرزاق أخبرنا ، عن الزهري، أخبرني سالم، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1823:12).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["Ibn ʿUmar said: I entered upon Hafsah, and she said: “Do you know that your father is not appointing a successor?” I said: “He would not do that.” She said: “He will.” So I swore that I would speak to him about it, but I remained silent until morning and did not speak to him. He said: It was as though I was carrying a mountain because of my oath until I returned and entered upon him. He asked me about the condition of the people, and I informed him. Then I said to him: “I heard the people saying something, and I swore that I would say it to you. They claim that you are not appointing a successor. If you had a shepherd of camels or a shepherd of sheep, then he came to you after leaving them, you would think he had neglected them. Caring for the people is even more serious.” He said: My statement agreed with him, so he lowered his head for a while, then raised it toward me and said: “Allah, Mighty and Majestic, will preserve His religion. If I do not appoint a successor, then the Messenger of Allah ﷺ did not appoint one. And if I appoint a successor, then Abu Bakr appointed one.” He said: By Allah, as soon as he mentioned the Messenger of Allah ﷺ and Abu Bakr, I knew that he would not equate anyone with the Messenger of Allah ﷺ, and that he would not appoint a successor."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1823:12)."},{"num":7698,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ مَيْمُونٍ الأَوْدِيِّ، قَالَ: رَأَيْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: يَا عَبْدَ اللَّهِ بْنَ عُمَرَ، اذْهَبْ إِلَى أُمِّ الْمُؤْمِنِينَ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَقُلْ: يَقْرَأُ عُمَرُ بْنُ الْخَطَّابِ عَلَيْكِ السَّلاَمَ، ثُمَّ سَلْهَا أَنْ أُدْفَنَ مَعَ صَاحِبَىَّ. قَالَتْ: كُنْتُ أُرِيدُهُ لِنَفْسِي، فَلأُوثِرَنَّهُ الْيَوْمَ عَلَى نَفْسِي. فَلَمَّا أَقْبَلَ قَالَ لَهُ: مَا لَدَيْكَ؟ قَالَ: أَذِنَتْ لَكَ يَا أَمِيرَ الْمُؤْمِنِينَ. قَالَ: مَا كَانَ شَىْءٌ أَهَمَّ إِلَىَّ مِنْ ذَلِكَ الْمَضْجَعِ، فَإِذَا قُبِضْتُ فَاحْمِلُونِي، ثُمَّ سَلِّمُوا، ثُمَّ قُلْ: يَسْتَأْذِنُ عُمَرُ بْنُ الْخَطَّابِ. فَإِنْ أَذِنَتْ لِي فَادْفِنُونِي، وَإِلاَّ فَرُدُّونِي إِلَى مَقَابِرِ الْمُسْلِمِينَ، إِنِّي لاَ أَعْلَمُ أَحَدًا أَحَقَّ بِهَذَا الأَمْرِ مِنْ هَؤُلاَءِ النَّفَرِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَنْهُمْ رَاضٍ، فَمَنِ اسْتَخْلَفُوا بَعْدِي فَهُوَ الْخَلِيفَةُ، فَاسْمَعُوا لَهُ وَأَطِيعُوا. فَسَمَّى عُثْمَانَ، وَعَلِيًّا، وَطَلْحَةَ، وَالزُّبَيْرَ، وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ، وَسَعْدَ بْنَ أَبِي وَقَّاصٍ، وَوَلَجَ عَلَيْهِ شَابٌّ مِنَ الأَنْصَارِ فَقَالَ: أَبْشِرْ يَا أَمِيرَ الْمُؤْمِنِينَ بِبُشْرَى اللَّهِ، كَانَ لَكَ مِنَ الْقَدَمِ فِي الإِسْلاَمِ مَا قَدْ عَلِمْتَ، ثُمَّ اسْتُخْلِفْتَ فَعَدَلْتَ، ثُمَّ الشَّهَادَةُ بَعْدَ هَذَا كُلِّهِ. فَقَالَ: لَيْتَنِي يَا ابْنَ أَخِي وَذَلِكَ كَفَافًا لاَ عَلَىَّ وَلاَ لِي، أُوصِي الْخَلِيفَةَ مِنْ بَعْدِي بِالْمُهَاجِرِينَ الأَوَّلِينَ خَيْرًا، أَنْ يَعْرِفَ لَهُمْ حَقَّهُمْ، وَأَنْ يَحْفَظَ لَهُمْ حُرْمَتَهُمْ، وَأُوصِيهِ بِالأَنْصَارِ خَيْرًا الَّذِينَ تَبَوَّءُوا الدَّارَ وَالإِيمَانَ أَنْ يُقْبَلَ مِنْ مُحْسِنِهِمْ، وَيُعْفَى عَنْ مُسِيئِهِمْ، وَأُوصِيهِ بِذِمَّةِ اللَّهِ وَذِمَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُوفَى لَهُمْ بِعَهْدِهِمْ، وَأَنْ يُقَاتَلَ مِنْ وَرَائِهِمْ، وَأَنْ لاَ يُكَلَّفُوا فَوْقَ طَاقَتِهِمْ."],"takhrij":"صحيح: رواه البخاري في الزكاة (1392) عن قتيبة، حدثنا جرير بن عبدالحميد حدثنا حصين بن عبد الرحمن، عن عمرو بن ميمون الأودي فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1392).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["ʿAmr ibn Maymun al-Awdi said: I saw ʿUmar ibn al-Khattab, may Allah be pleased with him, say: “ʿAbdullah ibn ʿUmar, go to the Mother of the Believers ʿA’ishah, may Allah be pleased with her, and say: ʿUmar ibn al-Khattab sends you greetings of peace. Then ask her that I be buried with my two companions.” She said: “I had wanted it for myself, but today I will prefer him over myself.” When he returned, ʿUmar said to him: “What do you have?” He said: “She has granted permission for you, Commander of the Believers.” He said: “Nothing was more important to me than that resting place. When I am taken in death, carry me, then give greetings of peace, then say: ʿUmar ibn al-Khattab seeks permission. If she gives permission, bury me there; otherwise return me to the graveyard of the Muslims. I do not know anyone more entitled to this affair than these individuals with whom the Messenger of Allah ﷺ was pleased when he died. Whoever they appoint after me is the caliph, so listen to him and obey.” He named ʿUthman, ʿAli, Talhah, al-Zubayr, ʿAbd al-Rahman ibn ʿAwf, and Saʿd ibn Abi Waqqas. A young man from the Ansar entered upon him and said: “Receive glad tidings, Commander of the Believers, with the glad tidings of Allah. You had precedence in Islam as you know, then you were appointed and acted justly, then martyrdom after all of this.” He said: “I wish, my nephew, that it would be just even: neither against me nor for me. I advise the caliph after me to treat the early Emigrants well, to recognize their rights and preserve their honor. I advise him to treat the Helpers well, those who settled the city and faith, to accept from those among them who do good and pardon those who do wrong. And I advise him concerning the covenant of Allah and the covenant of His Messenger ﷺ, that their agreement be fulfilled, that they be defended from behind, and that they not be burdened beyond their ability.”"]}},"tuhfa":{},"full":1,"rep":[3817],"tks":"صحيح: رواه البخاري (1392)."},{"num":7699,"demo":false,"sanad":"","matn":["عن الْمِسْوَرِ بن مَخْرَمَةَ: أَخْبَرَهُ. أَنَّ الرَّهْطَ الَّذِينَ وَلاَّهُمْ عُمَرُ، اجْتَمَعُوا فَتَشَاوَرُوا، قَالَ لَهُمْ: عَبْدُ الرَّحْمَنِ لَسْتُ بِالَّذِي أُنَافِسُكُمْ عَلَى هَذَا الأَمْرِ، وَلَكِنَّكُمْ إِنْ شِئْتُمُ اخْتَرْتُ لَكُمْ مِنْكُمْ. فَجَعَلُوا ذَلِكَ إِلَى عَبْدِ الرَّحْمَنِ، فَلَمَّا وَلَّوْا عَبْدَ الرَّحْمَنِ أَمْرَهُمْ، فَمَالَ النَّاسُ عَلَى عَبْدِ الرَّحْمَنِ، حَتَّى مَا أَرَى أَحَدًا مِنَ النَّاسِ يَتْبَعُ أُولَئِكَ الرَّهْطَ، وَلاَ يَطَأُ عَقِبَهُ، وَمَالَ النَّاسُ عَلَى عَبْدِ الرَّحْمَنِ يُشَاوِرُونَهُ تِلْكَ اللَّيَالِيَ، حَتَّى إِذَا كَانَتِ اللَّيْلَةُ الَّتِي أَصْبَحْنَا مِنْهَا، فَبَايَعْنَا عُثْمَانَ.","قَالَ الْمِسْوَرُ: طَرَقَنِي عَبْدُ الرَّحْمَنِ بَعْدَ هَجْعٍ مِنَ اللَّيْلِ، فَضَرَبَ الْبَابَ حَتَّى اسْتَيْقَظْتُ فَقَالَ: أَرَاكَ نَائِمًا، فَوَاللَّهِ مَا اكْتَحَلْتُ هَذِهِ اللَّيْلَةَ بِكَبِيرِ نَوْمٍ، انْطَلِقْ، فَادْعُ الزُّبَيْرَ وَسَعْدًا فَدَعَوْتُهُمَا لَهُ فَشَاوَرَهُمَا، ثُمَّ دَعَانِي فَقَالَ: ادْعُ لِي عَلِيًّا، فَدَعَوْتُهُ، فَنَاجَاهُ حَتَّى ابْهَارَّ اللَّيْلُ، ثُمَّ قَامَ عَلِيٌّ مِنْ عِنْدِهِ وَهْوَ عَلَى طَمَعٍ، وَقَدْ كَانَ عَبْدُ الرَّحْمَنِ يَخْشَى مِنْ عَلِيٍّ شَيْئًا، ثُمَّ قَالَ: ادْعُ لِي عُثْمَانَ، فَدَعَوْتُهُ، فَنَاجَاهُ حَتَّى فَرَّقَ بَيْنَهُمَا الْمُؤَذِّنُ بِالصُّبْحِ، فَلَمَّا صَلَّى لِلنَّاسِ الصُّبْحَ، وَاجْتَمَعَ أُولَئِكَ الرَّهْطُ عِنْدَ الْمِنْبَرِ، فَأَرْسَلَ إِلَى مَنْ كَانَ حَاضِرًا مِنَ الْمُهَاجِرِينَ وَالأَنْصَارِ، وَأَرْسَلَ إِلَى أُمَرَاءِ الأَجْنَادِ، وَكَانُوا وَافَوْا تِلْكَ الْحَجَّةَ مَعَ عُمَرَ، فَلَمَّا اجْتَمَعُوا تَشَهَّدَ عَبْدُ الرَّحْمَنِ، ثُمَّ قَالَ: أَمَّا بَعْدُ! يَا عَلِيُّ، إِنِّي قَدْ نَظَرْتُ فِي أَمْرِ النَّاسِ، فَلَمْ أَرَهُمْ يَعْدِلُونَ بِعُثْمَانَ، فَلاَ تَجْعَلَنَّ عَلَى نَفْسِكَ سَبِيلاً، فَقَالَ: أُبَايِعُكَ عَلَى سُنَّةِ اللَّهِ وَرَسُولِهِ، وَالْخَلِيفَتَيْنِ مِنْ بَعْدِهِ، فَبَايَعَهُ عَبْدُ الرَّحْمَنِ، وَبَايَعَهُ النَّاسُ الْمُهَاجِرُونَ، وَالأَنْصَارُ، وَأُمَرَاءُ الأَجْنَادِ، وَالْمُسْلِمُونَ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7207) عن عبد الله بن محمد بن أسماء حدثنا جويرية، عن مالك، عن الزهري، أن حميد بن عبد الرحمن، أخبره أن المسور بن مخرمة أخبره فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7207).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["Al-Miswar ibn Makhramah narrated that the group whom ʿUmar appointed gathered and consulted. ʿAbd al-Rahman said to them: “I will not compete with you for this matter, but if you wish, I will choose one from among you for you.” So they entrusted that to ʿAbd al-Rahman. When they entrusted their matter to ʿAbd al-Rahman, the people turned to ʿAbd al-Rahman, until I did not see anyone among the people following that group or walking behind them. The people turned to ʿAbd al-Rahman, consulting him during those nights, until the night after which we woke and pledged allegiance to ʿUthman. Al-Miswar said: ʿAbd al-Rahman came to me after a portion of the night had passed and knocked on the door until I woke up. He said: “I see that you are sleeping. By Allah, I have not had much sleep this night. Go and call al-Zubayr and Saʿd.” So I called them for him, and he consulted them. Then he called me and said: “Call ʿAli for me.” So I called him, and he spoke privately with him until the night became very dark. Then ʿAli left him while still hoping for the matter, and ʿAbd al-Rahman had feared something from ʿAli. Then he said: “Call ʿUthman for me.” So I called him, and he spoke privately with him until the caller to prayer separated them at dawn. When he led the people in the dawn prayer and that group gathered near the pulpit, he sent for those present from the Emigrants and the Helpers, and he sent for the commanders of the armies, who had attended that pilgrimage with ʿUmar. When they gathered, ʿAbd al-Rahman testified, then said: “As for what follows: ʿAli, I have looked into the matter of the people, and I do not see them equating anyone with ʿUthman, so do not make a case against yourself.” He said: “I pledge allegiance to you upon the way of Allah and His Messenger, and the two caliphs after him.” So ʿAbd al-Rahman pledged allegiance to him, and the people pledged allegiance to him: the Emigrants, the Helpers, the commanders of the armies, and the Muslims."]}},"tuhfa":{},"full":1,"rep":[9893],"tks":"صحيح: رواه البخاري (7207)."},{"num":7700,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ مَيْمُونٍ قَالَ: فَلَمَّا قُبِضَ –يَعْنِي عُمَرَ بن الْخَطَّابِ- خَرَجْنَا بِهِ، فَانْطَلَقْنَا نَمْشِي، فَسَلَّمَ عَبْدُ اللَّهِ بْنُ عُمَرَ قَالَ: يَسْتَأْذِنُ عُمَرُ بْنُ الْخَطَّابِ قَالَتْ: أَدْخِلُوهُ، فَأُدْخِلَ، فَوُضِعَ هُنَالِكَ مَعَ صَاحِبَيْهِ، فَلَمَّا فُرِغَ مِنْ دَفْنِهِ اجْتَمَعَ هَؤُلاَءِ الرَّهْطُ فَقَالَ عَبْدُ الرَّحْمَنِ: اجْعَلُوا أَمْرَكُمْ إِلَى ثَلاَثَةٍ مِنْكُمْ، فَقَالَ الزُّبَيْرُ: قَدْ جَعَلْتُ أَمْرِي إِلَى عَلِيٍّ، فَقَالَ طَلْحَةُ: قَدْ جَعَلْتُ أَمْرِي إِلَى عُثْمَانَ، وَقَالَ سَعْدٌ: قَدْ جَعَلْتُ أَمْرِي إِلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ فَقَالَ عَبْدُ الرَّحْمَنِ: أَيُّكُمَا تَبَرَّأَ مِنْ هَذَا الأَمْرِ، فَنَجْعَلُهُ إِلَيْهِ، وَاللَّهُ عَلَيْهِ وَالإِسْلاَمُ، لَيَنْظُرَنَّ أَفْضَلَهُمْ فِي نَفْسِهِ، فَأُسْكِتَ الشَّيْخَانِ، فَقَالَ عبدالرحمن: أَفَتَجْعَلُونَهُ إِلَى، وَاللَّهُ عَلَى أَنْ لاَ آلِ عَنْ أَفْضَلِكُمْ؟ قَالاَ: نَعَمْ فَأَخَذَ بِيَدِ أَحَدِهِمَا، فَقَالَ: لَكَ قَرَابَةٌ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَالْقَدَمُ فِي الإِسْلاَمِ مَا قَدْ عَلِمْتَ، فَاللَّهُ عَلَيْكَ لَئِنْ أَمَّرْتُكَ لَتَعْدِلَنَّ، وَلَئِنْ أَمَّرْتُ عُثْمَانَ، لَتَسْمَعَنَّ وَلَتُطِيعَنَّ، ثُمَّ خَلاَ بِالآخَرِ، فَقَالَ لَهُ: مِثْلَ ذَلِكَ، فَلَمَّا أَخَذَ الْمِيثَاقَ قَالَ: ارْفَعْ يَدَكَ يَا عُثْمَانُ، فَبَايَعَهُ فَبَايَعَ لَهُ عَلِيٌّ، وَوَلَجَ أَهْلُ الدَّارِ فَبَايَعُوهُ."],"takhrij":"صحيح: رواه البخاري في فضائل أصحاب النبي صلى الله عليه وسلم (3700) عن موسى بن إسماعيل حدثنا أبو عوانة، عن حصين، عن عمرو بن ميمون قال: فذكر الحديث بطوله، وفيه قصة مقتل عمر رضي الله عنه.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3700).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["ʿAmr ibn Maymun said: When he was taken in death — meaning ʿUmar ibn al-Khattab — we went out with him and walked. ʿAbdullah ibn ʿUmar gave greetings of peace and said: “ʿUmar ibn al-Khattab seeks permission.” She said: “Bring him in.” So he was brought in and placed there with his two companions. When his burial was completed, those members of the group gathered. ʿAbd al-Rahman said: “Entrust your matter to three among you.” Al-Zubayr said: “I have entrusted my matter to ʿAli.” Talhah said: “I have entrusted my matter to ʿUthman.” Saʿd said: “I have entrusted my matter to ʿAbd al-Rahman ibn ʿAwf.” ʿAbd al-Rahman said: “Which of you two will withdraw from this matter so that we may entrust it to him, with Allah and Islam upon him, that he will surely look to the one he considers best?” The two elders remained silent. ʿAbd al-Rahman said: “Will you entrust it to me, with Allah upon me that I will not fall short in choosing the best of you?” They said: “Yes.” He took the hand of one of them and said: “You have kinship with the Messenger of Allah ﷺ and precedence in Islam as you know. By Allah, if I appoint you, you must act justly; and if I appoint ʿUthman, you must listen and obey.” Then he met privately with the other and said the same to him. When he had taken the covenant, he said: “Raise your hand, ʿUthman.” He pledged allegiance to him, ʿAli pledged allegiance to him, and the people of the house entered and pledged allegiance to him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3700)."},{"num":7701,"demo":false,"sanad":"","matn":["عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ:  أَنَّ عُمَرَ بْنَ الْخَطَّابِ خَطَبَ يَوْمَ الْجُمُعَةِ فَذَكَرَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَذَكَرَ أَبَا بَكْرٍ، قَالَ: إِنِّي رَأَيْتُ كَأَنَّ دِيكًا نَقَرَنِي ثَلَاثَ نَقَرَاتٍ، وَإِنِّي لَا أُرَاهُ إِلَّا حُضُورَ أَجَلِي. وَإِنَّ أَقْوَامًا يَأْمُرُونَنِي أَنْ أَسْتَخْلِفَ، وَإِنَّ اللَّهَ لَمْ يَكُنْ لِيُضَيِّعَ دِينَهُ وَلَا خِلَافَتَهُ، وَلَا الَّذِي بَعَثَ بِهِ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَإِنْ عَجِلَ بِي أَمْرٌ، فَالْخِلَافَةُ شُورَى بَيْنَ هَؤُلَاءِ السِّتَّةِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَنْهُمْ رَاضٍ. وَإِنِّي قَدْ عَلِمْتُ أَنَّ أَقْوَامًا يَطْعَنُونَ فِي هَذَا الْأَمْرِ، أَنَا ضَرَبْتُهُمْ بِيَدِي هَذِهِ عَلَى الْإِسْلَامِ، فَإِنْ فَعَلُوا ذَلِكَ فَأُولَئِكَ أَعْدَاءُ اللهِ الْكَفَرَةُ الضُّلَّالُ."],"takhrij":"صحيح: رواه مسلم في المساجد (567: 78) عن محمد بن المثنى حدثنا يحيى بن سعيد حدثنا هشام حدثنا قتادة عن سالم بن أبي الجعد عن معدان بن أبي طلحة فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (567:78).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["Maʿdan ibn Abi Talhah narrated that ʿUmar ibn al-Khattab delivered a sermon on Friday, mentioned the Prophet of Allah ﷺ, and mentioned Abu Bakr. He said: “I saw as though a rooster pecked me three pecks, and I only see that as the coming of my death. Some people are telling me to appoint a successor. Allah would never let His religion, His caliphate, or that with which He sent His Prophet ﷺ be lost. If a matter comes quickly upon me, then the caliphate is to be decided by consultation among these six men with whom the Messenger of Allah ﷺ was pleased when he died. I know that some people will criticize this matter, though I struck them with this hand of mine for Islam. If they do that, then they are the enemies of Allah, disbelieving and misguided.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (567:78)."},{"num":7702,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَدِمَ مُسَيْلِمَةُ الْكَذَّابُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ يَقُولُ: إِنْ جَعَلَ لِي مُحَمَّدٌ الأَمْرَ مِنْ بَعْدِهِ تَبِعْتُهُ. وَقَدِمَهَا فِي بَشَرٍ كَثِيرٍ مِنْ قَوْمِهِ، فَأَقْبَلَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَعَهُ ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ، وَفِي يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِطْعَةُ جَرِيدٍ، حَتَّى وَقَفَ عَلَى مُسَيْلِمَةَ فِي أَصْحَابِهِ، فَقَالَ: لَوْ سَأَلْتَنِي هَذِهِ الْقِطْعَةَ مَا أَعْطَيْتُكَهَا، وَلَنْ تَعْدُوَ أَمْرَ اللَّهِ فِيكَ، وَلَئِنْ أَدْبَرْتَ لَيَعْقِرَنَّكَ اللَّهُ، وَإِنِّي لأَرَاكَ الَّذِي أُرِيتُ فِيكَ مَا رَأَيْتُ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3620)، ومسلم في الرؤيا (2273: 21) كلاهما من طريق أبي اليمان، أخبرنا شعيب عن عبد الله بن أبي حسين، حدثنا نافع بن جبير، عن ابن عباس رضي الله عنهما قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب طلب مسيلمة الكذاب الخلافة بعد النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3620) and Muslim (2273:21).","chapter_en":"Musaylimah the Liar’s Request for the Caliphate After the Prophet ﷺ","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":32,"content":{"translation":{"en":["Ibn ʿAbbas said: Musaylimah the Liar came during the time of the Messenger of Allah ﷺ and began saying: “If Muhammad appoints me to the affair after him, I will follow him.” He came with many people from his tribe. The Messenger of Allah ﷺ approached him, with Thabit ibn Qays ibn Shammas, and in the hand of the Messenger of Allah ﷺ was a piece of palm stalk, until he stood over Musaylimah among his companions. He said: “If you asked me for this piece, I would not give it to you. You will not go beyond what Allah has decreed for you. If you turn away, Allah will destroy you. I see that you are the one concerning whom I was shown what I saw. This is Thabit; he will answer you on my behalf.” Then he turned away from him."]},"buhuth":{"en":["His statement, “If Muhammad appoints me to the affair after him,” means the caliphate.","The Prophet’s statement ﷺ, “I see that you are the one concerning whom I was shown,” refers to the vision he saw. ʿUbaydullah ibn ʿAbdullah said: I asked ʿAbdullah ibn ʿAbbas about the vision of the Messenger of Allah ﷺ that he mentioned, and Ibn ʿAbbas said: The Messenger of Allah ﷺ told me: “While I was sleeping, I was shown that two bracelets of gold had been placed in my hands. I was disturbed by them and disliked them, then I was given permission and blew upon them, so they flew away. I interpreted them as two liars who would emerge.” ʿUbaydullah said: One of them was al-ʿAnsi, whom Fayruz killed in Yemen, and the other was Musaylimah the Liar. Al-Bukhari mentioned it (4379).","The phrase “in the house of the daughter of al-Harith, and beneath him was the daughter of al-Harith ibn Kurayz” means she was the wife of Musaylimah the Liar before she married another, and for that reason Musaylimah and his people stayed with her. Their number was seventeen men, as al-Waqidi mentioned."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3620)، ومسلم (2273:21)."},{"num":7703,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا بَعَثَ اللَّهُ مِنْ نَبِيٍّ وَلاَ اسْتَخْلَفَ مِنْ خَلِيفَةٍ، إِلاَّ كَانَتْ لَهُ بِطَانَتَانِ، بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ، وَتَحُضُّهُ عَلَيْهِ، وَبِطَانَةٌ تَأْمُرُهُ بِالشَّرِّ، وَتَحُضُّهُ عَلَيْهِ، فَالْمَعْصُومُ مَنْ عَصَمَ اللَّهُ تَعَالَى."],"takhrij":"صحيح: رواه البخاري في الأحكام (7198) عن أصبغ، أخبرنا ابن وهب، أخبرني يونس، عن ابن شهاب، عن أبي سلمة، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب الحث على اتخاذ البطانة الصالحة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7198).","chapter_en":"Encouragement to Take Righteous Advisers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated from the Prophet ﷺ that he said: “Allah never sent a prophet and never appointed a caliph except that he had two inner circles: an inner circle that commands him to what is right and urges him toward it, and an inner circle that commands him to evil and urges him toward it. The protected one is the one whom Allah the Exalted protects.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7198)."},{"num":7704,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ، أَنَّهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا بُعِثَ مِنْ نَبِيٍّ وَلاَ كَانَ بَعْدَهُ مِنْ خَلِيفَةٍ إِلاَّ وَلَهُ بِطَانَتَانِ: بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ وَتَنْهَاهُ عَنِ الْمُنْكَرِ، وَبِطَانَةٌ لاَ تَأْلُوهُ خَبَالاً، فَمَنْ وُقِيَ بِطَانَةَ السُّوءِ فَقَدْ وُقِيَ."],"takhrij":"صحيح: رواه النسائي (4203)، والطحاوي في شرح المشكل (2112)، والطبراني في الكبير (3895) من طرق عن الليث –هو ابن سعد- عن عبيد الله بن أبي جعفر عن صفوان –هو ابن سُليم- عن أبي سلمة، عن أبي أيوب فذكره.","grade":"صحيح","chapter_ar":"باب الحث على اتخاذ البطانة الصالحة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4203), al-Tahawi in Sharh al-Mushkil (2112), and al-Tabarani in al-Kabir (4/156).","chapter_en":"Encouragement to Take Righteous Advisers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abu Ayyub said: I heard the Messenger of Allah ﷺ say: “No prophet was sent, and no caliph came after him, except that he had two inner circles: an inner circle that commands him to what is right and forbids him from what is wrong, and an inner circle that spares no effort in corrupting him. Whoever is protected from the evil inner circle has been protected.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4203)، والطحاوي في شرح المشكل (2112)، والطبراني في الكبير (3895)."},{"num":7705,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ وَالٍ إِلاَّ وَلَهُ بِطَانَتَانِ: بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ، وَتَنْهَاهُ عَنِ الْمُنْكَرِ، وَبِطَانَةٌ لاَ تَأْلُوهُ خَبَالاً، فَمَنْ وُقِيَ شَرَّهَا فَقَدْ وُقِيَ، وَهُوَ مِنَ الَّتِي تَغْلِبُ عَلَيْهِ مِنْهُمَا."],"takhrij":"صحيح: رواه النسائي (4201)، وأحمد (7239)، وصحّحه ابن حبان (6191) كلهم من حديث الزهري، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الحث على اتخاذ البطانة الصالحة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4201), Ahmad (7239), and graded authentic by Ibn Hibban (6191).","chapter_en":"Encouragement to Take Righteous Advisers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There is no governor except that he has two inner circles: an inner circle that commands him to what is right and forbids him from what is wrong, and an inner circle that spares no effort in corrupting him. Whoever is protected from its evil has been protected, and he will be according to whichever of the two overcomes him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4201)، وأحمد (7239)، وصححه ابن حبان (6191)."},{"num":7706,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَرَادَ اللَّهُ بِالأَمِيرِ خَيْرًا جَعَلَ لَهُ وَزِيرَ صِدْقٍ إِنْ نَسِيَ ذَكَّرَهُ، وَإِنْ ذَكَرَ أَعَانَهُ، وَإِذَا أَرَادَ اللَّهُ بِهِ غَيْرَ ذَلِكَ جَعَلَ لَهُ وَزِيرَ سُوءٍ، إِنْ نَسِيَ لَمْ يُذَكِّرْهُ، وَإِنْ ذَكَرَ لَمْ يُعِنْهُ."],"takhrij":"صحيح: رواه أبو داود (2932) واللفظ له، والنسائي (4204)، وأحمد (24414)، وابن حبان (4494)، والبيهقي (20320) كلهم من طرق عن القاسم بن محمد، عن عائشة فذكرته. وفي بعض طرقه ضعف يسير يتقوى بمجيئه من طرق أخرى.","grade":"صحيح","chapter_ar":"باب اتخاذ الوزير","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2932), with his wording; al-Nasa’i (4204), Ahmad (24414), Ibn Hibban (4494), and al-Bayhaqi (10/111–112). Some of its routes contain slight weakness, which is strengthened by its transmission through other routes.","chapter_en":"Taking a Minister","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “When Allah intends good for a ruler, He gives him a truthful minister: if he forgets, he reminds him, and if he remembers, he helps him. And when Allah intends otherwise for him, He gives him an evil minister: if he forgets, he does not remind him, and if he remembers, he does not help him.”"]}},"tuhfa":{},"full":1,"rep":[6718],"tks":"صحيح: رواه أبو داود (2932) واللفظ له، والنسائي (4204)، وأحمد (24414)، وابن حبان (4494)، والبيهقي (20320)."},{"num":7707,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ عَمِيرَةَ الْكِنْدِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  مَنِ اسْتَعْمَلْنَاهُ مِنْكُمْ عَلَى عَمَلٍ، فَكَتَمَنَا مِخْيَطًا فَمَا فَوْقَهُ، كَانَ غُلُولًا يَأْتِي بِهِ يَوْمَ الْقِيَامَةِ. قَالَ: فَقَامَ إِلَيْهِ رَجُلٌ أَسْوَدُ مِنَ الْأَنْصَارِ كَأَنِّي أَنْظُرُ إِلَيْهِ، فَقَالَ: يَا رَسُولَ اللَّهِ، اقْبَلْ عَنِّي عَمَلَكَ، قَالَ: وَمَا لَكَ؟ قَالَ: سَمِعْتُكَ تَقُولُ: كَذَا وَكَذَا، قَالَ: وَأَنَا أَقُولُهُ الْآنَ، مَنِ اسْتَعْمَلْنَاهُ مِنْكُمْ عَلَى عَمَلٍ فَلْيَجِئْ بِقَلِيلِهِ وَكَثِيرِهِ، فَمَا أُوتِيَ مِنْهُ أَخَذَ، وَمَا نُهِيَ عَنْهُ انْتَهَى."],"takhrij":"صحيح: رواه مسلم في الإمارة (1833) عن أبي بكر بن أبي شيبة، حدثنا وكيع بن الجراح، حدثنا إسماعيل بن أبي خالد، عن قيس بن أبي حازم، عن عدي بن عميرة الكندي قال: فذكره.","grade":"صحيح","chapter_ar":"باب إثم من استُعمل على عمل، فسرق منه شيئًا","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1833).","chapter_en":"The Sin of One Appointed to a Task Who Steals Anything from It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":35,"content":{"translation":{"en":["ʿAdi ibn ʿUmayrah al-Kindi said: I heard the Messenger of Allah ﷺ say: “Whoever among you we appoint over a task, and he conceals from us even a needle or anything greater than it, it will be misappropriation that he will bring on the Day of Resurrection.” He said: A black man from the Ansar stood up to him — it is as though I can still see him — and said: “Messenger of Allah, take back your appointment from me.” He said: “What is the matter with you?” He said: “I heard you say such-and-such.” He said: “And I say it now: Whoever among you we appoint over a task, let him bring its little and its much. Whatever he is given from it, he may take, and whatever he is forbidden from, he must refrain from.”"]}},"tuhfa":{},"full":1,"rep":[4003],"tks":"صحيح: رواه مسلم (1833)."},{"num":7708,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ مَالِكٍ، مِنْ رَهْطِهِ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً، فَسَلَحْتُ رَجُلاً مِنْهُمْ سَيْفًا، فَلَمَّا رَجَعَ قَالَ: لَوْ رَأَيْتَ مَا لاَمَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَعَجَزْتُمْ إِذْ بَعَثْتُ رَجُلاً مِنْكُمْ فَلَمْ يَمْضِ لأَمْرِي أَنْ تَجْعَلُوا مَكَانَهُ مَنْ يَمْضِي لأَمْرِي."],"takhrij":"حسن: رواه أبو داود (2627)، وأحمد (17007) وصحّحه ابن حبان (4740)، والحاكم (2539) كلهم من طريق سليمان بن المغيرة حدثنا حميد بن هلال، عن بشر بن عاصم، عن عقبة بن مالك –وكان من رهطه- قال: فذكره.","grade":"حسن","chapter_ar":"باب لا يجوز للعامل أن يخالف أمر الإمام","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2627), Ahmad (17007), and graded authentic by Ibn Hibban (4740) and al-Hakim (2539).","chapter_en":"It Is Not Permissible for an Appointed Worker to Oppose the Command of the Leader","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":36,"content":{"translation":{"en":["ʿUqbah ibn Malik said: The Prophet ﷺ sent out a detachment, and I equipped one of its men with a sword. When he returned, he said: “If only you had seen how the Messenger of Allah ﷺ reproached us!” He said: “Were you unable, when I sent a man from among you and he did not carry out my command, to appoint in his place someone who would carry out my command?”"]},"buhuth":{"en":["His phrase “I equipped him” means: I gave him a weapon."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2627)، وأحمد (17007)، وصححه ابن حبان (4740)، والحاكم (2539)."},{"num":7709,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ الساعدي قَالَ: اسْتَعْمَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً مِنْ بَنِي أَسَدٍ يُقَالُ لَهُ: ابْنُ الأُتَبِيَّةِ عَلَى صَدَقَةٍ فَلَمَّا قَدِمَ قَالَ: هَذَا لَكُمْ، وَهَذَا أُهْدِيَ لِي فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ، قَالَ سُفْيَانُ أَيْضًا: فَصَعِدَ الْمِنْبَرَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: مَا بَالُ الْعَامِلِ نَبْعَثُهُ فَيَأْتِي يَقُولُ: هَذَا لَكَ، وَهَذَا لِي فَهَلاَّ جَلَسَ فِي بَيْتِ أَبِيهِ وَأُمِّهِ، فَيَنْظُرُ أَيُهْدَى لَهُ أَمْ لاَ؟ وَالَّذِي نَفْسِي بِيَدِهِ لاَ يَأْتِي بشيء إِلاَّ جَاءَ بِهِ يَوْمَ الْقِيَامَةِ يَحْمِلُهُ عَلَى رَقَبَتِهِ، إِنْ كَانَ بَعِيرًا لَهُ رُغَاءٌ، أَوْ بَقَرَةً لَهَا خُوَارٌ، أَوْ شَاةً تَيْعَرُ، ثُمَّ رَفَعَ يَدَيْهِ حَتَّى رَأَيْنَا عفرتي إِبْطَيْهِ، أَلاَ هَلْ بَلَّغْتُ؟ ثَلاَثًا."],"takhrij":"متفق عليه: رواه البخاري في الاحكام (7174)، ومسلم في الإمارة (1832: 26) كلاهما من طريق سفيان بن عيينة، عن الزهري أنه سمع عروة أخبرنا أبو حميد الساعدي قال: فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في هدايا العمال","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7174) and Muslim (1832:26). The wording is al-Bukhari’s.","chapter_en":"What Has Been Reported Concerning Gifts Given to Appointed Workers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":37,"content":{"translation":{"en":["Abu Humayd al-Saʿidi said: The Prophet ﷺ appointed a man from Banu Asad called Ibn al-Lutbiyyah over charity collection. When he came back, he said: “This is for you, and this was given to me as a gift.” So the Prophet ﷺ stood on the pulpit. Sufyan also said: He ascended the pulpit, praised Allah and extolled Him, then said: “What is the matter with a worker whom we send, then he comes and says: ‘This is for you, and this is for me’? Why did he not sit in the house of his father and mother and see whether he would be given gifts or not? By the One in whose hand is my soul, he will not bring anything except that he will come with it on the Day of Resurrection carrying it on his neck: if it is a camel, it will be grunting; if it is a cow, it will be mooing; and if it is a sheep, it will be bleating.” Then he raised his hands until we saw the whiteness of his armpits and said three times: “Have I conveyed?”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7174)، ومسلم (1832:26). والسياق للبخاري."},{"num":7710,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن السعدي: أَخْبَرَهُ أَنَّهُ، قَدِمَ عَلَى عُمَرَ فِي خِلاَفَتِهِ، فَقَالَ لَهُ عُمَرُ: أَلَمْ أُحَدَّثْ أَنَّكَ تَلِي مِنْ أَعْمَالِ النَّاسِ أَعْمَالاً، فَإِذَا أُعْطِيتَ الْعُمَالَةَ كَرِهْتَهَا. فَقُلْتُ: بَلَى. فَقَالَ عُمَرُ: مَا تُرِيدُ إِلَى ذَلِكَ؟ قُلْتُ: إِنَّ لِي أَفْرَاسًا وَأَعْبُدًا، وَأَنَا بِخَيْرٍ، وَأَرِيدُ أَنْ تَكُونَ عُمَالَتِي صَدَقَةً عَلَى الْمُسْلِمِينَ. قَالَ عُمَرُ: لاَ تَفْعَلْ فَإِنِّي كُنْتُ أَرَدْتُ الَّذِي أَرَدْتَ، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْطِينِي الْعَطَاءَ، فَأَقُولُ: أَعْطِهِ أَفْقَرَ إِلَيْهِ مِنِّي. حَتَّى أَعْطَانِي مَرَّةً مَالاً، فَقُلْتُ: أَعْطِهِ أَفْقَرَ إِلَيْهِ مِنِّي. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خُذْهُ فَتَمَوَّلْهُ، وَتَصَدَّقْ بِهِ، فَمَا جَاءَكَ مِنْ هَذَا الْمَالِ وَأَنْتَ غَيْرُ مُشْرِفٍ وَلاَ سَائِلٍ فَخُذْهُ، وَإِلاَّ فَلاَ تُتْبِعْهُ نَفْسَكَ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7163) عن أبي اليمان، أخبرنا شعيب، عن الزهري، أخبرني السائب بن يزيد -ابن أخت نمر- أن حويطب بن عبد العزى أخبره أن عبدالله بن السعدي أخبره فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أجرة العمال","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7163), and Muslim (1045:112) through another route from Ibn al-Saʿdi al-Maliki, who said: ʿUmar ibn al-Khattab appointed me over charity collection. When I completed it and handed it over to him, he ordered that I be given wages. I said: “I only worked for Allah, and my reward is with Allah.” He said: “Take what you have been given, for I worked during the time of the Messenger of Allah ﷺ and he gave me wages. I said the same as you said, and the Messenger of Allah ﷺ said to me: ‘When you are given something without asking, then eat from it and give charity.’”","chapter_en":"What Has Been Reported Concerning the Wages of Appointed Workers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":38,"content":{"translation":{"en":["ʿAbdullah ibn al-Saʿdi came to ʿUmar during his caliphate. ʿUmar said to him: “Have I not been told that you take charge of some of the people’s work, and when you are given wages for it, you dislike taking them?” I said: “Yes.” ʿUmar said: “What do you intend by that?” I said: “I have horses and slaves, and I am well-off, so I want my wages to be charity for the Muslims.” ʿUmar said: “Do not do that, for I once intended what you intend. The Messenger of Allah ﷺ would give me a gift, and I would say: ‘Give it to someone poorer than me,’ until one time he gave me wealth and I said: ‘Give it to someone poorer than me.’ The Prophet ﷺ said: ‘Take it, make it part of your wealth, and give charity from it. Whatever of this wealth comes to you while you are neither seeking it nor asking for it, take it; otherwise, do not let your soul follow after it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7163)، ورواه مسلم (1045:112). فقال: خذ ما أعطيت، فإني عملت على عهد رسول الله ﷺ فعملني، فقلت مثل قولك، فقال لي رسول الله ﷺ: ((إذا أعطيت شيئا من غير أن تسأل فكل وتصدق))."},{"num":7711,"demo":false,"sanad":"","matn":["عَنِ طَرِيفٍ أَبِي تَمِيمَةَ، قَالَ: شَهِدْتُ صَفْوَانَ وَجُنْدَبًا وَأَصْحَابَهُ وَهْوَ يُوصِيهِمْ فَقَالُوا: هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا؟ قَالَ: سَمِعْتُهُ يَقُولُ: مَنْ سَمَّعَ سَمَّعَ اللَّهُ بِهِ يَوْمَ الْقِيَامَةِ ـ قَالَ: ـ وَمَنْ يُشَاقِقْ يَشْقُقِ اللَّهُ عَلَيْهِ يَوْمَ الْقِيَامَةِ. فَقَالُوا أَوْصِنَا. فَقَالَ: إِنَّ أَوَّلَ مَا يُنْتِنُ مِنَ الإِنْسَانِ بَطْنُهُ، فَمَنِ اسْتَطَاعَ أَنْ لاَ يَأْكُلَ إِلاَّ طَيِّبًا فَلْيَفْعَلْ، وَمَنِ اسْتَطَاعَ أَنْ لاَ يُحَالَ بَيْنَهُ وَبَيْنَ الْجَنَّةِ بِمِلْءِ كَفِّهِ مِنْ دَمٍ أَهْرَاقَهُ فَلْيَفْعَلْ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7152) عن إسحاق الواسطي، حدثنا خالد، عن الجريري، عن طريف أبي تميمة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أجرة العمال","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7152).","chapter_en":"What Has Been Reported Concerning the Wages of Appointed Workers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":38,"content":{"translation":{"en":["Tarif Abu Tamimah said: I was present with Safwan, Jundab, and his companions while he was advising them. They said: “Did you hear anything from the Messenger of Allah ﷺ?” He said: I heard him say: “Whoever acts so that people hear of him, Allah will make him heard of on the Day of Resurrection.” He said: “Whoever makes things difficult, Allah will make things difficult for him on the Day of Resurrection.” They said: “Advise us.” He said: “The first thing of a person to decay is his belly, so whoever is able not to eat except what is pure, let him do so. And whoever is able not to have between himself and Paradise even a handful of blood that he has shed, let him do so.”"]},"buhuth":{"en":["The phrase “Whoever makes things difficult, Allah will make things difficult for him” may refer to hardship and harm by rulers burdening people with what is difficult for them. It may also refer to dissension, meaning opposition and separating from the community."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7152)."},{"num":7712,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ قَيْسَ بْنَ سَعْدٍ، كَانَ يَكُونُ بَيْنَ يَدَىِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَنْزِلَةِ صَاحِبِ الشُّرَطِ مِنَ الأَمِيرِ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7155) عن محمد بن خالد الذهلي، حدثنا الأنصاري محمد بن عبد الله، قال: حدثني أبي، عن ثمامة، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في اتخاذ الشُّرَط","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7155).","chapter_en":"What Has Been Reported Concerning Appointing Guards","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":39,"content":{"translation":{"en":["Anas ibn Malik narrated that Qays ibn Saʿd used to stand before the Prophet ﷺ in the position of a chief guard before a ruler."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7155)."},{"num":7713,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  صِنْفَانِ مِنْ أَهْلِ النَّارِ لَمْ أَرَهُمَا: قَوْمٌ مَعَهُمْ سِيَاطٌ كَأَذْنَابِ الْبَقَرِ يَضْرِبُونَ بِهَا النَّاسَ، وَنِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ، مُمِيلَاتٌ مَائِلَاتٌ، رُءُوسُهُنَّ كَأَسْنِمَةِ الْبُخْتِ الْمَائِلَةِ، لَا يَدْخُلْنَ الْجَنَّةَ، وَلَا يَجِدْنَ رِيحَهَا، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ كَذَا وَكَذَا."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2128: 125) عن زهير بن حرب حدثنا جرير، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ذم استعمال الشُّرَط السلطةَ للظلم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2128:125).","chapter_en":"Condemnation of Guards Using Authority for Oppression","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There are two types of the people of the Fire whom I have not seen: people with whips like the tails of cattle with which they beat the people; and women who are clothed yet naked, inclining and causing others to incline, their heads like the leaning humps of Bactrian camels. They will not enter Paradise, nor will they smell its fragrance, even though its fragrance can be found from such-and-such a distance.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15567,15847,16282],"tks":"صحيح: رواه مسلم (2128:125)."},{"num":7714,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: لَمَّا أَرَادَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكْتُبَ إِلَى الرُّومِ قَالُوا: إِنَّهُمْ لاَ يَقْرَءُونَ كِتَابًا إِلاَّ مَخْتُومًا. فَاتَّخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ فِضَّةٍ، كَأَنِّي أَنْظُرُ إِلَى وَبِيصِهِ، وَنَقْشُهُ مُحَمَّدٌ رَسُولُ اللَّهِ.","وَفِي رواية: أَرَادَ أَنْ يَكْتُبَ إِلَى كِسْرَى وَقَيْصَرَ وَالنَّجَاشِيِّ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7162)، ومسلم في اللباس والزينة (2092: 56) عن محمد بن بشار –وزاد مسلم ومحمد بن المثنى- حدثنا غندر، حدثنا شعبة قال: سمعت قتادة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ختم الرسائل والكتابات الموجَّهة إلى الملوك والأمراء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7162) and Muslim (2092:56).","chapter_en":"Sealing Letters and Writings Sent to Kings and Rulers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["Anas ibn Malik said: When the Prophet ﷺ wanted to write to the Romans, they said: “They do not read a letter unless it is sealed.” So the Prophet ﷺ took a ring of silver; it is as though I can still see its shine, and its inscription was: Muhammad, Messenger of Allah. In another narration: He wanted to write to Chosroes, Caesar, and the Negus."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7162)، ومسلم (2092:56)."},{"num":7715,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهِ عَنْهُ لَمَّا اسْتُخْلِفَ بَعَثَهُ إِلَى الْبَحْرَيْنِ، وَكَتَبَ لَهُ هَذَا الْكِتَابَ وَخَتَمَهُ بخاتم النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَكَانَ نَقْشُ الْخَاتَمِ ثَلاَثَةَ أَسْطُرٍ: مُحَمَّدٌ سَطْرٌ، وَرَسُولُ سَطْرٌ، وَاللَّهِ سَطْرٌ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3106) عن محمد بن عبد الله الأنصاري قال: حدثني أبي، عن ثمامة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ختم الرسائل والكتابات الموجَّهة إلى الملوك والأمراء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3106).","chapter_en":"Sealing Letters and Writings Sent to Kings and Rulers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["Anas narrated that when Abu Bakr became caliph, he sent him to Bahrain and wrote this document for him, sealing it with the ring of the Prophet ﷺ. The inscription of the ring was in three lines: “Muhammad” on one line, “Messenger” on one line, and “Allah” on one line."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3106)."},{"num":7716,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ يَقُولُ:  بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْثًا، وَأَمَّرَ عَلَيْهِمْ أُسَامَةَ بْنَ زَيْدٍ، فَطَعَنَ النَّاسُ فِي إِمْرَتِهِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنْ تَطْعَنُوا فِي إِمْرَتِهِ فَقَدْ كُنْتُمْ تَطْعَنُونَ فِي إِمْرَةِ أَبِيهِ مِنْ قَبْلُ، وَايْمُ اللَّهِ إِنْ كَانَ لَخَلِيقًا لِلْإِمْرَةِ، وَإِنْ كَانَ لَمِنْ أَحَبِّ النَّاسِ إِلَيَّ، وَإِنَّ هَذَا لَمِنْ أَحَبِّ النَّاسِ إِلَيَّ بَعْدَهُ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7187)، ومسلم في فضائل الصحابة (2426: 63) كلاهما من حديث عبد الله بن دينار قال: سمعت ابن عمر يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب استعمال الموالي على إمارة البلاد وقيادة الجيوش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7187) and Muslim (2426:63).","chapter_en":"Appointing Freedmen Over Governorship of Lands and Command of Armies","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ sent out an army and appointed Usamah ibn Zayd as its commander. The people criticized his command, so the Messenger of Allah ﷺ stood and said: “If you criticize his command, you used to criticize the command of his father before. By Allah, he was certainly worthy of command, and he was among the most beloved of people to me, and this one is among the most beloved of people to me after him.”"]}},"tuhfa":{},"full":1,"rep":[7845],"tks":"متفق عليه: رواه البخاري (7187)، ومسلم (2426:63)."},{"num":7717,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَخْبَرَهُ قَالَ: كَانَ سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ يَؤُمُّ الْمُهَاجِرِينَ الأَوَّلِينَ وَأَصْحَابَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِ قُبَاءٍ، فِيهِمْ: أَبُو بَكْرٍ، وَعُمَرُ، وَأَبُو سَلَمَةَ وَزَيْدٌ، وَعَامِرُ بْنُ رَبِيعَةَ.","وفي رواية: لما قدم المهاجرون الأولون العصبة -موضع بقباء- قبل مقدم رسول الله صلى الله عليه وسلم كان يؤمهم سالم مولى أبي حذيفة، وكان أكثرهم قرآنا."],"takhrij":"صحيح: رواه البخاري في الأحكام (7175) عن عثمان بن صالح، حدثنا عبدالله بن وهب، أخبرني ابن جريج أن نافعا أخبره أن ابن عمر أخبره قال: فذكره. والرواية الأخرى في الأذان (692) من طريق عبيد الله، عن نافع به.","grade":"صحيح","chapter_ar":"باب استعمال الموالي على إمارة البلاد وقيادة الجيوش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7175), and the other narration is also by al-Bukhari (692).","chapter_en":"Appointing Freedmen Over Governorship of Lands and Command of Armies","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["Ibn ʿUmar said: Salim, the freedman of Abu Hudhayfah, used to lead the first Emigrants and the companions of the Prophet ﷺ in prayer in the Mosque of Quba’. Among them were Abu Bakr, ʿUmar, Abu Salamah, Zayd, and ʿAmir ibn Rabiʿah. In another narration: When the first Emigrants arrived at al-ʿUsbah — a place in Quba’ — before the arrival of the Messenger of Allah ﷺ, Salim, the freedman of Abu Hudhayfah, used to lead them in prayer, and he knew the most Qur’an among them."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7175)، والرواية الأخرى bukhari(692)."},{"num":7718,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ وَاثِلَةَ:  أَنَّ نَافِعَ بْنَ عَبْدِ الْحَارِثِ لَقِيَ عُمَرَ بِعُسْفَانَ، - وَكَانَ عُمَرُ يَسْتَعْمِلُهُ عَلَى مَكَّةَ، - فَقَالَ: مَنِ اسْتَعْمَلْتَ عَلَى أَهْلِ الْوَادِي؟ فَقَالَ: ابْنَ أَبْزَى. قَالَ: وَمَنِ ابْنُ أَبْزَى؟ قَالَ: مَوْلًى مِنْ مَوَالِينَا. قَالَ: فَاسْتَخْلَفْتَ عَلَيْهِمْ مَوْلًى، قَالَ: إِنَّهُ قَارِئٌ لِكِتَابِ اللهِ عَزَّ وَجَلَّ، وَإِنَّهُ عَالِمٌ بِالْفَرَائِضِ. قَالَ عُمَرُ: أَمَا إِنَّ نَبِيَّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قَالَ: إِنَّ اللَّهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَامًا وَيَضَعُ بِهِ آخَرِينَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (817: 269) عن زهير بن حرب، حدثنا يعقوب بن إبراهيم، حدثني أبي، عن ابن شهاب، عن عامر بن واثلة فذكره.","grade":"صحيح","chapter_ar":"باب استعمال الموالي على إمارة البلاد وقيادة الجيوش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (817:269).","chapter_en":"Appointing Freedmen Over Governorship of Lands and Command of Armies","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["ʿAmir ibn Wathilah narrated that Nafiʿ ibn ʿAbd al-Harith met ʿUmar at ʿUsfan, and ʿUmar had appointed him over Mecca. He said: “Whom have you appointed over the people of the valley?” He said: “Ibn Abza.” He said: “Who is Ibn Abza?” He said: “A freedman of ours.” He said: “You appointed a freedman over them?!” He said: “He is a reciter of the Book of Allah, Mighty and Majestic, and he is knowledgeable of the inheritance laws.” ʿUmar said: “Indeed, your Prophet ﷺ said: ‘Allah raises some people by this Book and lowers others by it.’”"]}},"tuhfa":{},"full":1,"rep":[11838],"tks":"صحيح: رواه مسلم (817:269)."},{"num":7719,"demo":false,"sanad":"","matn":["عن مَرْوَانَ بن الْحَكَمِ والمسور بن مَخْرَمَةَ: أَخْبَرَاهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ حِينَ أَذِنَ لَهُمُ الْمُسْلِمُونَ فِي عِتْقِ سَبْىِ هَوَازِنَ: إِنِّي لاَ أَدْرِي مَنْ أَذِنَ مِنْكُمْ مِمَّنْ لَمْ يَأْذَنْ، فَارْجِعُوا حَتَّى يَرْفَعَ إِلَيْنَا عُرَفَاؤُكُمْ أَمْرَكُمْ. فَرَجَعَ النَّاسُ فَكَلَّمَهُمْ عُرَفَاؤُهُمْ، فَرَجَعُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرُوهُ أَنَّ النَّاسَ قَدْ طَيَّبُوا وَأَذِنُوا."],"takhrij":"صحيح: رواه البخاري في الأحكام (7176-7177) عن إسماعيل بن أبي أويس، حدثني إسماعيل بن إبراهيم، عن عمه موسى بن عقبة قال ابن شهاب حدثني عروة بن الزبير أن مروان بن الحكم والمسور بن مخرمة أخبراه فذكراه.","grade":"صحيح","chapter_ar":"باب اتخاذ العرفاء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7176–7177).","chapter_en":"Appointing Representatives","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Marwan ibn al-Hakam and al-Miswar ibn Makhramah narrated that when the Muslims gave permission to free the captives of Hawazin, the Messenger of Allah ﷺ said: “I do not know who among you has given permission and who has not. So return until your representatives bring your matter to us.” The people returned, and their representatives spoke to them. Then they returned to the Messenger of Allah ﷺ and informed him that the people had willingly agreed and given permission."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7176-7177)."},{"num":7720,"demo":false,"sanad":"","matn":["عن زَيْدِ بن ثَابِتٍ- قَالَ: قَالَ زَيْدُ بْنُ ثَابِتٍ أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَعَلَّمْتُ لَهُ كِتَابَ يَهُودَ وَقَالَ: إِنِّي وَاللَّهِ مَا آمَنُ يَهُودَ عَلَى كِتَابِي. فَتَعَلَّمْتُهُ فَلَمْ يَمُرَّ بِي إِلاَّ نِصْفُ شَهْرٍ حَتَّى حَذَقْتُهُ، فَكُنْتُ أَكْتُبُ لَهُ إِذَا كَتَبَ، وَأَقْرَأُ لَهُ إِذَا كُتِبَ إِلَيْهِ."],"takhrij":"حسن: رواه أبو داود (3645) -واللفظ له-، والترمذي (2715) وأحمد (21618) من طريق عبد الرحمن بن أبى الزناد، عن أبيه، عن خارجة بن زيد بن ثابت، عن زيد بن ثابت قال: فذكره. وعلقه البخاري في الأحكام (7195) عن خارجة بن زيد به مختصرا.","grade":"حسن","chapter_ar":"باب اتخاذ الإمام مترجمًا أمينًا","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3645), with his wording; al-Tirmidhi (2715); and Ahmad (21618). Al-Bukhari cited it in suspended form in the Book of Judgments (7195), from Kharijah ibn Zayd, in abridged form. Al-Tirmidhi said: It is a good authentic hadith.","chapter_en":"The Leader Taking a Trustworthy Translator","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":44,"content":{"translation":{"en":["Zayd ibn Thabit said: The Messenger of Allah ﷺ commanded me, so I learned for him the writing of the Jews. He said: “By Allah, I do not trust the Jews with my writing.” So I learned it, and only half a month passed before I mastered it. I used to write for him when he wrote, and read to him when something was written to him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3645) — واللفظ له —، والترمذي (2715)، وأحمد (21618)، وعلقه البخاري (7195) عن خارجة بن زيد به مختصرا. وقال الترمذي: حديث حسن صحيح."},{"num":7721,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ، قَالَ: بَعَثَ إِلَىَّ أَبُو بَكْرٍ لِمَقْتَلِ أَهْلِ الْيَمَامَةِ، وَعِنْدَهُ عُمَرُ، فَقَالَ أَبُو بَكْرٍ: إِنَّ عُمَرَ أَتَانِي فَقَالَ: إِنَّ الْقَتْلَ قَدِ اسْتَحَرَّ يَوْمَ الْيَمَامَةِ بِقُرَّاءِ الْقُرْآنِ، وَإِنِّي أَخْشَى أَنْ يَسْتَحِرَّ الْقَتْلُ بِقُرَّاءِ الْقُرْآنِ فِي الْمَوَاطِنِ كُلِّهَا، فَيَذْهَبَ قُرْآنٌ كَثِيرٌ، وَإِنِّي أَرَى أَنْ تَأْمُرَ بِجَمْعِ الْقُرْآنِ. قُلْتُ: كَيْفَ أَفْعَلُ شَيْئًا لَمْ يَفْعَلْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ عُمَرُ: هُوَ وَاللَّهِ خَيْرٌ. فَلَمْ يَزَلْ عُمَرُ يُرَاجِعُنِي فِي ذَلِكَ حَتَّى شَرَحَ اللَّهُ صَدْرِي لِلَّذِي شَرَحَ لَهُ صَدْرَ عُمَرَ، وَرَأَيْتُ فِي ذَلِكَ الَّذِي رَأَى عُمَرُ.","قَالَ زَيْدٌ: قَالَ أَبُو بَكْرٍ: وَإِنَّكَ رَجُلٌ شَابٌّ عَاقِلٌ لاَ نَتَّهِمُكَ، قَدْ كُنْتَ تَكْتُبُ الْوَحْىَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم، فَتَتَبَّعِ الْقُرْآنَ فَاجْمَعْهُ. قَالَ زَيْدٌ: فَوَاللَّهِ لَوْ كَلَّفَنِي نَقْلَ جَبَلٍ مِنَ الْجِبَالِ مَا كَانَ بِأَثْقَلَ عَلَىَّ مِمَّا كَلَّفَنِي مِنْ جَمْعِ الْقُرْآنِ. قُلْتُ: كَيْفَ تَفْعَلاَنِ شَيْئًا لَمْ يَفْعَلْهُ رَسُولُ اللَّهِ صلى الله عليه وسلم؟ قَالَ أبوبكر: هُوَ وَاللَّهِ خَيْرٌ فَلَمْ يَزَلْ يَحُثُّ مُرَاجَعَتِي حَتَّى شَرَحَ اللَّهُ صَدْرِي لِلَّذِي شَرَحَ اللَّهُ لَهُ صَدْرَ أَبِي بَكْرٍ وَعُمَرَ، وَرَأَيْتُ فِي ذَلِكَ الَّذِي رَأَيَا، فَتَتَبَّعْتُ الْقُرْآنَ أَجْمَعُهُ مِنَ الْعُسُبِ وَالرِّقَاعِ وَاللِّخَافِ وَصُدُورِ الرِّجَالِ، فَوَجَدْتُ في آخِرَ سُورَةِ التَّوْبَةِ ﴿لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ﴾ [التوبة: 128] إِلَى آخِرِهَا مَعَ خُزَيْمَةَ أَوْ أَبِي خُزَيْمَةَ، فَأَلْحَقْتُهَا فِي سُورَتِهَا وَكَانَتِ الصُّحُفُ عِنْدَ أَبِي بَكْرٍ حَيَاتَهُ حَتَّى تَوَفَّاهُ اللَّهُ عَزَّ وَجَلَّ، ثُمَّ عِنْدَ عُمَرَ حَيَاتَهُ حَتَّى تَوَفَّاهُ اللَّهُ، ثُمَّ عِنْدَ حَفْصَةَ بِنْتِ عُمَرَ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7191) عن محمد بن عبيد الله أبي ثابت، حدثنا إبراهيم بن سعد، عن ابن شهاب، عن عبيد بن السباق، عن زيد بن ثابت فذكره.","grade":"صحيح","chapter_ar":"باب الإمام يتخذ كاتبًا أمينًا عاقلًا","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7191).","chapter_en":"The Leader Taking a Trustworthy and Intelligent Scribe","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":45,"content":{"translation":{"en":["Zayd ibn Thabit said: Abu Bakr sent for me after the killing of the people of al-Yamamah, and ʿUmar was with him. Abu Bakr said: “ʿUmar came to me and said: ‘The killing was severe among the reciters of the Qur’an on the day of al-Yamamah, and I fear that killing may become severe among the reciters of the Qur’an in all places, causing much of the Qur’an to be lost. I think you should order the collection of the Qur’an.’” I said: “How can I do something the Messenger of Allah ﷺ did not do?” ʿUmar said: “By Allah, it is good.” ʿUmar continued to discuss it with me until Allah opened my chest to what He had opened ʿUmar’s chest, and I saw in the matter what ʿUmar saw. Zayd said: Abu Bakr said: “You are a young, intelligent man whom we do not suspect. You used to write revelation for the Messenger of Allah ﷺ, so search for the Qur’an and collect it.” Zayd said: By Allah, if he had charged me with moving one of the mountains, it would not have been heavier upon me than what he charged me with regarding the collection of the Qur’an. I said: “How can you both do something that the Messenger of Allah ﷺ did not do?” Abu Bakr said: “By Allah, it is good.” Abu Bakr continued to discuss it with me until Allah opened my chest to what He had opened the chests of Abu Bakr and ʿUmar, and I saw in the matter what they saw. So I searched for the Qur’an, collecting it from palm stalks, parchments, flat stones, and the chests of men, until I found the end of the chapter of Repentance — “There has certainly come to you a Messenger from among yourselves” [Repentance: 128] to the end of it — with Khuzaymah or Abu Khuzaymah, so I placed it in its chapter. The written sheets remained with Abu Bakr during his life until Allah, Mighty and Majestic, took him in death, then with ʿUmar during his life until Allah took him in death, then with Hafsah bint ʿUmar."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7191)."},{"num":7722,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَعْمَلَ ابْنَ الأُتَبِيَّةِ عَلَى صَدَقَاتِ بَنِي سُلَيْمٍ، فَلَمَّا جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَحَاسَبَهُ قَالَ: هَذَا الَّذِي لَكُمْ، وَهَذِهِ هَدِيَّةٌ أُهْدِيَتْ لِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَهَلاَّ جَلَسْتَ فِي بَيْتِ أَبِيكَ وَبَيْتِ أُمِّكَ حَتَّى تَأْتِيَكَ هَدِيَّتُكَ، إِنْ كُنْتَ صَادِقًا. ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَطَبَ النَّاسَ، وَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ: أَمَّا بَعْدُ فَإِنِّي أَسْتَعْمِلُ رِجَالاً مِنْكُمْ عَلَى أُمُورٍ مِمَّا وَلاَّنِي اللَّهُ، فَيَأْتِي أَحَدُكُمْ فَيَقُولُ: هَذَا لَكُمْ وَهَذِهِ هَدِيَّةٌ أُهْدِيَتْ لِي فَهَلاَّ جَلَسَ فِي بَيْتِ أَبِيهِ وَبَيْتِ أُمِّهِ حَتَّى تَأْتِيَهُ هَدِيَّتُهُ إِنْ كَانَ صَادِقًا، فَوَاللَّهِ لاَ يَأْخُذُ أَحَدُكُمْ مِنْهَا شَيْئًا ـ قَالَ هِشَامٌ: ـ بِغَيْرِ حَقِّهِ إِلاَّ جَاءَ اللَّهَ يَحْمِلُهُ يَوْمَ الْقِيَامَةِ، أَلاَ فَلأَعْرِفَنَّ مَا جَاءَ اللَّهَ رَجُلٌ بِبَعِيرٍ لَهُ رُغَاءٌ، أَوْ بِبَقَرَةٍ لَهَا خُوَارٌ، أَوْ شَاةٍ تَيْعَرُ. ثُمَّ رَفَعَ يَدَيْهِ حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ أَلاَ هَلْ بَلَّغْتُ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7197)، ومسلم في الإمارة (1832: 27) كلاهما من طريق هشام بن عروة عن أبيه عن أبي حميد الساعدي فذكره.","grade":"متفق عليه","chapter_ar":"باب محاسبة الإمام عماله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7197) and Muslim (1832:27).","chapter_en":"The Leader Holding His Workers Accountable","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":46,"content":{"translation":{"en":["Abu Humayd al-Saʿidi narrated that the Prophet ﷺ appointed Ibn al-Lutbiyyah over the charities of Banu Sulaym. When he came to the Messenger of Allah ﷺ and the Prophet held him accountable, he said: “This is what belongs to you, and this is a gift that was given to me.” The Messenger of Allah ﷺ said: “Why did you not sit in the house of your father and the house of your mother until your gift came to you, if you are truthful?” Then the Messenger of Allah ﷺ stood and addressed the people, praised Allah and extolled Him, then said: “As for what follows: I appoint men among you over matters that Allah has entrusted to me, and one of you comes and says: ‘This is for you, and this is a gift given to me.’ Why did he not sit in the house of his father and the house of his mother until his gift came to him, if he is truthful? By Allah, none of you takes anything from it — Hisham said: without its right — except that he will come carrying it on the Day of Resurrection. Let me not recognize any man coming to Allah with a camel that grunts, or a cow that moos, or a sheep that bleats.” Then he raised his hands until I saw the whiteness of his armpits and said: “Have I conveyed?”"]},"buhuth":{"en":["Ibn al-Lutbiyyah is ʿAbdullah ibn al-Lutbiyyah al-Azdi. In the two Sahih collections it appears as Ibn al-Utbiyyah, with a hamzah; the correct form is Ibn al-Lutbiyyah, with the letter “l,” as it appears in the Musnad of Imam Ahmad (23598). Al-Lutbiyyah is an attribution to Banu Lutb, a known tribe from al-Azd."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7197)، ومسلم (1832:27)."},{"num":7723,"demo":false,"sanad":"","matn":["عن عبـد اللَّهِ بن مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: يَا رَسُولَ اللَّهِ أَىُّ الْعَمَلِ أَفْضَلُ؟ قَالَ: الصَّلاَةُ عَلَى مِيقَاتِهَا. قُلْتُ: ثُمَّ أَىٌّ. قَالَ: ثُمَّ بِرُّ الْوَالِدَيْنِ. قُلْتُ: ثُمَّ أَىٌّ؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللَّهِ. فَسَكَتُّ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَوِ اسْتَزَدْتُهُ لَزَادَنِي."],"takhrij":"متفق عليه: رواه البخاريّ في الجهاد (2782)، ومسلم في الإيمان (85: 138) كلاهما من طريق الوليد بن العيزار، عن أبي عمرو الشيباني قال عبدالله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2782) and Muslim (85:138).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: I asked the Messenger of Allah ﷺ, saying: “O Messenger of Allah, which deed is best?” He said: “Prayer at its appointed time.” I said: “Then which?” He said: “Then dutifulness to parents.” I said: “Then which?” He said: “Striving in the path of Allah.” Then I remained silent before the Messenger of Allah ﷺ, and if I had asked him for more, he would have given me more."]},"intro":{"ar":["قال الله تعالى:","(إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّةَ ۚ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّا فِي التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ ۚ وَمَنْ أَوْفَىٰ بِعَهْدِهِ مِنَ اللَّهِ ۚ فَاسْتَبْشِرُوا بِبَيْعِكُمُ الَّذِي بَايَعْتُم بِهِ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ۝ التَّائِبُونَ الْعَابِدُونَ الْحَامِدُونَ السَّائِحُونَ الرَّاكِعُونَ السَّاجِدُونَ الْآمِرُونَ بِالْمَعْرُوفِ وَالنَّاهُونَ عَنِ الْمُنكَرِ وَالْحَافِظُونَ لِحُدُودِ اللَّهِ ۗ وَبَشِّرِ الْمُؤْمِنِينَ) [التوبة: ١١١-١١٢]","وقال تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا هَلْ أَدُلُّكُمْ عَلَىٰ تِجَارَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ ۝ تُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ وَتُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِكُمْ وَأَنفُسِكُمْ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ ۝ يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ وَمَسَاكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ ۚ ذَٰلِكَ الْفَوْزُ الْعَظِيمُ) [الصف: ١٠-١٢]","شُرِعَ الجهاد لسببين:","أحدهما: للدفاع عن النفس، قال الله تعالى: (أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا وَإِنَّ اللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ) [الحج: ٣٩].","والثاني: لوقاية دولة الإسلام من دولة قوية مجاورة لها، كما كانت غزوة الروم والفرس.","وأما للاستعمار فلم يحصل هذا في تاريخ الإسلام، بخلاف الدول الأوربية التي استعمرت الدول الإسلامية وغير الإسلامية في أنحاء العالم.","مما لا خلاف فيه بين أهل السنة والجماعة أن الجهاد لا يجب إلا إذا دعا إليه وليّ أمر المسلمين ورئيسهم؛ فإن إقامة فرض الجهاد من حق الإمام؛ لأنه أدرى بمصلحة البلاد والعباد، مثل إقامة الحدود الشرعية لإقامة العدل بين الناس."],"en":["Allah Most High said:","“Indeed, Allah has purchased from the believers their lives and their wealth in exchange for Paradise. They fight in the path of Allah, so they kill and are killed. It is a true promise binding upon Him in the Torah, the Gospel, and the Qur’an. And who is more faithful to his covenant than Allah? So rejoice in the bargain you have made with Him; that is the great triumph. They are those who repent, worship, praise, journey, bow, prostrate, command what is right, forbid what is wrong, and preserve the limits set by Allah. So give glad tidings to the believers.” [Repentance: 111–112]","And He said:","“O you who believe, shall I direct you to a trade that will save you from a painful punishment? You believe in Allah and His Messenger, and you strive in the path of Allah with your wealth and your lives. That is better for you, if you only knew. He will forgive you your sins and admit you into gardens beneath which rivers flow, and pleasant dwellings in gardens of everlasting residence. That is the great triumph.” [The Ranks: 10–12]","Striving in battle was prescribed for two reasons:","The first is self-defense. Allah Most High said: “Permission to fight has been given to those who are being fought because they have been wronged, and indeed Allah is fully able to give them victory.” [The Pilgrimage: 39]","The second is to protect the Islamic state from a powerful neighboring state, as occurred in the campaigns against the Romans and the Persians.","As for colonial conquest, this did not occur in the history of Islam, unlike the European states that colonized Muslim and non-Muslim lands throughout the world.","There is no disagreement among the people of the Prophetic way and the united community that striving in battle is not obligatory unless the Muslim ruler and leader calls to it. Establishing the obligation of such striving is the right of the leader, because he is most aware of the welfare of the lands and the people, just as carrying out prescribed legal punishments is for establishing justice among people."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2782)، ومسلم (85: 138)."},{"num":7724,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَىُّ الْعَمَلِ أَفْضَلُ؟ فَقَالَ: إِيمَانٌ بِاللَّهِ وَرَسُولِهِ. قِيلَ: ثُمَّ مَاذَا؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللَّهِ. قِيلَ: ثُمَّ مَاذَا؟ قَالَ: حَجٌّ مَبْرُورٌ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (26)، ومسلم في الإيمان (83) كلاهما من حديث إبراهيم بن سعد، حدثنا ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (26) and Muslim (83).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ was asked: “Which deed is best?” He said: “Faith in Allah and His Messenger.” It was said: “Then what?” He said: “Striving in the path of Allah.” It was said: “Then what?” He said: “An accepted pilgrimage.”"]}},"tuhfa":{},"full":1,"rep":[225],"tks":"متفق عليه: رواه البخاري (26)، ومسلم (83)."},{"num":7725,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَىُّ الْعَمَلِ أَفْضَلُ، قَالَ: إِيمَانٌ بِاللَّهِ، وَجِهَادٌ فِي سَبِيلِهِ."],"takhrij":"متفق عليه: رواه البخاري في العتق (2518)، ومسلم في الإيمان (136: 84) من طريق هشام بن عروة، عن أبيه، عن أبي مراوح، عن أبي ذر فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2518) and Muslim (84:136).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Dharr al-Ghifari said: I asked the Prophet ﷺ: “Which deed is best?” He said: “Faith in Allah and striving in His path.” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2518)، ومسلم (136: 84)."},{"num":7726,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَكَفَّلَ اللَّهُ لِمَنْ جَاهَدَ فِي سَبِيلِهِ، لاَ يُخْرِجُهُ إِلاَّ الْجِهَادُ فِي سَبِيلِهِ، وَتَصْدِيقُ كَلِمَاتِهِ، بِأَنْ يُدْخِلَهُ الْجَنَّةَ، أَوْ يَرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ {مَعَ مَا نَالَ} مِنْ أَجْرٍ أَوْ غَنِيمَةٍ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (2) عن أبي الزناد، عن الأعرج، عن أبي هريرة قال: فذكره. ورواه البخاري في فرض الخمس (3123) من طريق مالك به مثله. ورواه مسلم في الإمارة (1876: 104) من وجه آخر عن أبي الزناد به مثله.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (2), al-Bukhari (3123), and Muslim (1876:104).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah has guaranteed for the one who strives in His path, and nothing causes him to leave his house except striving in His path and believing His words, that He will admit him into Paradise, or return him to the dwelling from which he left with whatever reward or spoils he has gained.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (2)، والبخاري (3123)، ومسلم (1876: 104)."},{"num":7727,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  تَضَمَّنَ اللهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لَا يُخْرِجُهُ إِلَّا جِهَادًا فِي سَبِيلِي، وَإِيمَانًا بِي، وَتَصْدِيقًا بِرُسُلِي، فَهُوَ عَلَيَّ ضَامِنٌ أَنْ أُدْخِلَهُ الْجَنَّةَ، أَوْ أَرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ نَائِلًا مَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، مَا مِنْ كَلْمٍ يُكْلَمُ فِي سَبِيلِ اللَّهِ إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ كَهَيْئَتِهِ حِينَ كُلِمَ، لَوْنُهُ لَوْنُ دَمٍ، وَرِيحُهُ مِسْكٌ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْلَا أَنْ يَشُقَّ عَلَى الْمُسْلِمِينَ، مَا قَعَدْتُ خِلَافَ سَرِيَّةٍ تَغْزُو فِي سَبِيلِ اللَّهِ أَبَدًا، وَلَكِنْ لَا أَجِدُ سَعَةً فَأَحْمِلَهُمْ، وَلَا يَجِدُونَ سَعَةً، وَيَشُقُّ عَلَيْهِمْ أَنْ يَتَخَلَّفُوا عَنِّي، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوَدِدْتُ أَنِّي أَغْزُو فِي سَبِيلِ اللَّهِ فَأُقْتَلُ، ثُمَّ أَغْزُو فَأُقْتَلُ، ثُمَّ أَغْزُو فَأُقْتَلُ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (36) زمسلم في الإمارة (1876: 103) كلاهما من حديث عُمارة بن القعقاع، عن أبي زرعة بن عمرو بن جرير، عن أبي هريرة قال: فذكره. واللفظ لمسلم ، ولفظ البخاري مختصر.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (36, 2803) and Muslim (1876:103). The wording is Muslim’s.","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Allah has guaranteed for the one who goes out in His path, and nothing causes him to go out except striving in My path, faith in Me, and belief in My messengers: it is guaranteed by Me that I will admit him into Paradise, or return him to the dwelling from which he left, having attained whatever reward or spoils he has attained. By the One in whose hand is the soul of Muhammad, no wound is received in the path of Allah except that it will come on the Day of Resurrection in the same form as when it was received: its color will be the color of blood, and its scent will be musk. By the One in whose hand is the soul of Muhammad, were it not that it would be difficult for the Muslims, I would never remain behind any detachment that goes out in the path of Allah. But I do not find the means to mount them, and they do not find the means, and it is hard for them to remain behind me. By the One in whose hand is the soul of Muhammad, I would love to go out in the path of Allah and be killed, then go out and be killed, then go out and be killed.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (36، 2803)، ومسلم (1876: 103). واللفظ لمسلم."},{"num":7728,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلاَثَةٌ كُلُّهُمْ ضَامِنٌ عَلَى اللَّهِ عَزَّ وَجَلَّ: رَجُلٌ خَرَجَ غَازِيًا فِي سَبِيلِ اللَّهِ فَهُوَ ضَامِنٌ عَلَى اللَّهِ حَتَّى يَتَوَفَّاهُ، فَيُدْخِلَهُ الْجَنَّةَ، أَوْ يَرُدَّهُ بِمَا نَالَ مِنْ أَجْرٍ وَغَنِيمَةٍ، وَرَجُلٌ رَاحَ إِلَى الْمَسْجِدِ، فَهُوَ ضَامِنٌ عَلَى اللَّهِ حَتَّى يَتَوَفَّاهُ، فَيُدْخِلَهُ الْجَنَّةَ، أَوْ يَرُدَّهُ بِمَا نَالَ مِنْ أَجْرٍ وَغَنِيمَةٍ، وَرَجُلٌ دَخَلَ بَيْتَهُ بِسَلاَمٍ، فَهُوَ ضَامِنٌ عَلَى اللَّهِ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه أبو داود (2494)،والحاكم (2400) وعنه البهقي (9/166)، وصحّحه ابن حبان (499) كلهم من حديث سليمان بن حبيب، عن أبي أمامة الباهلي فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2494), al-Hakim (2400), and from him al-Bayhaqi (9/166), and graded authentic by Ibn Hibban (499).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah al-Bahili narrated that the Messenger of Allah ﷺ said: “Three are all under Allah’s guarantee, Mighty and Majestic: a man who goes out fighting in the path of Allah, so he is under Allah’s guarantee until He takes him in death and admits him into Paradise, or returns him with whatever reward and spoils he has attained; a man who goes to the mosque, so he is under Allah’s guarantee until He takes him in death and admits him into Paradise, or returns him with whatever reward and spoils he has attained; and a man who enters his house in peace, so he is under Allah’s guarantee, Mighty and Majestic.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2494)، والحاكم (2400)، وعنه البيهقي (18538)، وصححه ابن حبان (499)."},{"num":7729,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَعْنِي يَقُولُ اللَّهُ عَزَّ وَجَلَّ: الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ هُوَ عَلَىَّ ضَامِنٌ إِنْ قَبَضْتُهُ أَوْرَثْتُهُ الْجَنَّةَ، وَإِنْ رَجَعْتُهُ رَجَعْتُهُ بِأَجْرٍ أَوْ غَنِيمَةٍ."],"takhrij":"حسن: رواه الترمذي (1620) واللفظ له، وابن أبي عاصم في الجهاد (45) من طريق المعتمر بن سليمان، حدثني مرزوق أبو بكر، عن قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1620), who graded it authentic, and the wording is his; and by Ibn Abi ʿAsim in al-Jihad (45).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said — meaning that Allah, Mighty and Majestic, says: “The one who strives in My path is under My guarantee. If I take him in death, I will make him inherit Paradise; and if I return him, I will return him with reward or spoils.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1620) وصححه، واللفظ له، وابن أبي عاصم في الجهاد (45)."},{"num":7730,"demo":false,"sanad":"","matn":["عَنْ حُمَيْدٍ -يَعْنِي ابْنَ هِلَالٍ- قَالَ: كَانَ رَجُلٌ مِنْ الطُّفَاوَةِ طَرِيقُهُ عَلَيْنَا، فَأَتَى عَلَى الحَيِّ فَحَدَّثَهُمْ قَالَ: قَدِمْتُ المَدِينَةَ فِي عِيرٍ لَنَا، فَبِعْنَا بِيَاعَتَنَا، ثُمَّ قُلْتُ: لَأَنْطَلِقَنَّ إِلَى هَذَا الرَّجُلِ فَلَآتِيَنَّ مَنْ بَعْدِي بِخَبَرِهِ، قَالَ: فَانْتَهَيْتُ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِذَا هُوَ يُرِينِي بَيْتًا قَالَ: إِنَّ امْرَأَةً كَانَتْ فِيه،ِ فَخَرَجَتْ فِي سَرِيَّةٍ مِنْ المُسْلِمِين،َ وَتَرَكَتْ ثِنْتَيْ عَشْرَةَ عَنْزًا لَهَا وَصِيصِيَتَهَا كَانَتْ تَنْسِجُ بِهَا قَال:َ فَفَقَدَتْ عَنْزًا مِنْ غَنَمِهَا وَصِيصِيَتَهَا فَقَالَتْ: يَا رَبِّ إِنَّكَ قَدْ ضَمِنْتَ لِمَنْ خَرَجَ فِي سَبِيلِكَ أَنْ تَحْفَظَ عَلَيْهِ، وَإِنِّي قَدْ فَقَدْتُ عَنْزًا مِنْ غَنَمِي وَصِيصِيَتِي وَإِنِّي أَنْشُدُكَ عَنْزِي وَصِيصِيَتِي قَالَ: فَجَعَلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُ شِدَّةَ مُنَاشَدَتِهَا لِرَبِّهَا تَبَارَكَ وَتَعَالَى قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَأَصْبَحَتْ عَنْزُهَا وَمِثْلُهَا وَصِيصِيَتُهَا وَمِثْلُهَا وَهَاتِيكَ فَأْتِهَا فَاسْأَلهَا إِنْ شِئْتَ قَالَ: قُلْتُ: بَلْ أُصَدِّقُكَ."],"takhrij":"صحيح: رواه أحمد (20664) عن عبد الصمد بن عبد الوارث، حدثنا سليمان – يعني ابن المغيرة- عن حميد فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20664).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Humayd, meaning Ibn Hilal, said: A man from al-Tufawah used to pass by us. He came to the tribe and told them: I came to Medina with a caravan of ours, and we sold our merchandise. Then I said: “I will go to this man so that I may bring those after me news of him.” He said: I came to the Messenger of Allah ﷺ, and he showed me a house. He said: “A woman lived in it. She went out with a detachment of Muslims, leaving behind twelve goats of hers and a small weaving tool with which she used to weave. She lost one of her goats and her weaving tool, so she said: ‘My Lord, You have guaranteed for the one who goes out in Your path that You will preserve for him what he leaves behind. I have lost one of my goats and my weaving tool, and I ask You by Your promise for my goat and my weaving tool.’” He said: The Messenger of Allah ﷺ kept mentioning the intensity of her appeal to her Lord, Blessed and Most High. The Messenger of Allah ﷺ said: “By morning, her goat and another like it were there, and her weaving tool and another like it were there. There she is; go to her and ask her if you wish.” He said: I replied: “Rather, I believe you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20664)."},{"num":7731,"demo":false,"sanad":"","matn":["أَنَّ أَبَا هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ حَدَّثَهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: دُلَّنِي عَلَى عَمَلٍ يَعْدِلُ الْجِهَادَ. قَالَ: لاَ أَجِدُهُ، ـ قَالَ: ـ هَلْ تَسْتَطِيعُ إِذَا خَرَجَ الْمُجَاهِدُ أَنْ تَدْخُلَ مَسْجِدَكَ، فَتَقُومَ وَلاَ تَفْتُرَ، وَتَصُومَ وَلاَ تُفْطِرَ. قَالَ: وَمَنْ يَسْتَطِيعُ ذَلِكَ؟ قَالَ أَبُو هُرَيْرَةَ: إِنَّ فَرَسَ الْمُجَاهِدِ لَيَسْتَنُّ فِي طِوَلِهِ، فَيُكْتَبُ لَهُ حَسَنَاتٍ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2785) من طريق محمد بن حمادة، أخبرني أبو حصين، أن ذكوان حدثه أن أباهريرة رضي الله عنه حدثه قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2785), and Muslim (1878:110) narrated it through another route with similar wording, including: “The likeness of the one who strives in the path of Allah is one who does not cease from fasting or prayer until the one striving in the path of Allah returns.”","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: A man came to the Messenger of Allah ﷺ and said: “Direct me to a deed equal to striving in the path of Allah.” He said: “I do not find one.” He said: “When the one who strives goes out, are you able to enter your mosque, stand in prayer without stopping, and fast without breaking?” He said: “Who could do that?” Abu Hurayrah said: Even the horse of the one who strives, while moving energetically on its tether, has good deeds written for him."]},"buhuth":{"en":["The phrase “moving energetically” means moving with vigor. “Its tether” means the rope with which the animal is tied, one end being held while it is released into pasture."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2785)، ورواه مسلم (1878: 110)."},{"num":7732,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ – وَاللَّهُ أَعْلَمُ بِمَنْ يُجَاهِدُ فِي سَبِيلِهِ- كَمَثَلِ الصَّائِمِ الْقَائِمِ، وَتَوَكَّلَ اللَّهُ لِلْمُجَاهِدِ فِي سَبِيلِهِ بِأَنْ يَتَوَفَّاهُ: أَنْ يد خله الْجَنَّةَ أَوْ يَرْجِعَهُ سَالِمًا مَعَ أَجْرٍ أَوْ غَنِيمَةٍ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2787) عن أبي اليمان، أخبرنا شعيب، عن الزهري قال: أخبرني سعيد بن المسيب أن أبا هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2787).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: I heard the Messenger of Allah ﷺ say: “The likeness of the one who strives in the path of Allah — and Allah knows best who truly strives in His path — is like one who fasts and stands in prayer. Allah has guaranteed for the one who strives in His path, if He takes him in death, that He will admit him into Paradise, or return him safe with reward or spoils.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2787)."},{"num":7733,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ كَمَثَلِ الصَّائِمِ الْقَائِمِ الدَّائِمِ الَّذِي لا يَفْتُرُ مِنْ صَلاَةٍ وَلاَ صِيَامٍ حَتَّى يَرْجِعَ."],"takhrij":"صحيح: رواه مالك في الجهاد (1) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه مسلم في الإمارة (1878: 110) من وجه آخر عن أبي هريرة كما سبق.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (1) and Muslim (1878:110).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “The likeness of the one who strives in the path of Allah is like one who continually fasts and stands in prayer, never ceasing from prayer or fasting until he returns.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مالك (1)، ومسلم (1878: 110)."},{"num":7734,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  مِنْ خَيْرِ مَعَاشِ النَّاسِ لَهُمْ، رَجُلٌ مُمْسِكٌ عِنَانَ فَرَسِهِ فِي سَبِيلِ اللَّهِ، يَطِيرُ عَلَى مَتْنِهِ، كُلَّمَا سَمِعَ هَيْعَةً أَوْ فَزْعَةً طَارَ عَلَيْهِ، يَبْتَغِي الْقَتْلَ وَالْمَوْتَ مَظَانَّهُ، أَوْ رَجُلٌ فِي غُنَيْمَةٍ فِي رَأْسِ شَعَفَةٍ مِنْ هَذِهِ الشَّعَفِ، أَوْ بَطْنِ وَادٍ مِنْ هَذِهِ الْأَوْدِيَةِ، يُقِيمُ الصَّلَاةَ، وَيُؤْتِي الزَّكَاةَ، وَيَعْبُدُ رَبَّهُ حَتَّى يَأْتِيَهُ الْيَقِينُ، لَيْسَ مِنَ النَّاسِ إِلَّا فِي خَيْرٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1889: 125) عن يحيى بن يحى التميمي، حدثنا عبد العزيز بن أبي حازم، عن أبيه، عن بعجة، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1889:125).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Among the best livelihoods for people is that of a man holding the reins of his horse in the path of Allah, flying on its back whenever he hears a call of alarm or fear, seeking killing and death in their likely places; or a man among a small flock at the top of one of these mountain paths, or in the bottom of one of these valleys, establishing prayer, giving charity, and worshiping his Lord until certainty comes to him, having nothing to do with people except in good.”"]}},"tuhfa":{},"full":1,"rep":[12409],"tks":"صحيح: رواه مسلم (1889: 125)."},{"num":7735,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ أُخْبِرُكُمْ بِخَيْرِ النَّاسِ مَنْزِلاً. قُلْنَا: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: رَجُلٌ آخِذٌ بِرَأْسِ فَرَسِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ حَتَّى يَمُوتَ أَوْ يُقْتَلَ، وَأُخْبِرُكُمْ بِالَّذِي يَلِيهِ. قُلْنَا: نَعَمْ يَا رَسُولَ اللَّهِ. قَالَ: رَجُلٌ مُعْتَزِلٌ فِي شِعْبٍ يُقِيمُ الصَّلاَةَ وَيُؤْتِي الزَّكَاةَ وَيَعْتَزِلُ شُرُورَ النَّاسِ، وَأُخْبِرُكُمْ بِشَرِّ النَّاسِ. قُلْنَا: نَعَمْ يَا رَسُولَ اللَّهِ. قَالَ: الَّذِي يُسْأَلُ بِاللَّهِ عَزَّ وَجَلَّ وَلاَ يُعْطِي بِهِ."],"takhrij":"حسن: رواه النسائي (2569) عن محمد بن رافع، حدثنا ابن أبي فديك قال: أخبرنا ابن أبي ذئب، عن سعيد بن خالد القارظي، عن إسماعيل بن عبد الرحمن، عن عطاء بن يسار، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (2569).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Messenger of Allah ﷺ said: “Shall I not inform you of the person with the best station?” We said: “Yes, O Messenger of Allah.” He said: “A man holding the head of his horse in the path of Allah, Mighty and Majestic, until he dies or is killed. Shall I inform you of the one next to him?” We said: “Yes, O Messenger of Allah.” He said: “A man who withdraws into a mountain path, establishes prayer, gives charity, and avoids the evils of people. Shall I inform you of the worst of people?” We said: “Yes, O Messenger of Allah.” He said: “The one who is asked by Allah, Mighty and Majestic, and does not give.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2569)."},{"num":7736,"demo":false,"sanad":"","matn":["عن أُمِّ مُبَشِّرٍ سَأَلَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ النَّاسِ خَيْرٌ مَنْزِلَةً عِنْدَ اللَّهِ؟ فَقَالَ: رَجُلٌ عَلَى مَتْنِ فَرَسِهِ يُخِيفُ الْعَدُوَّ وَيُخِيفُونَهُ، وَرَجُلٌ يُقِيمُ الصَّلَاةَ، وَيُؤْتِي حَقَّ اللَّهِ فِي مَالِهِ، وَهُوَ فِي غَنِيمَةٍ لَهُ وَأَشَارَ بِيَدِهِ إِلَى الْحِجَازِ."],"takhrij":"صحيح: رواه ابن المبارك في الجهاد (166)، وابن راهويه في مسنده (2200)، والبيهقي في الشعب (3986-طبعة الرشد) كلهم من طريق ابن عيينة، عن عبد الله بن أبي نجيح، عن مجاهد، عن أم مبشر فذكرته. وعند البيهقي مختصر.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn al-Mubarak in al-Jihad (166), Ibn Rahwayh in his Musnad (2200), and al-Bayhaqi in Shuʿab al-Iman (3986) in abridged form.","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Umm Mubashshir said: I asked the Messenger of Allah ﷺ: “Which person has the best station with Allah?” He said: “A man on the back of his horse who frightens the enemy and whom they frighten; and a man who establishes prayer, gives Allah’s right from his wealth, and is with a small flock of his.” And he gestured with his hand toward the Hijaz."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن المبارك في الجهاد (166)، وابن راهويه في مسنده (2200)، والبيهقي في شعب الإيمان (3986) مختصرا."},{"num":7737,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا يَجْتَمِعُ كَافِرٌ وَقَاتِلُهُ فِي النَّارِ أَبَدًا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1891: 130) من طريق إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1891:130).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “An unbeliever and the one who killed him will never be gathered together in the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1891: 130)."},{"num":7738,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ مَرَّ رَجُلٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشِعْبٍ فِيهِ عُيَيْنَةٌ مِنْ مَاءٍ عَذْبَةٌ، فَأَعْجَبَتْهُ لِطِيبِهَا، فَقَالَ: لَوِ اعْتَزَلْتُ النَّاسَ فَأَقَمْتُ فِي هَذَا الشِّعْبِ وَلَنْ أَفْعَلَ حَتَّى أَسْتَأْذِنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: لاَ تَفْعَلْ؛ فَإِنَّ مَقَامَ أَحَدِكُمْ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِنْ صَلاَتِهِ فِي بَيْتِهِ سَبْعِينَ عَامًا، أَلاَ تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ، وَيُدْخِلَكُمُ الْجَنَّةَ، اغْزُوا فِي سَبِيلِ اللَّهِ، مَنْ قَاتَلَ فِي سَبِيلِ اللَّهِ فُوَاقَ نَاقَةٍ، وَجَبَتْ لَهُ الْجَنَّةُ."],"takhrij":"حسن: رواه الترمذي (1650)، وأحمد (9762، 10786)، والحاكم (2382)، والبيهقي (18503) كلهم من طرق عن هشام بن سعد، عن سعيد بن أبي هلال، عن ابن أبي ذباب، عن أبي هريرة فذكره. واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1650), who graded it good; Ahmad (9762, 10786); al-Hakim (2382), and al-Bayhaqi (9/160). The wording is al-Tirmidhi’s.","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: A man from the companions of the Messenger of Allah ﷺ passed by a mountain path in which there was a small spring of sweet water, and he admired its pleasantness. He said: “If only I withdrew from the people and stayed in this mountain path — but I will not do so until I seek permission from the Messenger of Allah ﷺ.” He mentioned that to the Messenger of Allah ﷺ, and he said: “Do not do that. For the standing of one of you in the path of Allah is better than his prayer in his house for seventy years. Do you not love that Allah should forgive you and admit you into Paradise? Go out in the path of Allah. Whoever fights in the path of Allah for the time between two milkings of a she-camel, Paradise becomes obligatory for him.”"]},"buhuth":{"en":["The expression “the time between two milkings of a she-camel” refers to the short interval between two milkings, or the time between opening and closing the hand on the udder."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1650) وحسنه، وأحمد (9762، 10786)، والحاكم (2382)، والبيهقي (18503). واللفظ للترمذي."},{"num":7739,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ مُكَاتِبًا لَهَا دَخَلَ عَلَيْهَا بِبَقِيَّةِ مُكَاتَبَتِهِ، فَقَالَتْ لَهُ: أَنْتَ غَيْرُ دَاخِلٍ عَلَيَّ غَيْرَ مَرَّتِكَ هَذِهِ، فَعَلَيْكَ بِالْجِهَادِ فِي سَبِيلِ اللَّهِ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَا خَالَطَ قَلْبَ امْرِئٍ مُسْلِمٍ رَهَجٌ فِي سَبِيلِ اللَّهِ، إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ النَّارَ."],"takhrij":"حسن: رواه أحمد (24548) عن أبي اليمان، حدثنا إسماعيل بن عياش، عن الأوزاعي، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (24548).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah narrated that a contracted slave of hers came to her with the remainder of his contract payment. She said to him: “You will not enter upon me again after this time, so you should take to striving in the path of Allah, for I heard the Messenger of Allah ﷺ say: ‘The dust of the path of Allah does not mix with the heart of a Muslim man except that Allah forbids the Fire for him.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (24548)."},{"num":7740,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ مُقَنَّعٌ بِالْحَدِيدِ، فَقَالَ: يَا رَسُولَ اللَّهِ أُقَاتِلُ وَأُسْلِمُ؟ قَالَ: أَسْلِمْ ثُمَّ قَاتِلْ، فَأَسْلَمَ، ثُمَّ قَاتَلَ، فَقُتِلَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : عَمِلَ قَلِيلاً، وَأُجِرَ كَثِيرًا ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2808)، ومسلم في الإمارة (1900: 144) كلاهما من حديث أبي إسحاق، عن البراء، فذكره واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2808) and Muslim (1900:144). The wording is al-Bukhari’s.","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Al-Bara’ said: A man covered in iron armor came to the Prophet ﷺ and said: “O Messenger of Allah, should I fight and then embrace Islam?” He said: “Embrace Islam, then fight.” So he embraced Islam, then fought and was killed. The Messenger of Allah ﷺ said: “He did little, but was greatly rewarded.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2808)، ومسلم (1900: 144). واللفظ للبخاري."},{"num":7741,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ قَالَ:  كُنْتُ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَجُلٌ: مَا أُبَالِي أَنْ لَا أَعْمَلَ عَمَلًا بَعْدَ الْإِسْلَامِ، إِلَّا أَنْ أُسْقِيَ الْحَاجَّ. وَقَالَ آخَرُ: مَا أُبَالِي أَنْ لَا أَعْمَلَ عَمَلًا بَعْدَ الْإِسْلَامِ إِلَّا أَنْ أَعْمُرَ الْمَسْجِدَ الْحَرَامَ. وَقَالَ آخَرُ: الْجِهَادُ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِمَّا قُلْتُمْ. فَزَجَرَهُمْ عُمَرُ، وَقَالَ: لَا تَرْفَعُوا أَصْوَاتَكُمْ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ يَوْمُ الْجُمُعَةِ، وَلَكِنْ إِذَا صَلَّيْتُ الْجُمُعَةَ دَخَلْتُ، فَاسْتَفْتَيْتُهُ فِيمَا اخْتَلَفْتُمْ فِيهِ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: ﴿أَجَعَلْتُمْ سِقَايَةَ الْحَاجِّ وَعِمَارَةَ الْمَسْجِدِ الْحَرَامِ كَمَنْ آمَنَ بِاللهِ وَالْيَوْمِ الآخِرِ﴾ الْآيَةَ إِلَى آخِرِهَا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1879: 111) عن حسن بن علي الحلواني، حدثنا أبو توبة، حدثنا معاوية بن سلام، عن زيد بن سلام أنه سمع أبا سلام قال: حدثني النعمان بن بشير قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1879:111).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Al-Nuʿman ibn Bashir said: I was near the pulpit of the Messenger of Allah ﷺ when a man said: “I would not mind doing no deed after Islam except giving drink to the pilgrims.” Another said: “I would not mind doing no deed after Islam except maintaining the Sacred Mosque.” Another said: “Striving in the path of Allah is better than what you have said.” ʿUmar rebuked them and said: “Do not raise your voices near the pulpit of the Messenger of Allah ﷺ, and it is Friday. But when I pray the Friday prayer, I will enter and ask him for a ruling about what you differed over.” So Allah, Mighty and Majestic, revealed: “Have you made giving drink to the pilgrims and maintaining the Sacred Mosque like one who believes in Allah and the Last Day…” [Repentance: 19], to the end of the verse."]}},"tuhfa":{},"full":1,"rep":[12436],"tks":"صحيح: رواه مسلم (1879: 111)."},{"num":7742,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، أي النَّاسِ أَفْضَلُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مُؤْمِنٌ يُجَاهِدُ فِي سَبِيلِ اللَّهِ بِنَفْسِهِ وَمَالِهِ، قَالُوا: ثُمَّ مَنْ؟ قَالَ: مُؤْمِنٌ فِي شِعْبٍ مِنَ الشِّعَابِ يَتَّقِي اللَّهَ، وَيَدَعُ النَّاسَ مِنْ شَرِّهِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (2786)، ومسلم في الإمارة (1888: 122) كلاهما من طرق عن الزهري، عن عطاء بن يزيد الليثي، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2786) and Muslim (1888:122).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: It was said: “O Messenger of Allah, which person is best?” The Messenger of Allah ﷺ said: “A believer who strives in the path of Allah with his life and wealth.” They said: “Then who?” He said: “A believer in one of the mountain paths who is mindful of Allah and leaves people safe from his harm.”"]}},"tuhfa":{},"full":1,"rep":[129],"tks":"متفق عليه: رواه البخاري (2786)، ومسلم (1888: 122)."},{"num":7743,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ آمَنَ بِاللَّهِ وَبِرَسُولِهِ وَأَقَامَ الصَّلاَةَ، وَصَامَ رَمَضَانَ، كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ، جَاهَدَ فِي سَبِيلِ اللَّهِ، أَوْ جَلَسَ فِي أَرْضِهِ الَّتِي وُلِدَ فِيهَا. فَقَالُوا يَا رَسُولَ اللَّهِ أَفَلاَ نُبَشِّرُ النَّاسَ. قَالَ إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِ اللَّهِ، مَا بَيْنَ الدَّرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، فَإِذَا سَأَلْتُمُ اللَّهَ فَاسْأَلُوهُ الْفِرْدَوْسَ، فَإِنَّهُ أَوْسَطُ الْجَنَّةِ وَأَعْلَى الْجَنَّةِ، أُرَاهُ فَوْقَهُ عَرْشُ الرَّحْمَنِ، وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2790) عن يحيى بن صالح، حدثنا فليح، عن هلال بن علي، عن عطاء بن يسار، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2790).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever believes in Allah and His Messenger, establishes prayer, and fasts Ramadan, it is a right upon Allah that He admit him into Paradise, whether he strives in the path of Allah or remains in the land in which he was born.” They said: “O Messenger of Allah, should we not give glad tidings to the people?” He said: “Indeed, in Paradise there are one hundred levels that Allah has prepared for those who strive in His path. Between two levels is like the distance between heaven and earth. So when you ask Allah, ask Him for the highest Garden; for it is the middle of Paradise and the highest of Paradise — I think he said above it is the Throne of the Most Merciful — and from it the rivers of Paradise burst forth.”"]}},"tuhfa":{},"full":1,"rep":[469,10911,12819],"tks":"صحيح: رواه البخاري (2790)."},{"num":7744,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَا أَبَا سَعِيدٍ، مَنْ رَضِيَ بِاللهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا، وَجَبَتْ لَهُ الْجَنَّةُ. فَعَجِبَ لَهَا أَبُو سَعِيدٍ فَقَالَ: أَعِدْهَا عَلَيَّ يَا رَسُولَ اللَّهِ، فَفَعَلَ، ثُمَّ قَالَ: وَأُخْرَى يُرْفَعُ بِهَا الْعَبْدُ مِائَةَ دَرَجَةٍ فِي الْجَنَّةِ، مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ. قَالَ: وَمَا هِيَ يَا رَسُولَ اللَّهِ؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللَّهِ، الْجِهَادُ فِي سَبِيلِ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1884: 116) عن سعيد بن منصور، حدثنا عبد الله بن وهب، حدثني أبو هانئ الخولاني، عن أبي عبد الرحمن الحبلي، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1884:116).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ said: “O Abu Saʿid, whoever is pleased with Allah as Lord, with Islam as religion, and with Muhammad as Prophet, Paradise becomes obligatory for him.” Abu Saʿid was amazed by it and said: “Repeat it to me, O Messenger of Allah.” So he repeated it, then said: “And there is another deed by which the servant is raised one hundred levels in Paradise, between each two levels being like the distance between heaven and earth.” He said: “What is it, O Messenger of Allah?” He said: “Striving in the path of Allah, striving in the path of Allah.”"]}},"tuhfa":{},"full":1,"rep":[16304],"tks":"صحيح: رواه مسلم (1884: 116)."},{"num":7745,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَقَامَ الصَّلاَةَ وَآتَى الزَّكَاةَ، وَمَاتَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا، كَانَ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ يَغْفِرَ لَهُ، هَاجَرَ أَوْ مَاتَ فِي مَوْلِدِهِ. فَقُلْنَا: يَا رَسُولَ اللَّهِ، أَلاَ نُخْبِرُ بِهَا النَّاسَ، فَيَسْتَبْشِرُوا بِهَا؟ فَقَالَ: إِنَّ لِلْجَنَّةِ مِائَةَ دَرَجَةٍ، بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِهِ، وَلَوْلاَ أَنْ أَشُقَّ عَلَى الْمُؤْمِنِينَ، وَلاَ أَجِدُ مَا أَحْمِلُهُمْ عَلَيْهِ، وَلاَ تَطِيبُ أَنْفُسُهُمْ أَنْ يَتَخَلَّفُوا بَعْدِي، مَا قَعَدْتُ خَلْفَ سَرِيَّةٍ، وَلَوَدِدْتُ أَنِّي أُقْتَلُ، ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ."],"takhrij":"حسن: رواه النسائي (3132) عن هارون بن محمد بن بكار بن بلال، حدثنا محمد بن عيسى بن القاسم بن سميع، حدثنا زيد بن واقد، حدثني بُسر بن عبيد الله، عن أبي إدريس الخولاني، عن أبي الدرداء فذكره.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3132).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu al-Darda’ said: The Messenger of Allah ﷺ said: “Whoever establishes prayer, gives charity, and dies without associating anything with Allah, it is a right upon Allah, Mighty and Majestic, that He forgive him, whether he emigrated or died in the place of his birth.” We said: “O Messenger of Allah, should we not inform the people of it so they may rejoice?” He said: “Indeed, Paradise has one hundred levels, between each two levels being like the distance between heaven and earth, which Allah has prepared for those who strive in His path. Were it not that I would make things difficult for the believers, and I do not find what to mount them on, and their souls would not be content to remain behind me, I would not remain behind any detachment. I would love to be killed, then brought back to life, then killed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3132)."},{"num":7746,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن أَبِي أَوْفَى، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلاَلِ السُّيُوفِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2818) ومسلم في الجهاد والسير (1742: 20) كلاهما من طريق موسى بن عقبة، عن سالم أبي النضر مولى عمر بن عبيدالله –وكان كاتبه- قال: كتب إليه عبد الله بن أبي أوفى فذكره.والسياق للبخاري، ومسلم ذكره بتمامه.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2818) and Muslim (1742:20).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn Abi Awfa narrated that the Messenger of Allah ﷺ said: “And know that Paradise is beneath the shades of swords.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2818)، ومسلم (1742: 20)."},{"num":7747,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ، عَنْ أَبِيهِ قَالَ: سَمِعْتُ أَبِي وَهُوَ بِحَضْرَةِ الْعَدُوِّ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ أَبْوَابَ الْجَنَّةِ تَحْتَ ظِلَالِ السُّيُوفِ. فَقَامَ رَجُلٌ رَثُّ الْهَيْئَةِ، فَقَالَ: يَا أَبَا مُوسَى، آنْتَ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ هَذَا؟ قَالَ: نَعَمْ، قَالَ: فَرَجَعَ إِلَى أَصْحَابِهِ، فَقَالَ: أَقْرَأُ عَلَيْكُمُ السَّلَامَ، ثُمَّ كَسَرَ جَفْنَ سَيْفِهِ، فَأَلْقَاهُ، ثُمَّ مَشَى بِسَيْفِهِ إِلَى الْعَدُوِّ، فَضَرَبَ بِهِ حَتَّى قُتِلَ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1902: 146) من طريق جعفر بن سليمان، عن أبي عمران الجوني، عن أبي بكر بن عبد الله بن قيس به فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1902:146). ʿAbdullah ibn Qays is Abu Musa al-Ashʿari.","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Bakr ibn ʿAbdullah ibn Qays narrated from his father, who said: I heard my father, while he was in the presence of the enemy, saying: The Messenger of Allah ﷺ said: “Indeed, the gates of Paradise are beneath the shades of swords.” A man of worn appearance stood and said: “O Abu Musa, did you hear the Messenger of Allah ﷺ say this?” He said: “Yes.” The man returned to his companions and said: “I convey peace to you.” Then he broke the sheath of his sword, threw it away, and walked with his sword toward the enemy, striking with it until he was killed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1902: 146). وعبد الله بن قيس هو أبو موسى الأشعري."},{"num":7748,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَقَابُ قَوْسٍ فِي الْجَنَّةِ خَيْرٌ مِمَّا تَطْلُعُ عَلَيْهِ الشَّمْسُ وَتَغْرُبُ. وَقَالَ: لَغَدْوَةٌ أَوْ رَوْحَةٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِمَّا تَطْلُعُ عَلَيْهِ الشَّمْسُ وَتَغْرُبُ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2793) من طريق عبد الرحمن بن أبي عمرة، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2793) and Muslim (1882:114).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “The space of a bow in Paradise is better than all over which the sun rises and sets.” And he said: “A morning journey or an evening journey in the path of Allah is better than all over which the sun rises and sets.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16308],"tks":"متفق عليه: رواه البخاري (2793)، ومسلم (1882: 114)."},{"num":7749,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَغَدْوَةٌ فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2792)، ومسلم في الإمارة (1880: 112) كلاهما من طريقين عن أنس قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2792) and Muslim (1880:112).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “A morning journey in the path of Allah or an evening journey is better than the world and all that is in it.”"]},"buhuth":{"en":["The phrase “a morning journey” refers to going out once at any time from the beginning of the day until midday. “An evening journey” refers to going out once at any time from the sun’s decline until sunset."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2792)، ومسلم (1880: 112)."},{"num":7750,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الرَّوْحَةُ وَالْغَدْوَةُ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِنَ الدُّنْيَا وَمَا فِيهَا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2794)، ومسلم في الإمارة (1881: 114) كلاهما من طريق سفيان (هو الثوري)، عن أبي حازم، عن سهل بن سعد فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2794) and Muslim (1881:114).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Prophet ﷺ said: “An evening journey and a morning journey in the path of Allah are better than the world and all that is in it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2794)، ومسلم (1881: 114)."},{"num":7751,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ قَالَ: قَالَ رَسُولُ اللَّهِ: غَدْوَةٌ فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ وَغَرَبَتْ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1883: 115) من طريق عبد الله بن يزيد المقرئ، عن سعيد بن أبي أيوب، حدثني شُرحبيل بن شريك المعافري، عن أبي عبد الرحمن الحبلي، قال: سمعت أبا أيوب يقول: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1883:115).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Ayyub said: The Messenger of Allah ﷺ said: “A morning journey in the path of Allah or an evening journey is better than everything over which the sun rises and sets.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1883: 115)."},{"num":7752,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عبيد يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَنَا زَعِيمٌ - وَالزَّعِيمُ الْحَمِيلُ - لِمَنْ آمَنَ بِي وَأَسْلَمَ وَهَاجَرَ بِبَيْتٍ فِي رَبَضِ الْجَنَّةِ، وَبِبَيْتٍ فِي وَسَطِ الْجَنَّةِ. وَأَنَا زَعِيمٌ لِمَنْ آمَنَ بِي وَأَسْلَمَ وَجَاهَدَ فِي سَبِيلِ اللَّهِ بِبَيْتٍ فِي رَبَضِ الْجَنَّةِ، وَبِبَيْتٍ فِي وَسَطِ الْجَنَّةِ. وَبِبَيْتٍ فِي أَعْلَى غُرَفِ الْجَنَّةِ، مَنْ فَعَلَ ذَلِكَ، فَلَمْ يَدَعْ لِلْخَيْرِ مَطْلَبًا، وَلاَ مِنَ الشَّرِّ مَهْرَبًا، يَمُوتُ حَيْثُ شَاءَ أَنْ يَمُوتَ."],"takhrij":"حسن: رواه النسائي (3135)، وصحّحه ابن حبان (4619)، والحاكم (2391) من طرق عن ابن وهب، أخبرني أبو هانئ الخولاني، عن عمرو بن مالك الجنبي أنه سمع فضالة بن عبيد فذكره.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (3135), and authenticated by Ibn Ḥibbān (4619) and al-Ḥākim (2391).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd reported: I heard the Messenger of Allah ﷺ say: “I am a guarantor—and a guarantor is one who undertakes responsibility—for whoever believes in me, submits to Islam, and emigrates: a house on the outskirts of Paradise and a house in the middle of Paradise. And I am a guarantor for whoever believes in me, submits to Islam, and strives in the path of Allah: a house on the outskirts of Paradise, a house in the middle of Paradise, and a house in the highest chambers of Paradise. Whoever does that has left no good that remains to be sought and no evil from which there remains any escape to seek. Let him die wherever he wishes to die.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3135)، وصححه ابن حبان (4619)، والحاكم (2391)."},{"num":7753,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ حُبْشِيٍّ الْخَثْعَمِيِّ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، سُئِلَ أَيُّ الْأَعْمَالِ أَفْضَلُ؟ قَالَ: إِيمَانٌ لَا شَكَّ فِيهِ، وَجِهَادٌ لَا غُلُولَ فِيهِ، وَحَجَّةٌ مَبْرُورَةٌ، قِيلَ: فَأَيُّ الصَّلَاةِ أَفْضَلُ؟ قَالَ: طُولُ الْقُنُوتِ. قِيلَ: فَأَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: جَهْدُ الْمُقِلِّ. قِيلَ: فَأَيُّ الْهِجْرَةِ أَفْضَلُ؟ قَالَ: مَنْ هَجَرَ مَا حَرَّمَ اللَّهُ عَلَيْهِ. قِيلَ: فَأَيُّ الْجِهَادِ أَفْضَلُ؟ قَالَ: مَنْ جَاهَدَ الْمُشْرِكِينَ بِمَالِهِ، وَنَفْسِهِ. قِيلَ: فَأَيُّ الْقَتْلِ أَشْرَفُ؟ قَالَ: مَنْ أُهَرِيقَ دَمُهُ، وَعُقِرَ جَوَادُهُ."],"takhrij":"حسن: رواه أحمد ( 15401)، واللفظ له، وعنه أبو داود (1449)، والنسائي (2526) كلهم من حديث حجاج ( هو ابن محمد المصيصي) قال: قال ابن جريج: حدثني عثمان بن أبي سليمان، عن علي الأزدي، عن عبيد بن عمير، عن عبد الله بن حُبشي فذكره.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (15401), and the wording is his; and through him by Abu Dawud (1449) and al-Nasa’i (2526).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn Hubshi al-Khathʿami narrated that the Prophet ﷺ was asked: “Which deeds are best?” He said: “Faith with no doubt in it, striving with no misappropriation in it, and an accepted pilgrimage.” It was said: “Which prayer is best?” He said: “Long standing.” It was said: “Which charity is best?” He said: “The effort of one who has little.” It was said: “Which emigration is best?” He said: “One who abandons what Allah has forbidden him.” It was said: “Which striving is best?” He said: “One who strives against the idolaters with his wealth and his life.” It was said: “Which killing is most noble?” He said: “One whose blood is spilled and whose horse is hamstrung.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15401)، واللفظ له، وعنه أبو داود (1449)، والنسائي (2526)."},{"num":7754,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، أَيُّ الْجِهَادِ أَفْضَلُ؟. قَالَ: مَنْ عُقِرَ جَوَادُهُ، وَأُهْرِيقَ دَمُهُ."],"takhrij":"صحيح: رواه أحمد (4210)، والدارمي (2437) وصحّحه ابن حبان (4639) كلهم من طريق الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (4210) and al-Darimi (2437), and graded authentic by Ibn Hibban (4639).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Jabir said: They said: “O Messenger of Allah, which striving is best?” He said: “That of one whose horse is hamstrung and whose blood is spilled.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (4210)، والدارمي (2437)، وصححه ابن حبان (4639)."},{"num":7755,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلاَثَةٌ يُحِبُّهُمُ اللَّهُ عزوجل: رَجُلٌ أَتَى قَوْمًا فَسَأَلَهُمْ بِاللَّهِ، وَلَمْ يَسْأَلْهُمْ بِقَرَابَةٍ بَيْنَهُ وَبَيْنَهُمْ، فَمَنَعُوهُ فتخلفهم رجلٌ بِأَعْقَابِهِمْ فَأَعْطَاهُ سِرًّا، لاَ يَعْلَمُ بِعَطِيَّتِهِ إِلاَّ اللَّهُ عزوجل، وَالَّذِي أَعْطَاهُ. وَقَوْمٌ سَارُوا لَيْلَتَهُمْ، حَتَّى إِذَا كَانَ النَّوْمُ أَحَبَّ إِلَيْهِمْ مِمَّا يُعْدَلُ بِهِ نَزَلُوا فَوَضَعُوا رؤوسهم، فَقَامَ يَتَمَلَّقُنِي، وَيَتْلُو آيَاتِي. وَرَجُلٌ كَانَ فِي سَرِيَّةٍ فلقوا الْعَدُوَّ، فانهزموا، فأقبل بِصَدْرِهِ حَتَّى يُقْتَلَ، أَوْ يُفْتَحَ لَهُ."],"takhrij":"حسن: رواه النسائي (1615)، والترمذي (2568) كلاهما عن محمد بن المثنى، حدثنا محمد بن جعفر، حدثنا شعبة، عن منصور بن المعتمر قال: سمعت ربعي بن حراش، يحدث عن زيد بن ظبيان رفعه إلى أبي ذر فذكر الحديث.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (1615) and al-Tirmidhi (2568).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Dharr narrated that the Prophet ﷺ said: “There are three whom Allah, Mighty and Majestic, loves: a man who came to a people and asked them by Allah, not asking them because of kinship between him and them, but they refused him; then a man stayed behind after them and gave to him secretly, so that no one knew of his gift except Allah, Mighty and Majestic, and the one who received it. And a group who traveled through their night until sleep became dearer to them than anything equivalent to it; they stopped and laid down their heads, but one of them stood, humbly seeking My nearness and reciting My verses. And a man who was in a detachment that met the enemy, and they fled, but he turned his chest forward until he was killed or victory was granted to him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13547],"tks":"حسن: رواه النسائي (1615)، والترمذي (2568)."},{"num":7756,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَجِبَ رَبُّنَا مِنْ رَجُلٍ غَزَا فِي سَبِيلِ اللَّهِ فَانْهَزَمَ. يَعْنِي أَصْحَابَهُ: فَعَلِمَ مَا عَلَيْهِ، فَرَجَعَ حَتَّى أُهْرِيقَ دَمُهُ، فَيَقُولُ اللَّهُ تَعَالَى لِمَلاَئِكَتِهِ: انْظُرُوا إِلَى عَبْدِي، رَجَعَ رَغْبَةً فِيمَا عِنْدِي وَشَفَقَةً مِمَّا عِنْدِي حَتَّى أُهَرِيقَ دَمُهُ."],"takhrij":"صحيح: رواه أبو داود (2536)، عن موسى بن إسماعيل، حدثنا حماد، أخبرنا عطاء بن السائب، عن مرة الهمداني، عن عبد الله بن مسعود فذكر مثله.","grade":"صحيح","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2536).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The Messenger of Allah ﷺ said: “Our Lord is amazed at a man who went out in the path of Allah and whose companions fled, but he knew what was upon him, so he returned until his blood was spilled. Allah Most High says to His angels: ‘Look at My servant. He returned out of desire for what is with Me and fear of what is with Me, until his blood was spilled.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2536)."},{"num":7757,"demo":false,"sanad":"","matn":["عَنْ سَبْرَةَ بْنِ أَبِي فَاكِهٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ الشَّيْطَانَ قَعَدَ لِابْنِ آدَمَ بِأَطْرُقِهِ، فَقَعَدَ لَهُ بِطَرِيقِ الْإِسْلَامِ، فَقَالَ: تسلم، وَتَذَرُ دِينَكَ، وَدِينَ آبَائِكَ، وَآبَاءِ أَبِيكَ، فَعَصَاهُ، فَأَسْلَمَ، ثُمَّ قَعَدَ لَهُ بِطَرِيقِ الْهِجْرَةِ، فَقَالَ: تهاجر، وتدع أَرْضَكَ، وَسَمَاءَكَ، وَإِنَّمَا مَثَلُ الْمُهَاجِرِ كَمَثَلِ الْفَرَسِ فِي الطِوَل، فَعَصَاهُ فَهَاجَرَ، ثُمَّ قَعَدَ لَهُ بِطَرِيقِ الْجِهَادِ، فَقَالَ: تجاهد فهو جَهْدُ النَّفْسِ وَالْمَالِ، فَتُقَاتِلُ فَتُقْتَلُ، فَتُنْكَحُ الْمَرْأَةُ، وَيُقَسَّمُ الْمَالُ، فَعَصَاهُ فَجَاهَدَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : فَمَنْ فَعَلَ ذَلِكَ، كَانَ حَقًّا عَلَى اللَّهِ عزوجل أَنْ يُدْخِلَهُ الْجَنَّةَ، وَمَنْ قُتِلَ كَانَ حَقًّا عَلَى اللَّهِ عَزَّ وَ جَلَّ أَنْ يُدْخِلَهُ الْجَنَّةَ، وَإِنْ غَرِقَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ أَوْ وَقَصَتْهُ دابته، كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ."],"takhrij":"حسن: رواه النسائي (3134)، وأحمد (15958)، وابن أبي شيبة (19329)، وصحّحه ابن حبان (4593)، كلهم من طريق موسى بن المسيب، أخبرني سالم بن أبي الجعد، عن سبرة بن أبي فاكه فذكره.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3134), Ahmad (15958), and Ibn Abi Shaybah (5/293), and graded authentic by Ibn Hibban (4593).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Sabrah ibn Abi Fakih said: I heard the Messenger of Allah ﷺ say: “Satan sits for the son of Adam on his paths. He sits for him on the path of submission and says: ‘Will you submit and leave your religion, the religion of your fathers, and the fathers of your father?’ But he disobeys him and submits. Then he sits for him on the path of emigration and says: ‘Will you emigrate and leave your land and your sky?’ The likeness of the emigrant is like a horse on a tether. But he disobeys him and emigrates. Then he sits for him on the path of striving and says: ‘Will you strive? It is the exertion of life and wealth. You will fight and be killed, then the woman will be married and the wealth divided.’ But he disobeys him and strives.” The Messenger of Allah ﷺ then said: “Whoever does that, it is a right upon Allah, Mighty and Majestic, to admit him into Paradise. Whoever is killed, it is a right upon Allah, Mighty and Majestic, to admit him into Paradise. If he drowns, it is a right upon Allah to admit him into Paradise; or if his riding animal throws him and kills him, it is a right upon Allah to admit him into Paradise.”"]},"buhuth":{"en":["The word “tether” means a rope whose one end is tied to a peg and whose other end is with the horse."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3134)، وأحمد (15958)، وابن أبي شيبة (19329)، وصححه ابن حبان (4593)."},{"num":7758,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أَمَرَ رَسُولُ اللَّهِ بسريّةٍ أَنْ تَخْرُجُ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أ نخرج اللَّيْلَةَ أَمْ نَمْكُثُ حَتَّى نُصْبِحَ؟ قَالَ: أ فلا تُحِبُّونَ أَنْ تَبِيتُوا هَكَذَا فِي خِرَافٍ الْجَنَّةِ؟."],"takhrij":"حسن: رواه النسائي في الكبرى (8783)، والحاكم (2/74)، والبيهقي في الشعب (3934) كلهم من طرقٍ عن ابن وهب، عن ابن لهيعة وعمر بن مالك، عن ابن أبي جعفر، عن صفوان بن سُليم، عن سليمان الأغرّ، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل الجهاد في سبيل الله إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (8783), al-Hakim (2401), and al-Bayhaqi in al-Shuʿab (3934).","chapter_en":"The Virtue of Striving in the Path of Allah When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ ordered a detachment to go out. They said: “O Messenger of Allah, should we go out tonight or remain until morning?” He said: “Do you not love to spend the night like this among the gardens of Paradise?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في الكبرى (8783)، والحاكم (2401)، والبيهقي في الشعب (3934)."},{"num":7759,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَبْسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا اغْبَرْتُ قَدَمًا عَبْدٌ فِي سَبِيلِ اللَّهِ فَتَمَسُّهُ النَّارُ."],"takhrij":"صحيح: رواه البخاري في الجهاد (2811)، عن إسحاق، أخبرنا محمد بن المبارك، حدثنا يحيى بن حمزة، حدثني يزيد بن أبي مريم، أخبرنا عباية بن رافع بن خديج، أخبرني أبو عبس –وهو عبد الرحمن بن حبر- قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل من اغبرت قدماه في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2811).","chapter_en":"The Virtue of the One Whose Feet Become Dusty in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu ʿAbs narrated that the Messenger of Allah ﷺ said: “The feet of a servant do not become dusty in the path of Allah and then the Fire touch him.”"]},"intro":{"ar":["قال الله تعالى:","(مَا كَانَ لِأَهْلِ الْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ الْأَعْرَابِ أَن يَتَخَلَّفُوا عَن رَّسُولِ اللَّهِ وَلَا يَرْغَبُوا بِأَنفُسِهِمْ عَن نَّفْسِهِ ۚ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِي سَبِيلِ اللَّهِ وَلَا يَطَئُونَ مَوْطِئًا يَغِيظُ الْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِ عَمَلٌ صَالِحٌ ۚ إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ) [التوبة: ١٢٠]"],"en":["Allah Most High said:","“It was not for the people of Medina and those around them of the desert Arabs to remain behind the Messenger of Allah, nor to prefer themselves over himself. That is because no thirst, fatigue, or hunger afflicts them in the path of Allah, nor do they tread any place that enrages the unbelievers, nor do they gain anything from an enemy, except that a righteous deed is written for them because of it. Indeed, Allah does not allow the reward of those who do good to be lost.” [Repentance: 120]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2811)."},{"num":7760,"demo":false,"sanad":"","matn":["عن أبي مصبِّح المقرائي قال: غزونا مع مالك بن عبد الله الخثعمي أرض الروم، فسبق رجل الناس، ثم نزل يمشي ويقود دابته، فقال مالك: يا أبا عبد الله ألا تركب؟ فقال: سمعت رسول الله صلى الله عليه وسلم يقول: من اغبرت قدماه في سبيل الله ساعة من نهار، فهما حرام على النار وأصلح دابتي لتغنيني عن قومي، قال أبو مصبح: فنزل الناس فلم أر نازلا قط أكثر من يومئذ."],"takhrij":"صحيح: رواه عبد الله بن المبارك في الجهاد (33) -والسياق له-، وأحمد (21962) من طريق عبدالرحمن بن يزيد بن جابر قال: حدثني أبو مصبح فذكره.","grade":"صحيح","chapter_ar":"باب فضل من اغبرت قدماه في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbdullah ibn al-Mubarak in al-Jihad (33), and the wording is his; and by Ahmad (21962).","chapter_en":"The Virtue of the One Whose Feet Become Dusty in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Misbah al-Maqra’i said: We went on campaign with Malik ibn ʿAbdullah al-Khathʿami in the land of the Romans. A man went ahead of the people, then dismounted and walked while leading his riding animal. Malik said: “O Abu ʿAbdullah, will you not ride?” He said: “I heard the Messenger of Allah ﷺ say: ‘Whoever’s feet become dusty in the path of Allah for an hour of the day, they are forbidden to the Fire.’ And I keep my riding animal in good condition so that it may suffice me from needing my people.” Abu Misbah said: The people then dismounted, and I never saw more people dismounting than on that day."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد الله بن المبارك في الجهاد (33) — والسياق له — وأحمد (21962)."},{"num":7761,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَلِجُ النَّارَ أَحَدٌ بَكَى مِنْ خَشْيَةِ اللَّهِ، حَتَّى يَعُودَ اللَّبَنُ فِي الضَّرْعِ، وَلَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ، وَدُخَانُ جَهَنَّمَ فِي مَنْخِرَيْ امْرِئٍ أَبَدًا."],"takhrij":"صحيح: رواه أحمد (10560) – واللفظ له- عن يزيد (هو ابن هارون) وأبي عبدالرحمن المقرئ- والترمذي (1633)، والنسائي (3108) من طريق ابن المبارك- والحاكم (7667) من طريق جعفر بن عون- كلهم عن عبد الرحمن بن عبد الله المسعودي، عن محمد بن عبد الرحمن مولى آل طلحة، عن عيسى بن طلحة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل من اغبرت قدماه في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (10560), and the wording is his; al-Tirmidhi (1633), who graded it authentic; al-Nasa’i (3108), and al-Hakim (7667).","chapter_en":"The Virtue of the One Whose Feet Become Dusty in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “No one who weeps out of fear of Allah, Mighty and Majestic, will enter the Fire until milk returns to the udder; and dust in the path of Allah and the smoke of Hell will never gather in a person’s nostrils.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15107],"tks":"صحيح: رواه أحمد (10560) — واللفظ له — والترمذي (1633) وصححه، والنسائي (3108)، والحاكم (7667)."},{"num":7762,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَا مِنْ غَازِيَةٍ تَغْزُو فِي سَبِيلِ اللَّهِ فَيُصِيبُونَ الْغَنِيمَةَ، إِلَّا تَعَجَّلُوا ثُلُثَيْ أَجْرِهِمْ مِنَ الْآخِرَةِ، وَيَبْقَى لَهُمُ الثُّلُثُ، وَإِنْ لَمْ يُصِيبُوا غَنِيمَةً تَمَّ لَهُمْ أَجْرُهُمْ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1906: 153) عن عبد بن حُميد، حدثنا عبد الله بن يزيد أبو عبد الرحمن، حدثنا حيوة بن شريح، عن أبي هانئ، عن أبي عبد الرحمن الحبلّي، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب من غزا بنيّة الغنيمة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1906:153).","chapter_en":"One Who Goes Out Intending to Obtain Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated that the Messenger of Allah ﷺ said: “No fighting group goes out in the path of Allah and gains spoils except that they have hastened two-thirds of their reward from the Hereafter, and one-third remains for them. But if they do not gain spoils, their reward is complete for them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1906: 153)."},{"num":7763,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا، وَمَوْضِعُ سَوْطِ أَحَدِكُمْ مِنَ الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا، وَالرَّوْحَةُ يَرُوحُهَا الْعَبْدُ فِي سَبِيلِ اللَّهِ أَوِ الْغَدْوَةُ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (2892) عن عبد الله بن منير، سمع أبا النضر، حدثنا عبد الرحمن بن عبد الله بن دينار، عن أبي حازم، عن سهل بن سعد الساعدي فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الرباط في سبيل الله عز وجل","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2892) and Muslim (1881:114).","chapter_en":"The Virtue of Guarding the Frontier in the Path of Allah, Mighty and Majestic","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Sahl ibn Saʿd al-Saʿidi narrated that the Messenger of Allah ﷺ said: “A day of guarding the frontier in the path of Allah is better than the world and all that is upon it. The place of one of your whips in Paradise is better than the world and all that is upon it. An evening journey that a servant makes in the path of Allah, or a morning journey, is better than the world and all that is upon it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2892)، ومسلم (1881: 114)."},{"num":7764,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: رِبَاطُ يَوْمٍ وَلَيْلَةٍ خَيْرٌ مِنْ صِيَامِ شَهْرٍ وَقِيَامِهِ، وَإِنْ مَاتَ جَرَى عَلَيْهِ عَمَلُهُ الَّذِي كَانَ يَعْمَلُهُ، وَأُجْرِيَ عَلَيْهِ رِزْقُهُ، وَأَمِنَ الْفَتَّانَ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1913: 163) عن عبد الله بن عبد الرحمن الدارمي، حدثنا أبو الوليد الطيالسي، حدثنا ليث بن سعد، عن أيوب بن موسى، عن مكحول، عن شرحبيل بن السمط، عن سلمان قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الرباط في سبيل الله عز وجل","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Leadership (1913:163).","chapter_en":"The Virtue of Guarding the Frontier in the Path of Allah, Mighty and Majestic","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Salman said: I heard the Messenger of Allah ﷺ say: “Guarding the frontier for one day and one night is better than fasting and standing in prayer for a month. If he dies, the deed he used to do continues for him, his provision continues for him, and he is safe from the tester.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3880,12119],"tks":"صحيح: رواه مسلم (1913: 163)."},{"num":7765,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رِبَاطُ شَهْرٍ خَيْرٌ مِنْ صِيَامِ دَهْرٍ، وَمَنْ مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ أَمِنَ مِنَ الْفَزَعِ الأَكْبَرِ، وَغُدِيَ عَلَيْهِ بِرِزْقِهِ وَرِيحٍ مِنَ الْجَنَّةِ، وَيَجْرِي عَلَيْهِ أَجْرُ الْمُرَابِطِ حَتَّى يَبْعَثَهُ اللَّهُ عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه الطبراني في الكبير –كما في جامع المسانيد والسنن (11882)- عن خير بن عرفة، عن عبد الله بن عبد الحكم، عن عصام بن إسماعيل، عن موسى بن ورقان، عن حنش بن عبد الله، عن أبي الدرداء فذكره.","grade":"حسن","chapter_ar":"باب فضل الرباط في سبيل الله عز وجل","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir, as cited in Jamiʿ al-Masanid wa al-Sunan (11050).","chapter_en":"The Virtue of Guarding the Frontier in the Path of Allah, Mighty and Majestic","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu al-Darda’ narrated that the Messenger of Allah ﷺ said: “Guarding the frontier for a month is better than fasting for a lifetime. Whoever dies while guarding the frontier in the path of Allah will be safe from the greatest terror, his provision and fragrance from Paradise will be brought to him in the morning, and the reward of one who guards the frontier will continue for him until Allah, Mighty and Majestic, raises him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير — كما في جامع المسانيد والسنن (11882)."},{"num":7766,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ: كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ إِلَّا الَّذِي مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ، فَإِنَّهُ يَنْمُو عَمَلُهُ إِلَى يَوْمِ الْقِيَامَةِ، وَيَأْمَنُ فِتْنَةَ الْقَبْرِ."],"takhrij":"صحيح: رواه أبو داود (2500)، والترمذي (1631)، وأحمد (23951)، وصحّحه ابن حبان (4624)، والحاكم (2/79، 144) كلهم من طريق حيوة بن شريح (وهو المصري) قال: أخبرني أبو هانئ حميد بن هانئ الخولاني، أن عمرو بن مالك الجنبي أخبره أنه سمع فضالة بن عبيد فذكره.","grade":"صحيح","chapter_ar":"باب فضل الرباط في سبيل الله عز وجل","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2500), al-Tirmidhi (1631), Ahmad (23951), graded authentic by Ibn Hibban (4624), and narrated by al-Hakim (2/79, 144).","chapter_en":"The Virtue of Guarding the Frontier in the Path of Allah, Mighty and Majestic","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Fadalah ibn ʿUbayd said: The Messenger of Allah ﷺ said: “Every deceased person has his deeds sealed, except the one who dies while guarding the frontier in the path of Allah. His deed will continue to grow for him until the Day of Resurrection, and he will be safe from the trial of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2500)، والترمذي (1631)، وأحمد (23951)، وصححه ابن حبان (4624)، والحاكم (2/79، 144)."},{"num":7767,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بن عَامِرٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ إِلَّا الْمُرَابِطَ فِي سَبِيلِ اللَّهِ، فَإِنَّهُ يُجْرَى لَهُ أَجْرُ عَمَلِهِ حَتَّى يُبْعَثَ، وَيُؤَمَّنُ مِنْ فَتَّانِ الْقَبْرِ."],"takhrij":"حسن: رواه أحمد (17359) عن عبد الله بن يزيد، حدثنا ابن لهيعة، حدثنا مشرح قال: سمعت عقبة بن عامر فذكر مثله.","grade":"حسن","chapter_ar":"باب فضل الرباط في سبيل الله عز وجل","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17359).","chapter_en":"The Virtue of Guarding the Frontier in the Path of Allah, Mighty and Majestic","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: I heard the Messenger of Allah ﷺ say: “Every deceased person has his deeds sealed, except the one who guards the frontier in the path of Allah. The reward of his deed continues for him until he is raised, and he is made safe from the testers of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3882],"tks":"حسن: رواه أحمد (17359)."},{"num":7768,"demo":false,"sanad":"","matn":["عن الْعِرْبَاضِ بن سَارِيَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُّ عَمَلٍ يَنْقَطِعُ عَنْ صَاحِبِهِ إِذَا مَاتَ، إِلَّا الْمُرَابِطَ فِي سَبِيلِ اللَّهِ، فَإِنَّهُ يُنْمَى لَهُ عَمَلُهُ، وَيُجْرَى عَلَيْهِ رِزْقُهُ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"حسن: رواه الطبراني في الكبير (18/ح 641)، والفسوي في المعرفة والتاريخ (2/348)، وابن أبي عاصم في الجهاد (296) كلهم من طرق عن أبي مطيع معاوية بن يحيى الأطرابلسي، عن بحير بن سعد، عن خالد بن معدان، عن جبير بن نفير، وكثير بن مرة، وعمرو بن الأسود، عن العرباض بن سارية فذكره.","grade":"حسن","chapter_ar":"باب فضل الرباط في سبيل الله عز وجل","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (18/256–257), al-Fasawi in al-Maʿrifah wa al-Tarikh (2/348), and Ibn Abi ʿAsim in al-Jihad (296).","chapter_en":"The Virtue of Guarding the Frontier in the Path of Allah, Mighty and Majestic","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Al-ʿIrbad ibn Sariyah said: The Messenger of Allah ﷺ said: “Every deed is cut off from its doer when he dies, except the one who guards the frontier in the path of Allah. His deed grows for him, and his provision continues for him until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (18/ح 641)، والفسوي في المعرفة والتاريخ (2/348)، وابن أبي عاصم في الجهاد (296)."},{"num":7769,"demo":false,"sanad":"","matn":["عَنْ مُجَاهِدٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ كَانَ فِي الرِّبَاطِ، فَفَزِعُوا إِلَى السَّاحِلِ، ثُمَّ قِيلَ: لَا بَأْسَ، فَانْصَرَفَ النَّاسُ، وَبَقِيَ أَبُو هُرَيْرَةَ وَاقِفا، فَمَرَّ بِهِ إِنْسَانٌ، فَقَالَ: مَا يُوقِفُكَ يَا أَبَا هُرَيْرَةَ؟ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَوْقِفُ سَاعَةٍ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ قِيَامِ لَيْلَةِ الْقَدْرِ عِنْدَ الْحَجَرِ الأَسْوَدِ."],"takhrij":"صحيح: رواه ابن حبان (4603)، والبيهقي في شعب الإيمان (4286) كلاهما من طريق عباس بن عبد الله الترقفي، حدثنا أبو عبد الرحمن المقرئ، حدثنا سعيد بن أبي أيوب، حدثني أبو الأسود محمد بن عبد الرحمن، عن مجاهد، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الرباط في سبيل الله عز وجل","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4603) and al-Bayhaqi in Shuʿab al-Iman (4286).","chapter_en":"The Virtue of Guarding the Frontier in the Path of Allah, Mighty and Majestic","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Mujahid narrated from Abu Hurayrah that he was guarding the frontier, and the people rushed in alarm to the coast. Then it was said: “There is no danger.” So the people left, while Abu Hurayrah remained standing. A person passed by him and said: “What is making you stand here, O Abu Hurayrah?” He said: I heard the Messenger of Allah ﷺ say: “Standing for an hour in the path of Allah is better than standing in prayer on the Night of Decree by the Black Stone.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (4603)، والبيهقي في شعب الإيمان (4286)."},{"num":7770,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَعِسَ عَبْدُ الدِّينَارِ، وَعَبْدُ الدِّرْهَمِ وَعَبْدُ الْخَمِيصَةِ، إِنْ أُعْطِيَ رَضِيَ، وَإِنْ لَمْ يُعْطَ سَخِطَ، تَعِسَ وَانْتَكَسَ، وَإِذَا شِيكَ فَلاَ انْتَقَشَ، طُوبَى لِعَبْدٍ آخِذٍ بِعِنَانِ فَرَسِهِ فِي سَبِيلِ اللَّهِ، أَشْعَثَ رَأْسُهُ مُغْبَرَّةٍ قَدَمَاهُ، إِنْ كَانَ فِي الْحِرَاسَةِ كَانَ فِي الْحِرَاسَةِ، وَإِنْ كَانَ فِي السَّاقَةِ كَانَ فِي السَّاقَةِ، إِنِ اسْتَأْذَنَ لَمْ يُؤْذَنْ لَهُ، وَإِنْ شَفَعَ لَمْ يُشَفَّعْ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2887) عن عمرو (هو ابن مروزق)، أخبرنا عبد الرحمن بن عبد الله بن دينار، عن أبيه، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل الحراسة في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2887).","chapter_en":"The Virtue of Guarding in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Wretched is the servant of the gold coin, the servant of the silver coin, and the servant of fine clothing. If he is given, he is pleased; and if he is not given, he is angry. May he be wretched and fall back; if he is pricked by a thorn, may he not find someone to remove it. Glad tidings to a servant holding the reins of his horse in the path of Allah, with disheveled hair and dusty feet. If he is assigned to guard, he guards; and if he is assigned to the rear guard, he remains in the rear guard. If he asks permission, he is not granted permission; and if he intercedes, his intercession is not accepted.”"]},"buhuth":{"en":["The phrase “if he is pricked by a thorn, may he not find someone to remove it” means: if a thorn strikes him, may he not find someone to take it out with tweezers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2887)."},{"num":7771,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: عَيْنَانِ لاَ تَمَسُّهُمَا النَّارُ، عَيْنٌ بَكَتْ مِنْ خَشْيَةِ اللَّهِ، وَعَيْنٌ بَاتَتْ تَحْرُسُ فِي سَبِيلِ اللَّهِ."],"takhrij":"حسن: رواه الترمذي (1639)، وابن أبي عاصم في الجهاد (146) من طريق شعيب بن رزيق أبو شيبة قال: حدثنا عطاء الخراساني، عن عطاء بن أبي رباح، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب فضل الحراسة في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1639), who graded it good; and Ibn Abi ʿAsim in al-Jihad (146).","chapter_en":"The Virtue of Guarding in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbas said: I heard the Messenger of Allah ﷺ say: “Two eyes will not be touched by the Fire: an eye that wept out of fear of Allah, and an eye that spent the night guarding in the path of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1639) وحسنه، وابن أبي عاصم في الجهاد (146)."},{"num":7772,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَيْنَانِ لَا تَمَسُّهُمَا النَّارُ: أَبَدًا: عَيْنٌ بَاتَتْ تَكْلُأُ الْمُسْلِمِينَ فِي سَبِيلِ اللَّهِ، وَعَيْنٌ بَكَتْ مِنْ خَشْيَةِ اللَّهِ."],"takhrij":"حسن: رواه أبو يعلى (4346) –ومن طريقه الضياء في المختارة (2198)، وابن أبي عاصم في الجهاد (147) كلاهما عن عمرو بن الضحاك بن مخلد، حدثنا أبي الضحاك بن مخلد، أخبرنا شبيب بن بشر، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب فضل الحراسة في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (4346), through whom al-Diya’ narrated it in al-Mukhtarah (2198), and by Ibn Abi ʿAsim in al-Jihad (147).","chapter_en":"The Virtue of Guarding in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Two eyes will not be touched by the Fire: an eye that spent the night guarding the Muslims in the path of Allah, and an eye that wept in solitude out of fear of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (4346) — ومن طريقه الضياء في المختارة (2198) — وابن أبي عاصم في الجهاد (147)."},{"num":7773,"demo":false,"sanad":"","matn":["عن زَيْدِ بن خَالِدٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ فَقَدْ غَزَا، وَمَنْ خَلَفَ غَازِيًا فِي سَبِيلِ اللَّهِ بِخَيْرٍ فَقَدْ غَزَا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2843)، ومسلم في الإمارة (1895: 136) كلاهما من طريق حسين المعلم، حدثنا يحيى بن أبي كثير، حدثني أبو سلمة بن عبد الرحمن، حدثني بُسر بن سعيد، حدثني زيد بن خالد فذكره.","grade":"متفق عليه","chapter_ar":"باب تقديم العون للجهاد إذا دعا إليه ولي الأمر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2843) and Muslim (1895:136).","chapter_en":"Providing Support for Striving When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Zayd ibn Khalid narrated that the Messenger of Allah ﷺ said: “Whoever equips one who goes out in the path of Allah has himself gone out; and whoever takes good care of the family and affairs of one who goes out in the path of Allah has himself gone out.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2843)، ومسلم (1895: 136)."},{"num":7774,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ إِلَى بَنِي لَِحْيَانَ: لِيَخْرُجْ مِنْ كُلِّ رَجُلَيْنِ رَجُلٌ. ثُمَّ قَالَ لِلْقَاعِدِ: أَيُّكُمْ خَلَفَ الْخَارِجَ فِي أَهْلِهِ وَمَالِهِ بِخَيْرٍ، كَانَ لَهُ مِثْلُ نِصْفِ أَجْرِ الْخَارِجِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1896: 138) عن سعيد بن منصور، حدثنا عبد الله بن وهب، أخبرني عمرو بن الحارث، عن يزيد بن أبي حبيب، عن يزيد بن أبي سعيد مولى المهري، عن أبيه، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب تقديم العون للجهاد إذا دعا إليه ولي الأمر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1896:138).","chapter_en":"Providing Support for Striving When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ sent word to Banu Lihyan: “Let one man go out from every two men.” Then he said to the one who stayed behind: “Whichever of you takes good care of the one who went out by looking after his family and wealth will have the equivalent of half the reward of the one who went out.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1896: 138)."},{"num":7775,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ قَالَ:  جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي أُبْدِعَ بِي فَاحْمِلْنِي. فَقَالَ: مَا عِنْدِي. فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَنَا أَدُلُّهُ عَلَى مَنْ يَحْمِلُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1893: 133) من طريق أبي معاوية، عن الأعمش، عن أبي عمرو الشيباني، عن أبي مسعود الأنصاري قال: فذكره.","grade":"صحيح","chapter_ar":"باب تقديم العون للجهاد إذا دعا إليه ولي الأمر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1893:133).","chapter_en":"Providing Support for Striving When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Masʿud al-Ansari said: A man came to the Prophet ﷺ and said: “My riding animal has failed me, so provide me with a mount.” He said: “I do not have anything.” A man said: “O Messenger of Allah, I can direct him to someone who will provide him with a mount.” The Messenger of Allah ﷺ said: “Whoever directs someone to good will have the like of the reward of the one who does it.”"]},"buhuth":{"en":["The phrase “my riding animal has failed me” means: my riding animal has perished or become unable to carry me."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1126],"tks":"صحيح: رواه مسلم (1893: 133)."},{"num":7776,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ:  أَنَّ فَتًى مِنْ أَسْلَمَ قَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أُرِيدُ الْغَزْوَ، وَلَيْسَ مَعِي مَا أَتَجَهَّزُ. قَالَ: ائْتِ فُلَانًا، فَإِنَّهُ قَدْ كَانَ تَجَهَّزَ فَمَرِضَ. فَأَتَاهُ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقْرِئُكَ السَّلَامَ، وَيَقُولُ: أَعْطِنِي الَّذِي تَجَهَّزْتَ بِهِ، قَالَ: يَا فُلَانَةُ، أَعْطِيهِ الَّذِي تَجَهَّزْتُ بِهِ، وَلَا تَحْبِسِي عَنْهُ شَيْئًا، فَوَاللهِ لَا تَحْبِسِي مِنْهُ شَيْئًا، فَيُبَارَكَ لَكِ فِيهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1894: 134) من طريق حماد بن سلمة، حدثنا ثابت، عن أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب تقديم العون للجهاد إذا دعا إليه ولي الأمر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1894:134).","chapter_en":"Providing Support for Striving When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Anas narrated that a young man from Aslam said: “O Messenger of Allah, I want to go out on campaign, but I do not have what I need to equip myself.” He said: “Go to so-and-so, for he had prepared himself but then became ill.” So he went to him and said: “The Messenger of Allah ﷺ sends you greetings of peace and says: Give me what you had prepared.” He said: “O so-and-so, give him what I had prepared, and do not withhold anything from him. By Allah, do not withhold anything from him, so that it may be blessed for you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1894: 134)."},{"num":7777,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ لَمْ يغزُ، أَوْ يُجَهِّزْ غَازِيًا، أَوْ يَخْلُفْ غَازِيًا فِي أَهْلِهِ بِخَيْرٍ أَصَابَهُ اللَّهُ سُبْحَانَهُ بِقَارِعَةٍ قَبْلَ يَوْمِ الْقِيَامَةِ."],"takhrij":"حسن: رواه أبو داود (2503)، وابن ماجه (2762)، والدارمي (2462) من طرق عن الوليد بن مسلم، حدثنا يحيى بن الحارث الذماري، عن القاسم بن عبد الرحمن، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب تقديم العون للجهاد إذا دعا إليه ولي الأمر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2503), Ibn Majah (2762), and al-Darimi (2462).","chapter_en":"Providing Support for Striving When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Umamah narrated that the Prophet ﷺ said: “Whoever neither goes out on campaign, nor equips one who goes out, nor takes good care of the family of one who goes out, Allah, Glorified is He, will strike him with a calamity before the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2503)، وابن ماجه (2762)، والدارمي (2462)."},{"num":7778,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَظَلَّ رَأْسَ غَازٍ، أَظَلَّهُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَمَنْ جَهَّزَ غَازِيًا حَتَّى يَسْتَقِلَّ، كَانَ لَهُ مِثْلُ أَجْرِهِ حَتَّى يَمُوتَ، - قَالَ: يُونُسُ: أَوْ يَرْجِعَ، - وَمَنْ بَنَى لِلَّهِ مَسْجِدًا يُذْكَرُ فِيهِ اسْمُ اللَّهِ تَعَالَى، بَنَى اللَّهُ لَهُ بِهِ بَيْتًا فِي الْجَنَّةِ."],"takhrij":"صحيح: رواه أحمد (126)، وابن ماجه ( 735، 2758)، وابن أبي شيبة (19902)، والحاكم (2447) من طرق عن ليث بن سعد، عن يزيد بن عبد الله بن أسامة بن الهاد، عن الوليد بن أبي الوليد، عن عثمان بن عبد الله بن سراقة، عن عمر بن الخطاب فذكره. واللفظ لأحمد ومنهم من اختصره.","grade":"صحيح","chapter_ar":"باب تقديم العون للجهاد إذا دعا إليه ولي الأمر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (126), Ibn Majah (2758, 735), Ibn Abi Shaybah (19902), and al-Hakim (2447).","chapter_en":"Providing Support for Striving When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: I heard the Messenger of Allah ﷺ say: “Whoever shades the head of one who goes out on campaign, Allah will shade him on the Day of Resurrection. Whoever equips one who goes out until he is fully ready will have the like of his reward until he dies or returns. And whoever builds a mosque for Allah, in which the name of Allah Most High is mentioned, Allah will build for him a house in Paradise because of it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (126)، وابن ماجه (2758، 735)، وابن أبي شيبة (19902)، والحاكم (2447)."},{"num":7779,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفْضَلُ الصَّدَقَاتِ ظِلُّ فُسْطَاطٍ فِي سَبِيلِ اللَّهِ، وَمَنِيحَةُ خَادِمٍ فِي سَبِيلِ اللَّهِ، أَوْ طَرُوقَةُ فَحْلٍ فِي سَبِيلِ اللَّهِ."],"takhrij":"حسن: رواه الترمذي (1627) عن زياد بن أيوب، حدثنا يزيد بن هارون، أخبرنا الوليد بن جميل، عن القاسم أبي عبد الرحمن، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب تقديم العون للجهاد إذا دعا إليه ولي الأمر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1627), who said: “A good, authentic, uncommon hadith.”","chapter_en":"Providing Support for Striving When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Umamah said: The Messenger of Allah ﷺ said: “The best forms of charity are the shade of a tent in the path of Allah, or lending a servant in the path of Allah, or providing a she-camel fit for breeding in the path of Allah.”"]},"buhuth":{"en":["The phrase “the shade of a tent” means giving a tent in the path of Allah so that those striving may take shade beneath it, or pitching a tent and gathering them in its shade. “Lending a servant in the path of Allah” means giving a servant to assist the one engaged in the campaign.","“A she-camel fit for breeding” means a she-camel suitable to be covered by a male camel, given to one who goes out so that he may ride it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1627)، وقال: حديث حسن صحيح غريب."},{"num":7780,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : حُرْمَةُ نِسَاءِ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ كَحُرْمَةِ أُمَّهَاتِهِمْ، وَمَا مِنْ رَجُلٍ مِنَ الْقَاعِدِينَ يَخْلُفُ رَجُلًا مِنَ الْمُجَاهِدِينَ فِي أَهْلِهِ، فَيَخُونُهُ فِيهِمْ إِلَّا وُقِفَ لَهُ يَوْمَ الْقِيَامَةِ، فَيَأْخُذُ مِنْ عَمَلِهِ مَا شَاءَ فَمَا ظَنُّكُمْ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1897: 139) عن أبي بكر بن أبي شيبة، حدثنا وكيع، عن سفيان، عن علقمة بن مرثد، عن سليمان بن بريدة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من التعرض لنساء المجاهدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1897:139).","chapter_en":"Warning Against Violating the Sanctity of the Wives of Those Who Go Out in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Messenger of Allah ﷺ said: “The sanctity of the wives of those who strive, for those who stay behind, is like the sanctity of their mothers. No man among those who stay behind is entrusted with the family of a man who strives, then betrays him regarding them, except that he will be made to stand before him on the Day of Resurrection, and he will take from his deeds whatever he wishes. So what do you think?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1897: 139)."},{"num":7781,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ عَبَسَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه الترمذي (1635) عن إسحاق بن منصور المروزي، أخبرنا حيوة بن شُريح الحمصي، عن بقية، عن بَحير بن سعد، عن خالد بن معدان، عن كثير بن مرة، عن عمرو بن عبسة فذكره.","grade":"صحيح","chapter_ar":"باب فضل من شاب شيبةً في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1635), who said: “This is a good, authentic, uncommon hadith.”","chapter_en":"The Virtue of One Whose Hair Turns Gray in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿAmr ibn ʿAbasah narrated that the Messenger of Allah ﷺ said: “Whoever has a gray hair in the path of Allah, it will be a light for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15423],"tks":"صحيح: رواه الترمذي (1635)، وقال: هذا حديث حسن صحيح غريب."},{"num":7782,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ، كَانَتْ نُورًا لَهُ يَوْمَ الْقِيَامَةِ، فَقَالَ رَجُلٌ عِنْدَ ذَلِكَ: فَإِنَّ رِجَالًا يَنْتِفُونَ الشَّيْبَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ شَاءَ فَلْيَنْتِفْ نُورَهُ.","وفي لفظ: من شاء ان ينتف شيبة –أو قال: نوره-."],"takhrij":"حسن: رواه ابن أبي عاصم في الجهاد (168)، والطبراني في الكبير (18/ح 783) من طرق عن وهب بن جرير بن حازم، حدثنا أبي، سمعت يحيى بن أيوب يحدث عن يزيد بن أبي حبيب، عن عبد العزيز بن أبي الصعبة، عن حنش (وهو الصنعاني)، عن فضالة بن عبيد فذكره.","grade":"حسن","chapter_ar":"باب فضل من شاب شيبةً في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi ʿAsim in al-Jihad (168), al-Tabarani in al-Kabir (18/304), and Ahmad (23952).","chapter_en":"The Virtue of One Whose Hair Turns Gray in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Fadalah ibn ʿUbayd narrated that the Prophet ﷺ said: “Whoever has a gray hair in the path of Allah, it will be a light for him on the Day of Resurrection.” A man then said: “But some men pluck out gray hairs.” The Messenger of Allah ﷺ said: “Then let him pluck out his light.” In another wording: “Whoever wishes to pluck out his gray hair — or he said: his light — then let him do so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الجهاد (168)، والطبراني في الكبير (18/304)، وأحمد (23952)."},{"num":7783,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ دَعَاهُ خَزَنَةُ الْجَنَّةِ -كُلُّ خَزَنَةِ باب- أي فُلْ هلُمَّ، قَالَ أَبُو بَكْرٍ: يَا رَسُولَ اللَّهِ ذَاكَ الَّذِي لاَ تَوَى عَلَيْهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنِّي لأَرْجُو أَنْ تَكُونَ مِنْهُمْ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2841)، ومسلم في الزكاة (1027: 86) كلاهما من طريق شيبان بن عبد الرحمن، عن يحيى بن أبي كثير، عن أبي سلمة بن عبد الرحمن أنه سمع أبا هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الإنفاق في سبيل الله تعالى إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2841) and Muslim (1027:86).","chapter_en":"The Virtue of Spending in the Path of Allah Most High When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Whoever spends two of a kind in the path of Allah will be called by the keepers of Paradise — the keepers of every gate: ‘O so-and-so, come!’” Abu Bakr said: “O Messenger of Allah, that is a person who will have no loss.” The Prophet ﷺ said: “I hope that you will be among them.”"]},"buhuth":{"en":["The phrase “two of a kind” means two things of any kind that are spent. The word “pair” may refer to one or to two, and here the intended meaning is one of each kind, as mentioned in Fath al-Bari (6/49). “O so-and-so” is a shortened form of “O person.” “That is a person who will have no loss” means no ruin or loss; it comes from a word meaning destruction, as Ibn al-Athir explained."]},"intro":{"ar":["قال الله تعالى:","(مَثَلُ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنبُلَةٍ مِائَةُ حَبَّةٍ ۗ وَاللَّهُ يُضَاعِفُ لِمَن يَشَاءُ ۗ وَاللَّهُ وَاسِعٌ عَلِيمٌ ۝ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ ثُمَّ لَا يُتْبِعُونَ مَا أَنفَقُوا مَنًّا وَلَا أَذًى ۙ لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) [البقرة: ٢٦١-٢٦٢]"],"en":["Allah Most High said:","“The example of those who spend their wealth in the path of Allah is like a grain that grows seven ears; in every ear are one hundred grains. And Allah multiplies for whom He wills, and Allah is All-Encompassing, All-Knowing. Those who spend their wealth in the path of Allah, then do not follow what they spent with reminders of generosity or harm, will have their reward with their Lord, and there will be no fear upon them, nor will they grieve.” [al-Baqarah: 261–262]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16270],"tks":"متفق عليه: رواه البخاري (2841)، ومسلم (1027: 86)."},{"num":7784,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَى الْمِنْبَرِ، فَقَالَ: إِنَّمَا أَخْشَى عَلَيْكُمْ مِنْ بَعْدِي مَا يُفْتَحُ عَلَيْكُمْ مِنْ بَرَكَاتِ الأَرْضِ، ثُمَّ ذَكَرَ زَهْرَةَ الدُّنْيَا، فَبَدَأَ بِإِحْدَاهُمَا وَثَنَّى بِالأُخْرَى، فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، أَوَيَأْتِي الْخَيْرُ بِالشَّرِّ؟ فَسَكَتَ عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، قُلْنَا: يُوحَى إِلَيْهِ وَسَكَتَ النَّاسُ كَأَنَّ عَلَى رُءُوسِهِمِ الطَّيْرَ، ثُمَّ إِنَّهُ مَسَحَ عَنْ وَجْهِهِ الرُّحَضَاءَ، فَقَالَ: أَيْنَ السَّائِلُ آنِفًا؟ أَوْ خير هُوَ،-ثَلاَثًا-، إِنَّ الْخَيْرَ لاَ يَأْتِي إِلاَّ بِالْخَيْرِ، وَإِنَّهُ كُلَّمَا يُنْبِتُ الرَّبِيعُ مَا يَقْتُلُ حَبَطًا أَوْ يُلِمُّ إِلاَّ آكِلَةَ الْخَضِرِ كُلَّمَا أَكَلَتْ، حَتَّى إِذَا امْتَلأَتْ خَاصِرَتَاهَا اسْتَقْبَلَتِ الشَّمْسَ، فَثَلَطَتْ وَبَالَتْ ثُمَّ رَتَعَتْ، وَإِنَّ هَذَا الْمَالَ خَضِرَةٌ حُلْوَةٌ، وَنِعْمَ صَاحِبُ الْمُسْلِمِ لِمَنْ أَخَذَهُ بِحَقِّهِ فَجَعَلَهُ فِي سَبِيلِ اللَّهِ وَالْيَتَامَى وَالْمَسَاكِينِ وابن السبيل، وَمَنْ لَمْ يَأْخُذْهُ بِحَقِّهِ فَهْوَ كَالآكِلِ الَّذِي لاَ يَشْبَعُ، وَيَكُونُ عَلَيْهِ شَهِيدًا يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (2842)، ومسلم في الزكاة (1052: 123) كلاهما من طريق هلال بن أبي ميمونة، عن عطاء بن يسار، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الإنفاق في سبيل الله تعالى إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2842) and Muslim (1052:123).","chapter_en":"The Virtue of Spending in the Path of Allah Most High When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ stood on the pulpit and said: “What I fear for you after me is what will be opened for you of the blessings of the earth.” Then he mentioned the splendor of the world, beginning with one matter and then mentioning the other. A man stood and said: “O Messenger of Allah, can good bring evil?” The Prophet ﷺ remained silent, and we said: Revelation is coming to him. The people became silent, as if birds were perched on their heads. Then he wiped the sweat from his face and said: “Where is the questioner just now? Is it good? — three times — Good brings only good. Among what spring causes to grow is that which kills by bloating or nearly kills, except the animal that eats greenery: it eats until its flanks are full, then faces the sun, passes dung and urine, and then grazes again. This wealth is green and sweet. How excellent is the companion of the Muslim when he takes it rightfully and places it in the path of Allah, for orphans, the poor, and the traveler. But whoever takes it without right is like one who eats and is never satisfied, and it will be a witness against him on the Day of Resurrection.”"]},"buhuth":{"en":["“Bloating” refers to livestock eating too much pasture until their bellies swell, which can lead to their death. “Nearly kills” means it comes close to destruction.","Al-Azhari said: “This report is difficult to grasp unless reflected upon. It contains two parables: one for the one who goes to excess in gathering worldly wealth and withholding its due, and another for the one who takes it moderately and benefits from it. His saying, ‘Among what spring causes to grow is that which kills by bloating,’ is a parable for the excessive person who takes it without right. Spring produces the best herbs and grass, and livestock eat too much of it until their bellies swell beyond endurance, their intestines rupture, and they die. Likewise, one who gathers worldly wealth unlawfully and withholds the rights owed from it is destroyed in the Hereafter by entering the Fire. As for the moderate person, his parable is in the Prophet’s saying: ‘except the animal that eats greenery…’ to the end. The greenery is not the strongest spring growth, but the later herbage grazed by livestock after the first growth has withered. The Prophet ﷺ gave the grazing animal as a parable for one who is moderate in taking and gathering worldly wealth, and whose greed does not drive him to take it unlawfully. He is saved from its harm, just as the animal that eats greenery is saved.” See: al-Dibaj by al-Suyuti."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2842)، ومسلم (1052: 123)."},{"num":7785,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ قَالَ:  جَاءَ رَجُلٌ بِنَاقَةٍ مَخْطُومَةٍ، فَقَالَ: هَذِهِ فِي سَبِيلِ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَكَ بِهَا يَوْمَ الْقِيَامَةِ سَبْعُمِائَةِ نَاقَةٍ، كُلُّهَا مَخْطُومَةٌ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1892: 132) عن إسحاق بن إبراهيم الحنظلي، أخبرنا جرير، عن الأعمش، عن أبي عمرو الشيباني، عن أبي مسعود الأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب فضل الإنفاق في سبيل الله تعالى إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1892:132).","chapter_en":"The Virtue of Spending in the Path of Allah Most High When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Masʿud al-Ansari said: A man came with a she-camel that had a halter and said: “This is in the path of Allah.” The Messenger of Allah ﷺ said: “Because of it, you will have seven hundred she-camels on the Day of Resurrection, all of them with halters.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1892: 132)."},{"num":7786,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَفْضَلُ دِينَارٍ يُنْفِقُهُ الرَّجُلُ: دِينَارٌ يُنْفِقُهُ عَلَى عِيَالِهِ، وَدِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ، وَدِينَارٌ يُنْفِقُهُ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الزكاة (994) من طريقين عن حماد بن زيد، حدثنا أيوب، عن أبي قلابة، عن أبي أسماء، عن ثوبان فذكره.","grade":"صحيح","chapter_ar":"باب فضل الإنفاق في سبيل الله تعالى إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (994).","chapter_en":"The Virtue of Spending in the Path of Allah Most High When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Thawban said: The Messenger of Allah ﷺ said: “The best dinar a man spends is a dinar he spends on his family, a dinar he spends on his riding animal in the path of Allah, and a dinar he spends on his companions in the path of Allah.”"]}},"tuhfa":{},"full":1,"rep":[4168],"tks":"صحيح: رواه مسلم (994)."},{"num":7787,"demo":false,"sanad":"","matn":["عَنْ خُرَيْمِ بْنِ فَاتِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ، تُضَاعَفُ بِسَبْعِ مِائَةِ ضِعْفٍ."],"takhrij":"حسن: رواه الترمذي (1625)، وأحمد (19036، 19038)، وابن أبي عاصم في الجهاد (71)، وصحّحه ابن حبان (4647)، والحاكم (2441) كلهم من طرق عن زائدة (هو ابن قدامة)- ورواه أحمد (19035)، وابن حبان (6171) من طريق شيبان بن عبد الرحمن النحوي- ورواه النسائي في المجتبى (3186)، وفي الكبرى (4395)، وابن أبي عاصم في الجهاد (72) من طريق سفيان (هو الثوري)- ثلاثتهم عن الركين بن الربيع، عن أبيه، عن عمه يُسير بن عميلة، عن خريم بن فاتك فذكره. ومنهم من رواه مطولا.","grade":"حسن","chapter_ar":"باب فضل الإنفاق في سبيل الله تعالى إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1625), who graded it good; Ahmad (19038, 19036); and Ibn Abi ʿAsim in al-Jihad (71).","chapter_en":"The Virtue of Spending in the Path of Allah Most High When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Khuraym ibn Fatik al-Asadi said: The Messenger of Allah ﷺ said: “Whoever spends an expenditure in the path of Allah, it is written for him as seven hundred times its like.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1625) وحسنه، وأحمد (19038، 19036)، وابن أبي عاصم في الجهاد (71)."},{"num":7788,"demo":false,"sanad":"","matn":["عَنْ صَعْصَعَةَ بْنِ مُعَاوِيَةَ، قَالَ: لَقِيتُ أَبَا ذَرٍّ قَالَ: قُلْتُ: حَدِّثْنِي. قَالَ: نَعَمْ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ عَبْدٍ مُسْلِمٍ يُنْفِقُ مِنْ كُلِّ مَالٍ لَهُ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ إِلاَّ اسْتَقْبَلَتْهُ حَجَبَةُ الْجَنَّةِ كُلُّهُمْ يَدْعُوهُ إِلَى مَا عِنْدَهُ. قُلْتُ: وَكَيْفَ ذَلِكَ؟ قَالَ: إِنْ كَانَتْ إِبِلاً فَبَعِيرَيْنِ، وَإِنْ كَانَتْ بَقَرًا فَبَقَرَتَيْنِ."],"takhrij":"صحيح: رواه النسائي (3185)، وأحمد (21413)، وصحّحه ابن حبان (4643)، والحاكم (2439) من طرق عن الحسن، عن صعصعة بن معاوية فذكره.","grade":"صحيح","chapter_ar":"باب فضل الإنفاق في سبيل الله تعالى إذا دعا إليه الإمام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3185), Ahmad (21413), and graded authentic by Ibn Hibban (4643) and al-Hakim (2439).","chapter_en":"The Virtue of Spending in the Path of Allah Most High When the Leader Calls to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Saʿsʿah ibn Muʿawiyah said: I met Abu Dharr and said: “Narrate to me.” He said: Yes. The Messenger of Allah ﷺ said: “There is no Muslim servant who spends two of each kind of his wealth in the path of Allah except that the gatekeepers of Paradise will receive him, each of them calling him to what is with him.” I said: “How is that?” He said: “If it is camels, then two camels; and if it is cattle, then two cows.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (3185)، وأحمد (21413)، وصححه ابن حبان (4643)، والحاكم (2439)."},{"num":7789,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، - هُوَ ابْنُ عَمْرٍو، - عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَفْلَةٌ كَغَزْوَةٍ."],"takhrij":"صحيح: رواه أبو داود (2487)، وأحمد (6625) والحاكم (2399)، والبيهقي (9/28) من طرق عن الليث بن سعد، حدثني حيوة بن شريح، عن ابن شُفي الأصبحي، عن أبيه شُفي بن ماتع، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب فضل القفول عن الغزو","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2487), Ahmad (6625), al-Hakim (2399), and al-Bayhaqi (9/28).","chapter_en":"The Virtue of Returning from Campaign","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr narrated that the Prophet ﷺ said: “A return is like a campaign.”"]},"buhuth":{"en":["Al-Khattabi said in Maʿalim al-Sunan (3/358), commenting on this hadith: This may carry two meanings.","The first is that it refers to returning from campaign and going back to one’s homeland; meaning that the reward of the fighter in returning to his family is like his reward in going forth to the campaign. That is because preparing the one who goes out may bring hardship to his family, and his return removes harm from them, allows the soul to rest, and prepares him with strength to return again.","The second meaning is that it refers to “following up,” meaning that he returns again along the same route from which he had come back, even if he does not meet an enemy or witness fighting. An army may do this after returning from its campaign for one of two reasons:","First, when the enemy sees that they have left their area, they feel safe and come out from their hiding places; then, if the army returns to the enemy’s land, they gain the opportunity to raid them.","Second, when the army openly returns from its campaign, they are not safe from the enemy following their trail and attacking them while they are unaware; so the army, or some of them, may strengthen their position by returning along their tracks in parts of the road. If the enemy is pursuing, they are ready to meet them; otherwise, they remain safe and preserve the spoils with them. End quote."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2487)، وأحمد (6625)، والحاكم (2399)، والبيهقي (9/28)."},{"num":7790,"demo":false,"sanad":"","matn":["عن أُمِّ حَرَامٍ بِنْتِ مِلْحَانَ قَالَتْ: نَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا قَرِيبًا مِنِّي، ثُمَّ اسْتَيْقَظَ يَتَبَسَّمُ. فَقُلْتُ: مَا أَضْحَكَكَ؟ قَالَ: أُنَاسٌ مِنْ أُمَّتِي عُرِضُوا عَلَىَّ، يَرْكَبُونَ هَذَا الْبَحْرَ الأَخْضَرَ، كَالْمُلُوكِ عَلَى الأَسِرَّةِ. قَالَتْ: فَادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ. فَدَعَا لَهَا، ثُمَّ نَامَ الثَّانِيَةَ، فَفَعَلَ مِثْلَهَا، فَقَالَتْ: مِثْلَ قَوْلِهَا، فَأَجَابَهَا مِثْلَهَا. فَقَالَتِ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ. فَقَالَ: أَنْتِ مِنَ الأَوَّلِينَ. فَخَرَجَتْ مَعَ زَوْجِهَا عُبَادَةَ بْنِ الصَّامِتِ غَازِيًا أَوَّلَ مَا رَكِبَ الْمُسْلِمُونَ الْبَحْرَ مَعَ مُعَاوِيَةَ، فَلَمَّا انْصَرَفُوا مِنْ غَزْوِهِمْ قَافِلِينَ، فَنَزَلُوا الشَّأْمَ، فَقُرِّبَتْ إِلَيْهَا دَابَّةٌ لِتَرْكَبَهَا، فَصَرَعَتْهَا، فَمَاتَتْ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير ( 2799، 2800)، ومسلم في الإمارة (1912: 161) كلاهما من طريق يحيى بن سعيد، عن محمد بن يحيى بن حبان، عن أنس بن مالك عن خالته أم حرام بنت ملحان فذكرته.","grade":"متفق عليه","chapter_ar":"باب فضل الغزو في البحر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2799, 2800) and Muslim (1912:161).","chapter_en":"The Virtue of Campaigning by Sea","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Umm Haram bint Milhan said: The Prophet ﷺ slept one day near me, then woke up smiling. I said: “What has made you smile?” He said: “People from my nation were shown to me, riding this green sea like kings upon thrones.” She said: “Supplicate to Allah to make me among them.” So he supplicated for her. Then he slept a second time and did the same. She said the same words, and he gave the same response. She said: “Supplicate to Allah to make me among them.” He said: “You are among the first.” She then went out with her husband ʿUbadah ibn al-Samit on campaign, in the first naval expedition undertaken by the Muslims with Muʿawiyah. When they returned from their campaign and came down in Syria, a riding animal was brought near for her to mount; it threw her down, and she died."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10444],"tks":"متفق عليه: رواه البخاري (2799، 2800)، ومسلم (1912: 161)."},{"num":7791,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَرَامٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: الْمَائِدُ فِي الْبَحْرِ الَّذِي يُصِيبُهُ الْقَىْءُ لَهُ أَجْرُ شَهِيدٍ، وَالْغَرِقُ لَهُ أَجْرُ شَهِيدَيْنِ."],"takhrij":"حسن: رواه أبو داود (2494)، وابن أبي عاصم في الجهاد (285-286) من طرق عن مروان بن معاوية، حدثنا هلال بن ميمون الرملي، عن أبي ثابت يعلى بن شداد، عن أم حرام فذكرته.","grade":"حسن","chapter_ar":"باب فضل الغزو في البحر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2493), and Ibn Abi ʿAsim in al-Jihad (285–286).","chapter_en":"The Virtue of Campaigning by Sea","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Umm Haram narrated that the Prophet ﷺ said: “The one who becomes seasick at sea and is struck by vomiting has the reward of a martyr, and the one who drowns has the reward of two martyrs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2494)، وابن أبي عاصم في الجهاد (285-286)."},{"num":7792,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ مَاتَ وَلَمْ يَغْزُ، وَلَمْ يُحَدِّثْ بِهِ نَفْسَهُ، مَاتَ عَلَى شُعْبَةٍ مِنْ نِفَاقٍ.","قَالَ عَبْدُ اللهِ بْنُ الْمُبَارَكِ: فَنُرَى أَنَّ ذَلِكَ كَانَ عَلَى عَهْدِ رَسُولِ اللهِ صلى الله عليه وسلم."],"takhrij":"صحيح: رواه مسلم في الإمارة (1910: 158) عن محمد بن عبد الرحمن بن سهم الأنطاكي، أخبرنا عبد الله بن المبارك، عن وهيب المكي، عن عمر بن محمد بن المنكدر، عن سمي، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ذم من لم يحدث نفسه بالغزو","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1910:158).","chapter_en":"Censure of One Who Does Not Even Intend Campaigning Within Himself","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever dies without having gone out on campaign, and without having intended it within himself, dies upon a branch of hypocrisy.” ʿAbdullah ibn al-Mubarak said: We hold that this was during the time of the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1910: 158)."},{"num":7793,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي غَزَاةٍ فَقَالَ: إِنَّ أَقْوَامًا بِالْمَدِينَةِ خَلْفَنَا، مَا سَلَكْنَا شِعْبًا وَلاَ وَادِيًا إِلاَّ وَهُمْ مَعَنَا فِيهِ، حَبَسَهُمُ الْعُذْرُ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2839) عن سليمان بن حرب، حدثنا حماد بن زيد، عن حميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ثواب من حبسه العذر عن الغزو","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2839).","chapter_en":"The Reward of One Prevented from Campaigning by a Valid Excuse","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ was on a campaign and said: “There are people in Medina behind us; we have not traveled through any mountain pass or valley except that they are with us in it. They were held back by an excuse.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2839)."},{"num":7794,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ فَقَالَ: إِنَّ بِالْمَدِينَةِ لَرِجَالًا مَا سِرْتُمْ مَسِيرًا وَلَا قَطَعْتُمْ وَادِيًا إِلَّا كَانُوا مَعَكُمْ، حَبَسَهُمُ الْمَرَضُ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1911: 159) عن عثمان بن أبي شيبة، حدثنا جرير، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ثواب من حبسه العذر عن الغزو","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1911:159).","chapter_en":"The Reward of One Prevented from Campaigning by a Valid Excuse","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We were with the Prophet on a campaign, and he said: “In Medina there are men; you have not traveled any distance nor crossed any valley except that they were with you. Illness held them back.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1911: 159)."},{"num":7795,"demo":false,"sanad":"","matn":["عن أُمِّ حَرَامٍ أَنَّهَا سَمِعَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَوَّلُ جَيْشٍ مِنْ أُمَّتِي يَغْزُونَ الْبَحْرَ قَدْ أَوْجَبُوا. قَالَتْ أُمُّ حَرَامٍ: قُلْتُ: يَا رَسُولَ اللَّهِ أَنَا فِيهِمْ. قَالَ: أَنْتِ فِيهِمْ. ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَّلُ جَيْشٍ مِنْ أُمَّتِي يَغْزُونَ مَدِينَةَ قَيْصَرَ مَغْفُورٌ لَهُمْ. فَقُلْتُ: أَنَا فِيهِمْ يَا رَسُولَ اللَّهِ. قَالَ: لاَ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2924)، عن إسحاق بن يزيد الدمشقي، حدثنا يحيى بن حمزة، حدثني ثور بن يزيد، عن خالد بن معدان، أن عمير بن الأسود العنسي حدثه أنه أتى عبادة بن الصامت وهو نازل في ساحة حمص، وهو في بناء له ومعه أم حرام، قال عمير: فحدثتنا أم حرام فذكرته.","grade":"صحيح","chapter_ar":"باب فضل أول جيش يغزو مدينة قيصر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2924).","chapter_en":"The Virtue of the First Army to Campaign Against the City of Caesar","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Umm Haram narrated that she heard the Prophet ﷺ say: “The first army from my nation to campaign by sea has made Paradise obligatory for itself.” Umm Haram said: I said, “O Messenger of Allah, am I among them?” He said: “You are among them.” Then the Prophet ﷺ said: “The first army from my nation to campaign against the city of Caesar will be forgiven.” I said: “Am I among them, O Messenger of Allah?” He said: “No.”"]},"buhuth":{"en":["The phrase “the city of Caesar” means Constantinople. The first to campaign against it was Yazid ibn Muʿawiyah in the year 52 AH. It was also said that the city of Caesar means Homs, but the first view is correct. See Fath al-Bari (6/102–103)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10081],"tks":"صحيح: رواه البخاري (2924)."},{"num":7796,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عِصَابَتَانِ مِنْ أُمَّتِي أَحْرَزَهُمُ اللهُ مِنَ النَّارِ: عِصَابَةٌ تَغْزُو الْهِنْدَ، وَعِصَابَةٌ تَكُونُ مَعَ عِيسَى ابْنِ مَرْيَمَ."],"takhrij":"حسن: رواه النسائي (3175) عن محمد بن عبد الله بن عبد الرحيم، قال: حدثنا أسد ابن موسى قال: حدثنا بقية قال: حدثني أبو بكر الزبيدي، عن أخيه محمد بن الوليد، عن لقمان بن عامر، عن عبد الأعلى بن عدي البهراني، عن ثوبان فذكره.","grade":"حسن","chapter_ar":"باب فضل العصابة التي تغزو الهند","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3175) and Imam Ahmad (22396).","chapter_en":"The Virtue of the Group That Campaigns Against India","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Thawban, the freedman of the Messenger of Allah ﷺ, narrated that the Messenger of Allah ﷺ said: “Two groups from my nation will be protected by Allah from the Fire: a group that campaigns against India, and a group that will be with ʿIsa ibn Maryam.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10082],"tks":"حسن: رواه النسائي (3175)، والإمام أحمد (22396)."},{"num":7797,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: وَعَدَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ الْهِنْدِ، فَإِنْ أَدْرَكْتُهَا أُنْفِقْ فِيهَا نَفْسِي وَمَالِي، فَإِنْ أُقْتَلْ كُنْتُ مِنْ أَفْضَلِ الشُّهَدَاءِ، وَإِنْ أَرْجِعْ فَأَنَا أَبُو هُرَيْرَةَ الْمُحَرَّرُ."],"takhrij":"حسن: رواه النسائي (3173، 3174)، وأحمد (7128)، والحاكم (6177) كلهم من طريق سيار، عن جبر بن عبيدة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب فضل العصابة التي تغزو الهند","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3173, 3174), Ahmad (7128), al-Hakim (6177), and Ibn Abi ʿAsim in al-Jihad (291).","chapter_en":"The Virtue of the Group That Campaigns Against India","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ promised us the campaign of India. If I live to see it, I will spend my life and wealth in it. If I am killed, I will be among the best of martyrs; and if I return, then I am Abu Hurayrah, the freed one."]},"buhuth":{"en":["The campaign against India occurred as the Prophet ﷺ said. The Muslims began campaigning in India during the time of Muʿawiyah in the year 44 AH, then the campaigns continued at the hands of Muhammad ibn al-Qasim, Mahmud ibn Sabuktakin, and others, until India became part of the lands of Islam. It remained under Muslim rule for eight centuries, until British colonial rule took control of it in 1857 CE, during the reign of the last king of India, Bahadur Shah Zafar, who was born in 1775 CE and died in 1862 CE in exile in Rangoon, the capital of Burma."]}},"tuhfa":{},"voc":["seerah",1723],"full":1,"dr":1,"tks":"حسن: رواه النسائي (3173، 3174)، وأحمد (7128)، والحاكم (6177)، وابن أبي عاصم في الجهاد (291)."},{"num":7798,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَجُلاً، قَالَ: يَا رَسُولَ اللَّهِ ائْذَنْ لِي فِي السِّيَاحَةِ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ سِيَاحَةَ أُمَّتِي الْجِهَادُ فِي سَبِيلِ اللَّهِ."],"takhrij":"حسن: رواه أبو داد (2486)، والحاكم (2398)، والبيهقي (18506) من طريق محمد بن عثمان التنوخي أبي الجماهر، حدثنا الهيثم بن حميد، أخبرني العلاء بن الحارث، عن القاسم أبي عبد الرحمن، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب إن سياحة هذه الأمة الجهاد في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2486), al-Hakim (2398), and al-Bayhaqi (9/161).","chapter_en":"The Spiritual Journey of This Nation Is Jihad in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في فضائل الجهاد","group_en":"Collection of Chapters Concerning the Virtues of Striving in the Path of Allah","part_no":43,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abu Umamah narrated that a man said: “O Messenger of Allah, permit me to travel in spiritual wandering.” The Prophet ﷺ said: “The spiritual journey of my nation is jihad in the path of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12517],"tks":"حسن: رواه أبو داود (2486)، والحاكم (2398)، والبيهقي (18506)."},{"num":7799,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: الرَّجُلُ يُقَاتِلُ لِلْمَغْنَمِ، وَالرَّجُلُ يُقَاتِلُ لِلذِّكْرِ، وَالرَّجُلُ يُقَاتِلُ لِيُرَى مَكَانُهُ، فَمَنْ فِي سَبِيلِ اللَّهِ؟ قَالَ: مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ."],"takhrij":"متفق عليه: رواه رواه البخاري في الجهاد (2810)، ومسلم في الإمارة (1904: 149) كلاهما من طريق شعبة، عن عمرو بن مرة قال: سمعت أبا وائل قال: حدثنا أبو موسى الأشعري فذكره.","grade":"متفق عليه","chapter_ar":"باب من قاتل لتكون كلمة الله هي العليا","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2810) and Muslim (1904:149).","chapter_en":"One Who Fights So That the Word of Allah May Be Supreme","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في أحكام الجهاد وآدابه","group_en":"Collection of What Has Been Narrated Concerning the Rulings and Etiquette of Jihad","part_no":43,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: A man came to the Prophet ﷺ and said: “A man fights for spoils, another fights to be remembered, and another fights so that his position may be seen. Which of them is in the path of Allah?” He said: “Whoever fights so that the word of Allah may be supreme is in the path of Allah.”"]}},"tuhfa":{},"full":1,"rep":[12383,12471],"tks":"متفق عليه: رواه البخاري (2810)، ومسلم (1904: 149)."}]);